const GENERIC_HYPER_RUNTIME_POST_MD_ENGINE_FLAG: &str =
    "--post-md-aggregation=preserve-lane-default";

fn canonical_hyper_runtime_post_md_engine_flag(policy: &PostMdAggregationPolicyV1) -> &'static str {
    match policy {
        PostMdAggregationPolicyV1::PreserveLaneDefault => {
            "--post-md-aggregation=preserve-lane-default"
        }
        PostMdAggregationPolicyV1::Full => "--post-md-aggregation=full",
        PostMdAggregationPolicyV1::Skip => "--post-md-aggregation=skip",
    }
}

fn canonical_hyper_runtime_therm_surface_engine_flag(
    policy: &ThermSurfacePolicyV1,
) -> &'static str {
    match policy {
        ThermSurfacePolicyV1::PreserveLaneDefault => {
            "--prism-therm-site-surface=preserve-lane-default"
        }
        ThermSurfacePolicyV1::Clusters => "--prism-therm-site-surface=clusters",
        ThermSurfacePolicyV1::Lattice => "--prism-therm-site-surface=lattice",
    }
}

fn resolved_hyper_runtime_therm_engine_flags(
    policy: Option<&ThermAndPostMdPolicyV1>,
) -> (&'static str, &'static str) {
    policy
        .map(|policy| {
            (
                canonical_hyper_runtime_post_md_engine_flag(&policy.effective_post_md_aggregation),
                canonical_hyper_runtime_therm_surface_engine_flag(&policy.effective_therm_surface),
            )
        })
        .unwrap_or((
            GENERIC_HYPER_RUNTIME_POST_MD_ENGINE_FLAG,
            "--prism-therm-site-surface=preserve-lane-default",
        ))
}

#[derive(Clone, Debug)]
enum Value {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

impl Value {
    fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(map) => map.get(key),
            _ => None,
        }
    }

    fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(value) => Some(*value),
            _ => None,
        }
    }

    fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(value) => Some(value.as_str()),
            _ => None,
        }
    }

    fn as_u64(&self) -> Option<u64> {
        match self {
            Value::Number(value) => value.parse().ok(),
            _ => None,
        }
    }

    fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Number(value) => value.parse().ok(),
            _ => None,
        }
    }

    fn as_array_len(&self) -> Option<u64> {
        match self {
            Value::Array(values) => Some(values.len() as u64),
            _ => None,
        }
    }

    fn as_array(&self) -> Option<&[Value]> {
        match self {
            Value::Array(values) => Some(values),
            _ => None,
        }
    }

    fn to_pretty_json(&self) -> String {
        let mut out = String::new();
        self.write_json(&mut out, 0, true);
        out.push('\n');
        out
    }

    fn write_json(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Value::Null => out.push_str("null"),
            Value::Bool(value) => out.push_str(if *value { "true" } else { "false" }),
            Value::Number(value) => out.push_str(value),
            Value::String(value) => {
                out.push('"');
                json_escape_into(out, value);
                out.push('"');
            }
            Value::Array(values) => {
                out.push('[');
                for (idx, value) in values.iter().enumerate() {
                    if idx > 0 {
                        out.push(',');
                    }
                    if pretty {
                        out.push('\n');
                        push_indent(out, indent + 2);
                    }
                    value.write_json(out, indent + 2, pretty);
                }
                if pretty && !values.is_empty() {
                    out.push('\n');
                    push_indent(out, indent);
                }
                out.push(']');
            }
            Value::Object(map) => {
                out.push('{');
                for (idx, (key, value)) in map.iter().enumerate() {
                    if idx > 0 {
                        out.push(',');
                    }
                    if pretty {
                        out.push('\n');
                        push_indent(out, indent + 2);
                    }
                    out.push('"');
                    json_escape_into(out, key);
                    out.push_str(if pretty { "\": " } else { "\":" });
                    value.write_json(out, indent + 2, pretty);
                }
                if pretty && !map.is_empty() {
                    out.push('\n');
                    push_indent(out, indent);
                }
                out.push('}');
            }
        }
    }
}

fn push_indent(out: &mut String, indent: usize) {
    for _ in 0..indent {
        out.push(' ');
    }
}

/// Convert a `serde_json::Value` (produced by the serde-derived provenance
/// structs in `prismcode::runtime_provenance`) into this binary's hand-rolled
/// `Value` so PROCESS-PROVEN provenance blocks can be embedded verbatim into the
/// emitted prismos JSON surfaces. Numbers are carried as their canonical string
/// form (matching `Value::Number(String)`).
fn serde_to_value(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::Null,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => Value::Number(n.to_string()),
        serde_json::Value::String(s) => Value::String(s.clone()),
        serde_json::Value::Array(a) => Value::Array(a.iter().map(serde_to_value).collect()),
        serde_json::Value::Object(o) => Value::Object(
            o.iter()
                .map(|(k, val)| (k.clone(), serde_to_value(val)))
                .collect(),
        ),
    }
}

fn json_escape_into(out: &mut String, value: &str) {
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => {
                let _ = write!(out, "\\u{:04x}", ch as u32);
            }
            ch => out.push(ch),
        }
    }
}

fn j_null() -> Value {
    Value::Null
}

fn j_bool(value: bool) -> Value {
    Value::Bool(value)
}

fn j_str(value: impl Into<String>) -> Value {
    Value::String(value.into())
}

fn j_num(value: impl ToString) -> Value {
    Value::Number(value.to_string())
}

fn j_opt_i32(value: Option<i32>) -> Value {
    value.map(j_num).unwrap_or(Value::Null)
}

fn j_opt_string(value: Option<String>) -> Value {
    value.map(j_str).unwrap_or(Value::Null)
}

fn j_array(values: Vec<Value>) -> Value {
    Value::Array(values)
}

fn j_string_array(values: &[&str]) -> Value {
    Value::Array(values.iter().map(|value| j_str(*value)).collect())
}

