fn j_obj(entries: Vec<(&str, Value)>) -> Value {
    Value::Object(
        entries
            .into_iter()
            .map(|(key, value)| (key.to_string(), value))
            .collect(),
    )
}

fn j_path_opt(value: Option<&Path>) -> Value {
    value
        .map(|path| j_str(path.display().to_string()))
        .unwrap_or(Value::Null)
}

fn j_u64_map(map: &BTreeMap<String, u64>) -> Value {
    Value::Object(
        map.iter()
            .map(|(key, value)| (key.clone(), j_num(*value)))
            .collect(),
    )
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        Self {
            input: input.as_bytes(),
            pos: 0,
        }
    }

    fn parse(mut self) -> Result<Value, String> {
        let value = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.input.len() {
            return Err("trailing JSON bytes".to_string());
        }
        Ok(value)
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'n') => {
                self.expect_lit(b"null")?;
                Ok(Value::Null)
            }
            Some(b't') => {
                self.expect_lit(b"true")?;
                Ok(Value::Bool(true))
            }
            Some(b'f') => {
                self.expect_lit(b"false")?;
                Ok(Value::Bool(false))
            }
            Some(b'"') => self.parse_string().map(Value::String),
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_object(),
            Some(b'-' | b'0'..=b'9') => self.parse_number().map(Value::Number),
            Some(other) => Err(format!("unexpected JSON byte {}", other)),
            None => Err("unexpected end of JSON".to_string()),
        }
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.expect_byte(b'{')?;
        let mut map = BTreeMap::new();
        loop {
            self.skip_ws();
            if self.consume_if(b'}') {
                break;
            }
            let key = self.parse_string()?;
            self.skip_ws();
            self.expect_byte(b':')?;
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_ws();
            if self.consume_if(b'}') {
                break;
            }
            self.expect_byte(b',')?;
        }
        Ok(Value::Object(map))
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.expect_byte(b'[')?;
        let mut values = Vec::new();
        loop {
            self.skip_ws();
            if self.consume_if(b']') {
                break;
            }
            values.push(self.parse_value()?);
            self.skip_ws();
            if self.consume_if(b']') {
                break;
            }
            self.expect_byte(b',')?;
        }
        Ok(Value::Array(values))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect_byte(b'"')?;
        let mut out = String::new();
        while let Some(byte) = self.next() {
            match byte {
                b'"' => return Ok(out),
                b'\\' => match self.next() {
                    Some(b'"') => out.push('"'),
                    Some(b'\\') => out.push('\\'),
                    Some(b'/') => out.push('/'),
                    Some(b'b') => out.push('\u{0008}'),
                    Some(b'f') => out.push('\u{000c}'),
                    Some(b'n') => out.push('\n'),
                    Some(b'r') => out.push('\r'),
                    Some(b't') => out.push('\t'),
                    Some(b'u') => {
                        let code = self.parse_hex4()?;
                        if let Some(ch) = char::from_u32(code) {
                            out.push(ch);
                        } else {
                            return Err("invalid JSON unicode scalar".to_string());
                        }
                    }
                    Some(other) => return Err(format!("invalid JSON escape {}", other)),
                    None => return Err("unterminated JSON escape".to_string()),
                },
                byte if byte.is_ascii_control() => {
                    return Err("control byte in JSON string".to_string());
                }
                byte => out.push(byte as char),
            }
        }
        Err("unterminated JSON string".to_string())
    }

    fn parse_number(&mut self) -> Result<String, String> {
        let start = self.pos;
        if self.consume_if(b'-') {}
        self.consume_digits();
        if self.consume_if(b'.') {
            self.consume_digits();
        }
        if matches!(self.peek(), Some(b'e' | b'E')) {
            self.pos += 1;
            if matches!(self.peek(), Some(b'+' | b'-')) {
                self.pos += 1;
            }
            self.consume_digits();
        }
        if self.pos == start {
            return Err("expected JSON number".to_string());
        }
        std::str::from_utf8(&self.input[start..self.pos])
            .map(str::to_string)
            .map_err(|e| e.to_string())
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        let mut value = 0u32;
        for _ in 0..4 {
            let Some(byte) = self.next() else {
                return Err("short JSON unicode escape".to_string());
            };
            value <<= 4;
            value += match byte {
                b'0'..=b'9' => (byte - b'0') as u32,
                b'a'..=b'f' => (byte - b'a' + 10) as u32,
                b'A'..=b'F' => (byte - b'A' + 10) as u32,
                _ => return Err("invalid JSON unicode escape".to_string()),
            };
        }
        Ok(value)
    }

    fn consume_digits(&mut self) {
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.pos += 1;
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), String> {
        if self.input.get(self.pos..self.pos + lit.len()) == Some(lit) {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("unexpected JSON literal".to_string())
        }
    }

    fn expect_byte(&mut self, expected: u8) -> Result<(), String> {
        match self.next() {
            Some(byte) if byte == expected => Ok(()),
            Some(byte) => Err(format!("expected byte {}, got {}", expected, byte)),
            None => Err(format!("expected byte {}, got EOF", expected)),
        }
    }

    fn consume_if(&mut self, expected: u8) -> bool {
        if self.peek() == Some(expected) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\n' | b'\r' | b'\t')) {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<u8> {
        let byte = self.peek()?;
        self.pos += 1;
        Some(byte)
    }
}

#[derive(Debug, Parser)]
#[command(name = "prismos", about = "PrismOS runtime")]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Verify every committed file in a retained or restored native experiment.
    ExperimentVerify {
        #[arg(long)]
        output: PathBuf,
    },
    Boot {
        #[arg(long, default_value = ".")]
        bundle: PathBuf,
    },
    Run {
        #[arg(default_value = "path-a-4boe")]
        profile: String,

        /// Registry-backed target id or PDB id (e.g. 4BOE). Removes the raw flag wall.
        #[arg(long)]
        target: Option<String>,

        /// Runtime mode for --target (e.g. path-a, full). Defaults to path-a.
        #[arg(long)]
        mode: Option<String>,

        /// Resolve + write the resolved profile WITHOUT executing prep or launching the engine.
        #[arg(long, default_value_t = false)]
        plan: bool,

        #[arg(long, default_value = ".")]
        repo: PathBuf,

        #[arg(long)]
        output: Option<PathBuf>,

        #[arg(long, default_value_t = 8767)]
        dashboard_port: u16,

        #[arg(long, default_value_t = false)]
        no_dashboard_server: bool,
    },
    Eval {
        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,

        #[arg(long, default_value_t = false)]
        no_server: bool,
    },
    View {
        #[arg(default_value = "all")]
        surface: String,

        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,

        #[arg(long, default_value_t = false)]
        no_server: bool,
    },
    Manifest {
        #[arg(default_value = "all")]
        surface: String,

        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long)]
        output: Option<PathBuf>,
    },
    Use {
        #[arg(long)]
        run_dir: PathBuf,
    },
    Current,
    Open {
        #[arg(default_value = "all")]
        surface: String,

        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,
    },
    Dashboard {
        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,
    },
    Doctor {
        #[arg(long)]
        run_dir: Option<PathBuf>,

        /// Strict mode: exit non-zero if any required gate is not PASS.
        #[arg(long, default_value_t = false)]
        strict: bool,
    },
    Control {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    PathA {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    PathB {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Dstw {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Molecules {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Teacher {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Student {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Gflownet {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Status {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Serve {
        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,
    },
    /// Science evaluation surface (no subcommand) OR a first-class evidence
    /// EMITTER promotion: `prismos science emit <family>` routes one of the 5
    /// PRISM evidence families BY VALUE from a real produced artifact, or
    /// FAIL-CLEARS with the EXACT missing inputs + producing stage + the command
    /// to run after they exist. Never fabricates a closure.
    Science {
        #[command(subcommand)]
        action: Option<ScienceAction>,

        #[arg(long)]
        run_dir: Option<PathBuf>,

        #[arg(long, default_value_t = 8781)]
        dashboard_port: u16,

        #[arg(long, default_value_t = false)]
        no_server: bool,
    },
    Artifacts {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Isa {
        /// Subcommand: status (default) or coverage.
        #[arg(default_value = "status")]
        action: String,

        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    Codec {
        /// Subcommand: status (default).
        #[arg(default_value = "status")]
        action: String,

        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    /// Downstream binding proof: Path B / DSTW / forge / teacher / student / GFlowNet.
    Lineage {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    /// Hot-path timing: QNANL encode time vs wall clock (is encode a bottleneck?).
    Timing {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    /// Take over a canonical Path A run manifest and re-drive it via PrismOS with
    /// real PrismCode opcodes (same config + packet). Live run untouched.
    Takeover {
        #[arg(long)]
        run_root: PathBuf,

        #[arg(long)]
        output: Option<PathBuf>,

        /// Resolve all manifest jobs WITHOUT launching the engine.
        #[arg(long, default_value_t = false)]
        plan: bool,

        /// Legacy compatibility: run through prism-validate-and-run.sh instead
        /// of the native prismos md-run launcher. New PrismOS acceptance uses the
        /// direct packaged engine child path so the OS owns the runtime.
        #[arg(long, default_value_t = false)]
        via_wrapper: bool,

        /// Save trajectories every N MD steps (0 = off, matching the bare manifest).
        /// High trajectory resolution = small N (e.g. 10).
        #[arg(long, default_value_t = 0)]
        save_trajectory_interval: u32,

        /// MD chunk size (steps per host break) = run "resolution"; production default 500.
        #[arg(long, default_value_t = 500)]
        chunk_size: u32,

        /// Only take over jobs whose region matches this substring (e.g. 7S15 for the last 5).
        #[arg(long)]
        only: Option<String>,

        #[arg(long, default_value = ".")]
        repo: PathBuf,
    },
    /// A/B the standard vs --ultimate-mode kernel: speedup + science parity.
    Bench {
        #[arg(long)]
        target: String,

        #[arg(long, default_value_t = 42)]
        seed: u64,

        /// Resolve both run configs WITHOUT launching the engine.
        #[arg(long, default_value_t = false)]
        plan: bool,

        #[arg(long, default_value = ".")]
        repo: PathBuf,

        #[arg(long)]
        output: Option<PathBuf>,
    },
    Logs {
        #[arg(long)]
        run_dir: Option<PathBuf>,
    },
    /// Execute the appliance-native packet-gated Hyper-Runtime MD profile.
    ///
    /// This is the named PrismOS operating mode for PrismCode authority,
    /// CUDA/resident-graph MD, runtime-native observers, and governed QNANL
    /// receipts. The profile keeps executable-dev packets at L3 by default;
    /// L5 remains reserved for executable production envelopes.
    HyperRuntimeMd(HyperRuntimeMdCliArgs),
    /// Submit a versioned canonical Hyper-Runtime request.
    ///
    /// This is the common client facade for CLI, systemd, GUI, agents, and
    /// CoPilot. It resolves packet, target, source/engine, physics, observer,
    /// output, and evidence authority before delegating to `hyper-runtime-md`.
    HyperRuntime(HyperRuntimeCliArgs),
    /// Inspect or invoke the authoritative installed PrismOS model router.
    Model {
        #[command(subcommand)]
        action: ModelAction,
    },
    MdRun {
        #[arg(long, default_value = ".")]
        repo: PathBuf,

        #[arg(long)]
        topology: PathBuf,

        #[arg(long)]
        output: PathBuf,

        #[arg(long)]
        prismcode_packet: PathBuf,

        #[arg(long)]
        prism_bundle_root: Option<PathBuf>,

        #[arg(long)]
        qnanl_force_kernel_packet: Option<PathBuf>,

        #[arg(long)]
        qnanl_force_kernel_receipt: Option<PathBuf>,

        #[arg(long, default_value_t = true)]
        qnanl_primary_artifacts: bool,

        #[arg(long, default_value_t = true)]
        qnanl_source_artifacts: bool,

        #[arg(long, default_value_t = true)]
        registry_artifact_discovery: bool,

        #[arg(long = "artifact-root")]
        artifact_roots: Vec<PathBuf>,

        #[arg(long = "path-b-root")]
        path_b_roots: Vec<PathBuf>,

        #[arg(long = "dstw-root")]
        dstw_roots: Vec<PathBuf>,

        #[arg(long = "forge-root")]
        forge_roots: Vec<PathBuf>,

        #[arg(long = "model-export-root")]
        model_export_roots: Vec<PathBuf>,

        #[arg(long = "science-root")]
        science_roots: Vec<PathBuf>,

        #[arg(long, default_value_t = true)]
        stream_large_qnanl_artifacts: bool,

        #[arg(long, default_value_t = 67108864)]
        qnanl_streaming_threshold_bytes: u64,

        #[arg(long, default_value_t = false)]
        keep_raw_debug: bool,

        #[arg(long, default_value_t = true)]
        require_cuda_graph_native: bool,

        /// Disable the CUDA graph capture/replay hard gate for hardware probes.
        #[arg(long, default_value_t = false)]
        no_require_cuda_graph_native: bool,

        #[arg(long, default_value_t = true)]
        metal_resident_md: bool,

        /// Disable conditional-WHILE metal-resident MD while preserving ordinary
        /// CUDA graph capture/replay. Required on GPUs/drivers that do not
        /// support CUDA conditional graph nodes.
        #[arg(long, default_value_t = false)]
        no_metal_resident_md: bool,

        #[arg(long, default_value_t = true)]
        require_metal_resident_md: bool,

        /// Do not fail when conditional-WHILE metal-resident MD is unavailable.
        #[arg(long, default_value_t = false)]
        no_require_metal_resident_md: bool,

        #[arg(long, default_value_t = true)]
        require_hotpath_acceleration: bool,

        /// Disable the host-launch-collapse hard gate while preserving CUDA
        /// graph capture/replay evidence.
        #[arg(long, default_value_t = false)]
        no_require_hotpath_acceleration: bool,

        #[arg(long, default_value_t = 64.0)]
        min_hotpath_launch_collapse: f64,

        #[arg(long, default_value = "target/release/nhs_rt_full")]
        engine: PathBuf,

        #[arg(long, default_value = "cuda")]
        prismcode_backend: String,

        #[arg(long, default_value = "L3")]
        prismcode_validation_level: String,

        #[arg(long, default_value_t = 8)]
        multi_stream: usize,

        #[arg(long, default_value_t = 30)]
        max_wall_seconds: u64,

        #[arg(long, default_value_t = 70)]
        spike_percentile: u32,

        #[arg(long, default_value_t = 6)]
        fused_steps: u32,

        #[arg(long, default_value_t = 8)]
        captured_graph_body_unroll: u32,

        #[arg(long, default_value_t = 40000)]
        path_a_chunk_size: u32,

        #[arg(long)]
        path_a_v2_trigger_steps: Option<u32>,

        #[arg(long)]
        path_a_t7_max_chunks: Option<u32>,

        /// Do not inject the Path-A production profile into the engine argv.
        /// This is for strict native-MD hotpath/readout witnesses where V2
        /// capture is not the proof target. Default md-run behavior keeps the
        /// production profile enabled.
        #[arg(long, default_value_t = false)]
        no_path_a_production_profile: bool,

        /// Always-on chronological trajectory/tensor capture policy. The
        /// default is standard, not off. Use --save-trajectory-interval only to
        /// override the policy interval for a particular run.
        #[arg(long, value_enum, default_value_t = TemporalFidelity::Standard)]
        temporal_fidelity: TemporalFidelity,

        /// Override the temporal-fidelity capture interval. 0 means use
        /// --temporal-fidelity policy, not disable temporal capture.
        #[arg(long, default_value_t = 0)]
        save_trajectory_interval: u32,

        #[arg(long, default_value = "280,274,258,254,211")]
        uv_wavelengths: String,

        /// Optional NMA modes artifact. NMA amplification/scan are forwarded to
        /// the engine only when this file is provided; scalar NMA knobs alone
        /// do not create a runtime MD.NMA_PERTURB claim.
        #[arg(long)]
        nma_perturb: Option<PathBuf>,

        #[arg(long, default_value_t = 3.0)]
        nma_amplification: f32,

        #[arg(long, default_value_t = 0.3)]
        nma_scan_fraction: f32,

        #[arg(long, default_value_t = 42)]
        replica_seed: u64,

        /// Explicitly permit the engine's historical uniform-fudge nonbonded
        /// path for compatibility evidence. This is non-production science and
        /// successful runs remain IMPLEMENTATION_PARTIAL.
        #[arg(long, default_value_t = false)]
        non_production_legacy_nonbonded: bool,

        #[arg(long = "engine-arg")]
        engine_args: Vec<String>,

        /// Site-detection posture stamped into PrismOS receipts and downstream
        /// mode ledgers. This does not silently enable legacy engine ranking
        /// flags; canonical runs stay on `--site-ranker phase-manifold`.
        #[arg(long, value_enum, default_value_t = DetectionMode::Mixed)]
        detection_mode: DetectionMode,

        /// Ligand posture. apo requires an apo topology; holo requires the
        /// selected engine-driving topology to contain GDP and refuses
        /// intent-only execution.
        #[arg(long, value_enum, default_value_t = LigandMode::Apo)]
        ligand_mode: LigandMode,

        /// Collect QNANL runtime receipts into a dedicated index.
        #[arg(long, default_value_t = false)]
        emit_runtime_qnanl: bool,

        /// Run packaged Path-B/V2 materialization as a PrismOS-orchestrated
        /// runtime stage after MD evidence emission.
        #[arg(long, default_value_t = false)]
        emit_runtime_pathb: bool,

        /// Run packaged tokenizer export over runtime-emitted T4 artifacts.
        #[arg(long, default_value_t = false)]
        emit_runtime_tokenizer_manifest: bool,

        /// Emit an opcode/operand ledger from native-MD receipts.
        #[arg(long, default_value_t = false)]
        emit_runtime_opcode_ledger: bool,

        /// Emit a provenance lineage DAG.
        #[arg(long, default_value_t = false)]
        emit_runtime_lineage_dag: bool,

        /// Emit hysteresis coverage parsed from the engine log.
        #[arg(long, default_value_t = false)]
        emit_runtime_hysteresis_coverage: bool,

        /// Print the full prismos_md_run_receipt.json to stdout after the
        /// runtime receipt is emitted.
        #[arg(long, default_value_t = true)]
        print_receipt: bool,
    },
    /// Full-family tokenizer corpus operations (Phase 0/1: `compile`).
    Corpus {
        #[command(subcommand)]
        action: CorpusAction,
    },
    /// PrismOS Beta acceptance entry point. Emits a complete distro proof bundle
    /// (14 sub-reports) into `output`. NEVER fabricates PASS: any producer or
    /// asset absent on THIS host is reported ABSENT with an explicit
    /// `absent_reason`, and byte/coverage gates that do not hold are FAIL.
    ProveDistro {
        /// Output directory for the proof bundle (created if absent).
        #[arg(long)]
        output: PathBuf,

        /// Run the expensive bounded native-MD sub-report (10). Default false
        /// gates sub-report 10 to referencing an existing receipt only.
        #[arg(long, default_value_t = false)]
        bounded_md: bool,
    },
    /// Target preparation: turn a raw/clean structure (or a prebuilt topology)
    /// into an engine-ready `.topology.json` with an HONEST ligand-state ledger.
    /// `apo`/`ligand-stripped` shell out to the trusted offline prep tools
    /// (`scripts/prism-clean.py` + `scripts/prism-prep`); `holo`/`gdp-bound`
    /// NEVER fabricate ligand force-field parameters — they SUCCEED only by
    /// adopting an already-parameterized GDP topology, resolving a prebuilt
    /// holo sibling, or merging prebuilt FF artifacts via the offline builder,
    /// and otherwise fail-clear as BLOCKED.
    Target {
        #[command(subcommand)]
        action: TargetAction,
    },
}

/// Subcommands under `prismos corpus`.
#[derive(Debug, Subcommand)]
enum CorpusAction {
    /// Walk a run dir (single md-run output OR the matrix root), build a
    /// full-family tokenizer manifest over every emitted artifact, run the
    /// packaged tokenizer, gate the result, and emit compile/loader/UI artifacts.
    Compile {
        /// Run directory to walk recursively for emitted artifacts.
        #[arg(long)]
        run_dir: PathBuf,

        /// Output directory for the manifest, corpus, and receipts.
        #[arg(long)]
        output: PathBuf,

        /// Warn (not hard-fail) when a manifest source produced zero records.
        #[arg(long, default_value_t = false)]
        require_all_emitted_families: bool,

        /// Fail if any routed family is Opaque/Unknown.
        #[arg(long, default_value_t = false)]
        reject_opaque_required: bool,

        /// Fail if the corpus reports zero matched fields.
        #[arg(long, default_value_t = false)]
        require_matched_fields: bool,

        /// Emit output/training_loader_manifest.json.
        #[arg(long, default_value_t = false)]
        emit_training_loader_manifest: bool,

        /// Emit output/ui_index.json.
        #[arg(long, default_value_t = false)]
        emit_ui_index: bool,

        /// Reduce raw dense-tensor .bin artifacts into
        /// output/dense_tensor_semantic_summaries.json (18-field
        /// DenseTensorSemanticSummary records) and route them into the corpus.
        #[arg(long, default_value_t = false)]
        reduce_dense: bool,
    },
}

#[derive(Debug, Subcommand)]
enum ModelAction {
    /// Probe the real installed model-router availability matrix.
    Status {
        /// Authoritative installed model-runtime Python interpreter.
        #[arg(long, default_value = "/opt/prismos/model-runtime/bin/python")]
        python: PathBuf,

        /// Authoritative installed router entrypoint. This is passed directly to
        /// the fixed model-runtime interpreter, without a shell wrapper.
        #[arg(
            long,
            default_value = "/usr/local/lib/prismos/services/prismos_model_router.py"
        )]
        router: PathBuf,

        /// Override the router install-layout context when explicitly required.
        #[arg(long)]
        context_hint: Option<String>,
    },
    /// Dry-run the real router policy for request.workload_class.
    Route {
        /// Inline JSON request containing a nonempty workload_class string.
        #[arg(long)]
        request: String,

        /// Authoritative installed model-runtime Python interpreter.
        #[arg(long, default_value = "/opt/prismos/model-runtime/bin/python")]
        python: PathBuf,

        /// Authoritative installed router entrypoint. This is passed directly to
        /// the fixed model-runtime interpreter, without a shell wrapper.
        #[arg(
            long,
            default_value = "/usr/local/lib/prismos/services/prismos_model_router.py"
        )]
        router: PathBuf,

        /// Explicit runtime evidence root forwarded to the real router.
        #[arg(long)]
        evidence_root: Option<PathBuf>,

        /// Override the router install-layout context when explicitly required.
        #[arg(long)]
        context_hint: Option<String>,
    },
}

/// Subcommands under `prismos target`.
#[derive(Debug, Subcommand)]
enum TargetAction {
    /// Prepare an engine-ready topology + an honest ligand-state ledger.
    Prepare {
        /// Input structure: `.pdb`/`.ent` (raw or clean), `.cif`/`.mmcif`, or a
        /// prebuilt `.topology.json` (adopted directly after validation).
        #[arg(long)]
        input: PathBuf,

        /// Stable identifier stamped into every emitted artifact (e.g. `4LPK`).
        #[arg(long)]
        target_id: String,

        /// Output directory for the three emitted artifacts (created if absent).
        #[arg(long)]
        output: PathBuf,

        /// Ligand posture for the prepared topology.
        #[arg(long, value_enum, default_value_t = TargetPrepMode::Apo)]
        mode: TargetPrepMode,

        /// Fail-closed: mismatch / missing-FF / BLOCKED become a non-zero exit
        /// (the receipt is ALWAYS written first, then the process errors).
        #[arg(long, default_value_t = false)]
        strict: bool,

        /// Repo root used to resolve the offline prep tools
        /// (`scripts/prism-clean.py`, `scripts/prism-prep`,
        /// `scripts/build_holo_state_topology.py`).
        #[arg(long, default_value = ".")]
        repo: PathBuf,

        /// Chain to retain when cleaning a raw PDB for apo/ligand-stripped prep.
        #[arg(long, default_value = "A")]
        chain: String,

        /// Directory of PREBUILT ligand force-field artifacts (SDF with embedded
        /// AM1-BCC charges the offline builder consumes). Enables the ONLY honest
        /// gdp-bound assembly path; never triggers in-runtime parameterization.
        #[arg(long)]
        ligand_ff_dir: Option<PathBuf>,
    },
}

/// Subcommands under `prismos science`.
#[derive(Debug, Subcommand)]
enum ScienceAction {
    /// Promote a first-class PRISM evidence EMITTER family to a runtime-owned
    /// command. The family is emitted BY VALUE from a real produced artifact,
    /// or FAIL-CLEARS with the EXACT missing inputs + producing stage + the
    /// command to run after they exist. NEVER fabricates a family closure.
    Emit {
        /// Evidence emitter family to route.
        #[arg(value_enum)]
        family: ScienceEmitFamily,

        /// Run directory searched (recursively) for the family's produced
        /// artifact(s) / required inputs.
        #[arg(long)]
        run_root: PathBuf,

        /// Output directory for the emit receipt + routed corpus (created if absent).
        #[arg(long)]
        output: PathBuf,

        /// Fail-closed: a BLOCKED family (missing inputs) becomes a non-zero
        /// exit (the receipt is ALWAYS written first, then the process errors).
        #[arg(long, default_value_t = false)]
        strict: bool,
    },
    /// Fail-closed science quality gate for corpus-merge eligibility. This is
    /// intentionally stricter than `science emit`: it can accept row-level
    /// evidence as useful training substrate while still rejecting final merge
    /// readiness when causal lag, mode contrast, replicate, measured-noise, or
    /// geometry requirements are not met.
    QualityGate {
        /// Run directory to evaluate. May be a single md-run output or a matrix
        /// root containing multiple row run directories.
        #[arg(long)]
        run_root: PathBuf,

        /// Output directory for gate ledgers, local corpus compile, and receipts.
        #[arg(long)]
        output: PathBuf,

        /// Require final governed-corpus merge readiness, not just row-level
        /// training-substrate validity.
        #[arg(long, default_value_t = false)]
        require_final_merge_ready: bool,

        /// Return non-zero if the requested gate status is not achieved.
        #[arg(long, default_value_t = false)]
        strict: bool,
    },
}

/// The first-class PRISM evidence emitter families exposed by
/// `prismos science emit <family>`. Canonical value names are the exact
/// PascalCase family names used across the tokenizer + corpus ledgers; a
/// kebab-case alias is accepted for shell ergonomics.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum ScienceEmitFamily {
    /// GhostPhaseLattice4D SO(3) edge-validation manifest. PRODUCIBLE via a
    /// v2-capture run and canonical for component/edge evidence when its
    /// Path-B canonicalization receipt passes. Raw lattice evidence alone is
    /// not cross-replica consensus.
    #[value(
        name = "PhaseManifoldEdgeValidation",
        alias = "phase-manifold-edge-validation"
    )]
    PhaseManifoldEdgeValidation,
    /// KCC site-adjudicator sites[] with gtck_rank + per-site ranks.
    #[value(name = "KccSite", alias = "kcc-site")]
    KccSite,
    /// DSTW Laplacian spectral-extractor fiber bundle.
    #[value(name = "SpectralExtractor", alias = "spectral-extractor")]
    SpectralExtractor,
    /// N80 per-residue phase-manifold coherence tensor (geomean/min channel fusion).
    #[value(name = "PhaseManifoldCoherence", alias = "phase-manifold-coherence")]
    PhaseManifoldCoherence,
    /// DSTW temporal superresolution tensor (multi-rate trajectory fusion).
    #[value(name = "DstwSuperresolution", alias = "dstw-superresolution")]
    DstwSuperresolution,
    /// Operator-scoped causal geometry event bundle:
    /// ScientificPocketOpeningEvent + LigandCausalActivityEvent +
    /// ResidueActivityEvent, generated from native chronology + Path-B sites +
    /// run-specific spectral geometry.
    #[value(name = "CausalGeometry", alias = "causal-geometry")]
    CausalGeometry,
}

fn main() {
    if let Err(err) = run() {
        eprintln!("{err}");
        std::process::exit(2);
    }
}

fn run() -> PcResult<()> {
    match Cli::parse().command {
        Command::Boot { bundle } => {
            let root = fs::canonicalize(bundle)?;
            let required = [
                "release/cse_hd_reference.pcode",
                "release/cse_hd_reference.cpu.pcout",
                "release/cse_hd_reference.cuda.pcout",
                "release/nanl_bin.nanlb",
                "release/nanl_q4.nanlq4",
                "release/nanl_dna_simulation_report.json",
                "release/nrf_frames.nrf",
                "release/drf_graph.drf",
                "release/replay_report.json",
                "release/cpu_gpu_parity_report.json",
                "release/cuda_benchmark_report.json",
                "release/key_provider_report.json",
                "release/attestation_report.json",
                "release/evidence_ledger.json",
                "release/evidence_ledger.sig",
            ];
            for rel in required {
                require_nonempty(&root.join(rel))?;
            }
            let fw = run_bin(&root, "prismfw", &["verify"])?;
            let audit = run_bin(&root, "prismctl", &["audit"])?;
            let status = if fw.get("success").and_then(Value::as_bool) == Some(true)
                && audit.get("success").and_then(Value::as_bool) == Some(true)
            {
                "PASS"
            } else {
                "FAIL"
            };
            let report = j_obj(vec![
                ("status", j_str(status)),
                (
                    "boot_graph",
                    j_string_array(&[
                        "FIRMWARE_PROFILE_SIGNATURE",
                        "CSE_HD_FULL_IMPLEMENTATION",
                        "NANL_BIN",
                        "NANL_Q4",
                        "NANL_DNA_SIMULATOR_ONLY",
                        "NRF_GENERATION",
                        "DRF_GENERATION",
                        "DRF_CPU_EXECUTION",
                        "DRF_CUDA_EXECUTION",
                        "CUDA_REPLAY",
                        "VAULT_PROVIDER_BOUND",
                        "RELEASE_MANIFEST_VERIFIED",
                        "EVIDENCE_LEDGER_VERIFIED",
                    ]),
                ),
                ("firmware_verify", fw),
                ("audit", audit),
            ]);
            println!("{}", report.to_pretty_json());
            if status != "PASS" {
                return Err(PcError::Security(
                    "installed PRISM OS boot failed".to_string(),
                ));
            }
        }
        Command::ExperimentVerify { output } => {
            let report = prismcode::durable_experiment::verify_output(&output)?;
            println!("{}", serde_json::to_string_pretty(&report)?);
            if report["status"] != "IMPLEMENTATION_VERIFIED" {
                return Err(PcError::Security("experiment has incomplete committed stages".into()));
            }
        }
        Command::HyperRuntimeMd(args) => run_hyper_runtime_md(args)?,
        Command::HyperRuntime(args) => run_hyper_runtime(args)?,
        Command::Model { action } => run_model_action(action)?,
        Command::MdRun {
            repo,
            topology,
            output,
            prismcode_packet,
            prism_bundle_root,
            qnanl_force_kernel_packet,
            qnanl_force_kernel_receipt,
            qnanl_primary_artifacts,
            qnanl_source_artifacts,
            registry_artifact_discovery,
            artifact_roots,
            path_b_roots,
            dstw_roots,
            forge_roots,
            model_export_roots,
            science_roots,
            stream_large_qnanl_artifacts,
            qnanl_streaming_threshold_bytes,
            keep_raw_debug,
            require_cuda_graph_native,
            no_require_cuda_graph_native,
            metal_resident_md,
            no_metal_resident_md,
            require_metal_resident_md,
            no_require_metal_resident_md,
            require_hotpath_acceleration,
            no_require_hotpath_acceleration,
            min_hotpath_launch_collapse,
            engine,
            prismcode_backend,
            prismcode_validation_level,
            multi_stream,
            max_wall_seconds,
            spike_percentile,
            fused_steps,
            captured_graph_body_unroll,
            path_a_chunk_size,
            path_a_v2_trigger_steps,
            path_a_t7_max_chunks,
            no_path_a_production_profile,
            temporal_fidelity,
            save_trajectory_interval,
            uv_wavelengths,
            nma_perturb,
            nma_amplification,
            nma_scan_fraction,
            replica_seed,
            non_production_legacy_nonbonded,
            engine_args,
            detection_mode,
            ligand_mode,
            emit_runtime_qnanl,
            emit_runtime_pathb,
            emit_runtime_tokenizer_manifest,
            emit_runtime_opcode_ledger,
            emit_runtime_lineage_dag,
            emit_runtime_hysteresis_coverage,
            print_receipt,
        } => run_md(RunMdArgs {
            repo,
            topology,
            output,
            prismcode_packet,
            expected_prismcode_packet_sha256: None,
            expected_prismcode_packet_hash_blake3: None,
            expected_source_epoch_id: None,
            expected_active_lock_sha256: None,
            expected_hyper_runtime_request_id: None,
            expected_engine_sha256: None,
            canonical_input_locator: None,
            expected_input_sha256: None,
            canonical_therm_and_post_md_policy: None,
            canonical_native_engine_intent: None,
            typed_engine_arguments: false,
            prism_bundle_root,
            qnanl_force_kernel_packet,
            qnanl_force_kernel_receipt,
            qnanl_primary_artifacts,
            qnanl_source_artifacts,
            registry_artifact_discovery,
            artifact_roots,
            path_b_roots,
            dstw_roots,
            forge_roots,
            model_export_roots,
            science_roots,
            stream_large_qnanl_artifacts,
            qnanl_streaming_threshold_bytes,
            keep_raw_debug,
            require_cuda_graph_native: require_cuda_graph_native && !no_require_cuda_graph_native,
            metal_resident_md: metal_resident_md && !no_metal_resident_md,
            require_metal_resident_md: require_metal_resident_md && !no_require_metal_resident_md,
            require_hotpath_acceleration: require_hotpath_acceleration
                && !no_require_hotpath_acceleration,
            min_hotpath_launch_collapse,
            engine,
            prismcode_backend,
            prismcode_validation_level,
            multi_stream,
            max_wall_seconds: Some(max_wall_seconds),
            spike_percentile,
            fused_steps,
            captured_graph_body_unroll,
            path_a_chunk_size,
            path_a_v2_trigger_steps,
            path_a_t7_max_chunks,
            path_a_production_profile: !no_path_a_production_profile,
            temporal_fidelity,
            save_trajectory_interval,
            uv_wavelengths,
            nma_perturb,
            nma_amplification,
            nma_scan_fraction,
            replica_seed,
            non_production_legacy_nonbonded,
            closed_loop_steering: true,
            topology_b: None,
            contrast_kind: None,
            identical_topology_negative_control: false,
            probe_residue_ids: Vec::new(),
            cryptic_search_outer_cutoff_angstrom: COUPLED_CRYPTIC_SEARCH_OUTER_CUTOFF_ANGSTROM,
            engine_args,
            detection_mode,
            ligand_mode,
            emit_runtime_qnanl,
            emit_runtime_pathb,
            emit_runtime_tokenizer_manifest,
            emit_runtime_opcode_ledger,
            emit_runtime_lineage_dag,
            emit_runtime_hysteresis_coverage,
            print_receipt,
        })?,
        Command::Run {
            profile,
            target,
            mode,
            plan,
            repo,
            output,
            dashboard_port,
            no_dashboard_server,
        } => run_profile(ProfileRunArgs {
            profile,
            target,
            mode,
            plan,
            repo,
            output,
            dashboard_port,
            no_dashboard_server,
        })?,
        Command::Eval {
            run_dir,
            dashboard_port,
            no_server,
        } => run_eval(EvalArgs {
            run_dir: resolve_run_dir(run_dir)?,
            dashboard_port,
            no_server,
        })?,
        Command::View {
            surface,
            run_dir,
            dashboard_port,
            no_server,
        } => run_view_surface(
            &surface,
            resolve_run_dir(run_dir)?,
            dashboard_port,
            no_server,
        )?,
        Command::Manifest {
            surface,
            run_dir,
            output,
        } => run_manifest_surface(&surface, resolve_run_dir(run_dir)?, output)?,
        Command::Use { run_dir } => run_use_active_run(run_dir)?,
        Command::Current => run_current_run()?,
        Command::Open {
            surface,
            run_dir,
            dashboard_port,
        } => run_view_surface(&surface, resolve_run_dir(run_dir)?, dashboard_port, false)?,
        Command::Dashboard {
            run_dir,
            dashboard_port,
        } => run_canonical_surface("serve", resolve_run_dir(run_dir)?, dashboard_port, false)?,
        Command::Doctor { run_dir, strict } => run_doctor(resolve_run_dir(run_dir)?, strict)?,
        Command::Control { run_dir } => {
            run_canonical_surface("control", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::PathA { run_dir } => {
            run_view_surface("path-a", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::PathB { run_dir } => {
            run_view_surface("path-b", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Dstw { run_dir } => {
            run_view_surface("dstw", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Molecules { run_dir } => {
            run_view_surface("molecules", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Teacher { run_dir } => {
            run_view_surface("teacher", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Student { run_dir } => {
            run_view_surface("student", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Gflownet { run_dir } => {
            run_view_surface("gflownet", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Status { run_dir } => {
            run_canonical_surface("status", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Serve {
            run_dir,
            dashboard_port,
        } => run_canonical_surface("serve", resolve_run_dir(run_dir)?, dashboard_port, false)?,
        Command::Science {
            action,
            run_dir,
            dashboard_port,
            no_server,
        } => match action {
            None => run_canonical_surface(
                "science",
                resolve_run_dir(run_dir)?,
                dashboard_port,
                no_server,
            )?,
            Some(ScienceAction::Emit {
                family,
                run_root,
                output,
                strict,
            }) => run_science_emit(family, &run_root, &output, strict)?,
            Some(ScienceAction::QualityGate {
                run_root,
                output,
                require_final_merge_ready,
                strict,
            }) => run_science_quality_gate(&run_root, &output, require_final_merge_ready, strict)?,
        },
        Command::Artifacts { run_dir } => {
            run_canonical_surface("artifacts", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Isa { action, run_dir } => {
            let rd = resolve_run_dir(run_dir)?;
            if action.trim().eq_ignore_ascii_case("coverage") {
                run_isa_coverage(rd)?
            } else {
                run_canonical_surface("isa", rd, 8781, true)?
            }
        }
        Command::Codec { run_dir, .. } => run_codec_status(resolve_run_dir(run_dir)?)?,
        Command::Lineage { run_dir } => run_lineage(resolve_run_dir(run_dir)?)?,
        Command::Timing { run_dir } => run_timing(resolve_run_dir(run_dir)?)?,
        Command::Takeover {
            run_root,
            output,
            plan,
            via_wrapper,
            save_trajectory_interval,
            chunk_size,
            only,
            repo,
        } => {
            let repo_root = fs::canonicalize(&repo)?;
            let run_root = fs::canonicalize(&run_root)?;
            run_takeover(
                &repo_root,
                &run_root,
                output,
                plan,
                via_wrapper,
                save_trajectory_interval,
                chunk_size,
                only,
            )?
        }
        Command::Bench {
            target,
            seed,
            plan,
            repo,
            output,
        } => {
            let repo_root = fs::canonicalize(&repo)?;
            run_bench(&repo_root, &target, seed, plan, output)?
        }
        Command::Logs { run_dir } => {
            run_canonical_surface("logs", resolve_run_dir(run_dir)?, 8781, true)?
        }
        Command::Corpus { action } => match action {
            CorpusAction::Compile {
                run_dir,
                output,
                require_all_emitted_families,
                reject_opaque_required,
                require_matched_fields,
                emit_training_loader_manifest,
                emit_ui_index,
                reduce_dense,
            } => run_corpus_compile(
                &run_dir,
                &output,
                require_all_emitted_families,
                reject_opaque_required,
                require_matched_fields,
                emit_training_loader_manifest,
                emit_ui_index,
                reduce_dense,
            )?,
        },
        Command::ProveDistro { output, bounded_md } => run_prove_distro(&output, bounded_md)?,
        Command::Target { action } => match action {
            TargetAction::Prepare {
                input,
                target_id,
                output,
                mode,
                strict,
                repo,
                chain,
                ligand_ff_dir,
            } => run_target_prepare(TargetPrepareArgs {
                input,
                target_id,
                output,
                mode,
                strict,
                repo,
                chain,
                ligand_ff_dir,
            })?,
        },
    }
    Ok(())
}

/// Site-detection posture for `prismos md-run`.
///
/// This is a PrismOS condition label / receipt field. It must not silently add
/// legacy engine flags (`--cascade`, `--boltzmann-rank`). Canonical runs stay on
/// `--site-ranker phase-manifold`; legacy flags are allowed only when explicitly
/// supplied through `--engine-arg` for a controlled comparison.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum DetectionMode {
    Orthosteric,
    Cryptic,
    Mixed,
}

/// Ligand posture for `prismos md-run`.
///
/// `Apo` requires a topology with no GDP residue token. `Holo` requires a
/// GDP-containing topology and runs that topology as the actual engine input.
/// A mode that only changes a receipt is not an execution mode.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum LigandMode {
    Apo,
    Holo,
}

/// Chronological trajectory/tensor capture policy for `prismos md-run`.
///
/// This is a PrismOS runtime policy, not a wrapper-script hint. Every mode row
/// captures scheduled trajectory frames unless an explicit future policy adds a
/// separately audited disable mode. Smaller intervals mean higher temporal
/// fidelity and larger outputs.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum TemporalFidelity {
    /// Low-overhead chronological evidence: frame every 64 MD steps.
    Minimal,
    /// Default PrismOS beta policy: frame every 16 MD steps.
    Standard,
    /// Higher-fidelity state-transition evidence: frame every 8 MD steps.
    High,
    /// Exhaustive trajectory/state capture: frame every MD step.
    Exhaustive,
}

impl TemporalFidelity {
    fn as_str(self) -> &'static str {
        match self {
            TemporalFidelity::Minimal => "minimal",
            TemporalFidelity::Standard => "standard",
            TemporalFidelity::High => "high",
            TemporalFidelity::Exhaustive => "exhaustive",
        }
    }

    fn default_save_trajectory_interval(self) -> u32 {
        match self {
            TemporalFidelity::Minimal => 64,
            TemporalFidelity::Standard => 16,
            TemporalFidelity::High => 8,
            TemporalFidelity::Exhaustive => 1,
        }
    }

    fn raw_temporal_retention_required(self) -> bool {
        true
    }

    fn requires_exact_chronology_cadence(self) -> bool {
        matches!(self, TemporalFidelity::High | TemporalFidelity::Exhaustive)
    }
}

/// Ligand posture requested for `prismos target prepare`.
///
/// `Apo` / `LigandStripped` produce a receptor-only topology via the offline
/// prep tools (both map to `ligand_mode_for_md_run = apo`). `Holo` / `GdpBound`
/// require an actually-parameterized GDP topology and map to `holo`; there is
/// NO in-runtime GAFF/AM1-BCC/antechamber path, so they SUCCEED only by
/// adopting/merging prebuilt parameters and otherwise fail-clear as BLOCKED.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum TargetPrepMode {
    Apo,
    Holo,
    LigandStripped,
    GdpBound,
}

impl TargetPrepMode {
    fn as_str(self) -> &'static str {
        match self {
            TargetPrepMode::Apo => "apo",
            TargetPrepMode::Holo => "holo",
            TargetPrepMode::LigandStripped => "ligand-stripped",
            TargetPrepMode::GdpBound => "gdp-bound",
        }
    }

    /// Does the requested posture expect a parameterized ligand in the output?
    fn expects_ligand(self) -> bool {
        matches!(self, TargetPrepMode::Holo | TargetPrepMode::GdpBound)
    }

    /// Ligand mode string threaded into the manifest so the prepared topology
    /// feeds `prismos md-run --ligand-mode <this>` unambiguously.
    fn ligand_mode_for_md_run(self) -> &'static str {
        if self.expects_ligand() {
            "holo"
        } else {
            "apo"
        }
    }
}

#[derive(Debug)]
struct EvalArgs {
    run_dir: PathBuf,
    dashboard_port: u16,
    no_server: bool,
}

#[derive(Debug)]
struct ProfileRunArgs {
    profile: String,
    target: Option<String>,
    mode: Option<String>,
    plan: bool,
    repo: PathBuf,
    output: Option<PathBuf>,
    dashboard_port: u16,
    no_dashboard_server: bool,
}

#[derive(Debug, clap::Args)]
struct HyperRuntimeCliArgs {
    /// Native parser-backed scientific intent shared by all clients.
    #[arg(long, conflicts_with_all = ["execution_profile", "target_id", "output", "governed_branch_selection", "request"])]
    intent: Option<PathBuf>,
    /// Root-owned, versioned execution-profile source installed with PrismOS.
    #[arg(long)]
    execution_profile: Option<PathBuf>,

    /// Safe identifier resolved through the profile's governed descriptor root.
    #[arg(long)]
    target_id: Option<String>,

    /// Governed per-run output path.
    #[arg(long)]
    output: Option<PathBuf>,

    /// Non-authoritative caller attribution; excluded from request identity.
    #[arg(long, value_parser = ["cli", "systemd", "gui", "agent", "copilot", "automation"])]
    client_surface: Option<String>,

    /// Hash-bound governed selection produced from one explicit sealed
    /// GFlowNet proposal. Must be paired with --request and cannot be combined
    /// with caller-composed profile/target/output fields.
    #[arg(
        long,
        requires = "request",
        conflicts_with_all = ["execution_profile", "target_id", "output", "client_surface"]
    )]
    governed_branch_selection: Option<PathBuf>,

    /// Exact cognition-produced next-branch execution request. Its identities
    /// are verified against --governed-branch-selection before materialization.
    #[arg(
        long,
        requires = "governed_branch_selection",
        conflicts_with_all = ["execution_profile", "target_id", "output", "client_surface"]
    )]
    request: Option<PathBuf>,

    /// Materialize and print the canonical request without launching the engine.
    #[arg(long, default_value_t = false)]
    plan: bool,
}

#[derive(Debug, clap::Args)]
struct HyperRuntimeMdCliArgs {
    /// Installed PrismOS root used for relative path resolution and provenance.
    #[arg(long, default_value = "/opt/prismos")]
    repo: PathBuf,

    /// Engine-driving topology. The installed reference topology is apo.
    #[arg(long, default_value = "/opt/prismos/packets/reference.topology.json")]
    topology: PathBuf,

    /// Second physical topology for a real two-system PRISM-TWIN molecular
    /// contrast. Requires --contrast-kind and selects --coupled-twin instead
    /// of the single-topology multi-differential path.
    #[arg(long)]
    topology_b: Option<PathBuf>,

    /// Molecular contrast kind bound into the engine receipt. Identical
    /// topology inputs are admitted only by the explicit negative-control
    /// kind and flag; production contrasts must bind distinct file hashes.
    #[arg(long, value_enum)]
    contrast_kind: Option<MolecularContrastKind>,

    /// Admit a same-hash topology pair as the coupled-TWIN negative control.
    /// This never relaxes the distinct-input requirement for apo-holo or
    /// design-reference executions.
    #[arg(long, default_value_t = false)]
    identical_topology_negative_control: bool,

    /// Topology-B residue ordinal belonging to the glycan-bearing probe.
    /// Repeat for each residue; required for glycan-mechanistic-probe.
    #[arg(long = "probe-residue-id")]
    probe_residue_ids: Vec<usize>,

    /// Outer inclusive radius for nearby receptor-only cryptic-site evidence.
    #[arg(long, default_value_t = 12.0)]
    cryptic_search_outer_cutoff_angstrom: f32,

    /// Fresh run root. Existing appliance and protected model paths are not defaults.
    #[arg(long)]
    output: PathBuf,

    /// Executable PrismCode/QNANL run-authority packet.
    #[arg(
        long,
        default_value = "/opt/prismos/packets/prismos_hyper_runtime_reference.pcode"
    )]
    prismcode_packet: PathBuf,

    /// Installed native MD engine.
    #[arg(long, default_value = "/opt/prismos/bin/nhs_rt_full")]
    engine: PathBuf,

    /// Bundle root containing the DEV hash-bound CUDA trust manifest and sidecar.
    #[arg(long, default_value = "/opt/prismos")]
    prism_bundle_root: Option<PathBuf>,

    /// Installed QNANL packet for the byte-exact force-kernel PTX.
    #[arg(
        long,
        default_value = "/opt/prismos/packets/nhs_amber_fused.ptx.prismqnanl"
    )]
    qnanl_force_kernel_packet: Option<PathBuf>,

    #[arg(long)]
    qnanl_force_kernel_receipt: Option<PathBuf>,

    /// Bounded installed source-contract payload. Relative paths resolve under
    /// --repo so the named profile follows the active appliance root.
    #[arg(long = "artifact-root", default_value = "science_contracts")]
    artifact_roots: Vec<PathBuf>,

    #[arg(long = "path-b-root")]
    path_b_roots: Vec<PathBuf>,

    #[arg(long = "dstw-root")]
    dstw_roots: Vec<PathBuf>,

    #[arg(long = "forge-root")]
    forge_roots: Vec<PathBuf>,

    #[arg(long = "model-export-root")]
    model_export_roots: Vec<PathBuf>,

    /// Installed deep-science evidence root. This bounded payload closes seven
    /// native categories; GFlowNet remains PARTIAL until its sampler outputs exist.
    #[arg(long = "science-root", default_value = "/opt/prismos/science_evidence")]
    science_roots: Vec<PathBuf>,

    /// PrismCode execution backend used by the packet gate.
    #[arg(long, default_value = "cuda")]
    prismcode_backend: String,

    /// L3 is the executable-dev gate. L5 accepts only production PSK envelopes
    /// and remains fail-closed until the runtime can securely decrypt them.
    #[arg(
        long,
        default_value = "L3",
        value_parser = ["L0", "L1", "L2", "L3", "L4", "L5"]
    )]
    prismcode_validation_level: String,

    /// Installed reference topology is apo; holo requires a real GDP topology.
    #[arg(long, value_enum, default_value_t = LigandMode::Apo)]
    ligand_mode: LigandMode,

    #[arg(long, value_enum, default_value_t = DetectionMode::Cryptic)]
    detection_mode: DetectionMode,

    /// Typed native engine surface. `auto` preserves the established
    /// Hyper-Runtime contract: single-topology runs select the interferometric
    /// multi-differential lane, while topology-B molecular contrasts use the
    /// strict direct coupled-TWIN lane. Captured-graph-TWIN selects the governed
    /// eight-stream resident-graph implementation and is accepted only when its
    /// explicit graph-scope and GPU-direct coupling receipt passes.
    #[arg(long, value_enum, default_value_t = HyperRuntimeEngineSurface::Auto)]
    engine_surface: HyperRuntimeEngineSurface,

    #[arg(long, default_value_t = 8)]
    multi_stream: usize,

    /// Explicit engine wall-time bound. When omitted, Hyper-Runtime preserves
    /// its established 240-second bound unless --no-wall-time-limit is set.
    #[arg(long)]
    max_wall_seconds: Option<u64>,

    /// Explicitly authorize execution until the requested native steps
    /// complete. This is a typed PrismCode control: it omits the engine
    /// --path-a-max-wall-seconds argument instead of smuggling an unbounded
    /// sentinel through the native engine CLI.
    #[arg(long, conflicts_with = "max_wall_seconds")]
    no_wall_time_limit: bool,

    #[arg(long, default_value_t = 70)]
    spike_percentile: u32,

    #[arg(long, default_value_t = 6)]
    fused_steps: u32,

    /// Logical MD steps captured per governed graph body. The production
    /// default matches the required 64x host-launch collapse contract.
    #[arg(long, default_value_t = 64)]
    captured_graph_body_unroll: u32,

    /// Proven bounded-exit-safe Path-A chunk size for the current appliance.
    #[arg(long, default_value_t = 1000)]
    path_a_chunk_size: u32,

    #[arg(long, value_enum, default_value_t = TemporalFidelity::Standard)]
    temporal_fidelity: TemporalFidelity,

    /// Zero selects the temporal-fidelity policy interval.
    #[arg(long, default_value_t = 0)]
    save_trajectory_interval: u32,

    #[arg(long, default_value_t = 42)]
    replica_seed: u64,

    /// Disable both canonical closed-loop steering and asymmetric steering.
    /// This is a typed Hyper-Runtime science control; the equivalent engine
    /// flags are reserved and cannot be smuggled through --engine-arg.
    #[arg(long, default_value_t = false)]
    no_closed_loop_steering: bool,

    // ── PACKAGE E: typed full-pipeline control plane ────────────────────────
    //
    // A production acceptance run has to be requestable in ONE invocation:
    // Path A (the resident captured-graph MD lane) AND Path B (the Arrow
    // spike/binding-site materializer), on the Ghost/V2 lane, with V2 ignition
    // live and the G26 gearbox actually running. Before this, Path B's engine
    // switch was reachable only by smuggling
    // `--engine-arg=--path-b-primary-surface`, and there was no way at all to
    // say "this run is only acceptable if the gearbox was live".
    //
    // `--engine-surface` is the worked example these follow: a reserved
    // orchestration flag gets a TYPED PrismOS option and is REJECTED when
    // forwarded through --engine-arg, so the control plane always knows the
    // dispatch it asked for and can record it in the profile.
    /// Treat the Arrow/Path-B materializer as the primary binding-site surface.
    /// Typed because `--path-b-primary-surface` is a reserved orchestration
    /// flag. Defaults to the engine's own default (on), so an unset invocation
    /// behaves exactly as before.
    #[arg(
        long,
        action = clap::ArgAction::Set,
        num_args = 0..=1,
        require_equals = true,
        default_value_t = true,
        default_missing_value = "true"
    )]
    path_b_primary_surface: bool,

    /// Require positive evidence that the V2 ignition (CapturedAdjudication)
    /// pipeline actually ran.
    ///
    /// This is an ADMISSION requirement, not a forwarded switch: `v2_ignition`
    /// is a compile-time cargo feature of the engine
    /// (crates/prism-nhs/src/bin/nhs_rt_full.rs:5051), so no runtime flag can
    /// turn it on. What this option does is (a) constrain the dispatch to a
    /// surface on which the V2 pipeline can instantiate and (b) make the run
    /// unacceptable unless the produced evidence shows that it did. It can
    /// never assert ignition by itself.
    #[arg(long, default_value_t = false)]
    require_v2_ignition: bool,

    /// Acceptance expectation for the G26 gearbox. `require-active` also
    /// requires V2 ignition, because a live gearbox is only reachable through
    /// it.
    #[arg(long, value_enum, default_value_t = GearboxLivenessRequirement::Auto)]
    gearbox_liveness: GearboxLivenessRequirement,

    /// Request the full production pipeline in one invocation: Path A and
    /// Path B together, on the Ghost/V2 lane, with V2 ignition required and the
    /// gearbox required to be live. Equivalent to `--engine-surface ghost-tiles
    /// --path-b-primary-surface=true --require-v2-ignition
    /// --gearbox-liveness require-active`. It CONFLICTS loudly rather than
    /// silently overriding: an incompatible explicit option is a named error,
    /// never a quiet reinterpretation of what the operator asked for.
    #[arg(long, default_value_t = false)]
    full_pipeline: bool,

    #[arg(long = "engine-arg")]
    engine_args: Vec<String>,

    /// Private canonical-request policy. Direct `hyper-runtime-md` callers
    /// cannot set it; they retain the raw compatibility lane default.
    #[arg(skip)]
    canonical_therm_and_post_md_policy: Option<ThermAndPostMdPolicyV1>,
    #[arg(skip)]
    canonical_native_engine_intent: Option<NativeEngineIntentV1>,

    /// Enable the runtime-native observational TSH Stage-II lane.
    #[arg(long, default_value_t = false)]
    enable_tsh_stage_ii: bool,

    /// ScientificUncertaintyTensor inputs for TSH normalization.
    #[arg(long = "tsh-uncertainty-tensor", value_name = "PATH")]
    tsh_uncertainty_tensors: Vec<PathBuf>,

    /// Canonical negative-evidence ledger for the TSH consensus gate.
    #[arg(long)]
    tsh_negative_controls: Option<PathBuf>,

    /// Minimum distinct seeds required for a persistent transition object.
    #[arg(long, default_value_t = 2)]
    tsh_min_consensus_seeds: usize,

    /// Physics signature from the paired TSH-disabled baseline run.
    #[arg(long)]
    tsh_baseline_physics_signature: Option<String>,

    #[arg(long, default_value_t = false)]
    keep_raw_debug: bool,

    #[arg(long, default_value_t = 67108864)]
    qnanl_streaming_threshold_bytes: u64,

    /// Print the compact Hyper-Runtime acceptance receipt to stdout.
    #[arg(long, default_value_t = true)]
    print_receipt: bool,

    // ── WP1: typed NMA authority ────────────────────────────────────────────
    //
    // The engine exposes --nma-perturb / --nma-amplification /
    // --nma-scan-fraction, but this control plane previously hardcoded
    // `nma_perturb: None`, so autonomous rescue could never physically act:
    // NMA forces are applied only during warm_hold and only to CA atoms, and
    // with no modes file the rescue controller's NMA actions are no-ops. These
    // flags are typed rather than forwarded through --engine-arg because the
    // engine argument allowlist rejects reserved NMA flags.
    /// Path to the source-derived NMA modes JSON consumed by autonomous rescue.
    /// Generated by `prism-prep --nma-modes N` from the authoritative PDB.
    #[arg(long)]
    nma_perturb: Option<PathBuf>,

    /// NMA perturbation amplification: each mode is pushed to
    /// amplification x thermal_amplitude.
    #[arg(long, default_value_t = 3.0)]
    nma_amplification: f32,

    /// Fraction of warm_hold spent scanning all modes before focusing on the best.
    #[arg(long, default_value_t = 0.3)]
    nma_scan_fraction: f32,

    // ── WP6: typed Path-A duration and trigger authority ────────────────────
    //
    // `path_a_production_profile` was hardcoded true here, which silently
    // imposed --path-a-t7-max-chunks 40 (= 20,000 device steps at the default
    // chunk size) and armed the cooperative evidence_complete early exit on
    // EVERY hyper-runtime-md run. A genuine fixed-duration run could not be
    // requested. These are now typed so duration, trigger, and chunk bound are
    // explicit and recorded rather than implied by a source literal.
    /// Force every per-stream V2 trigger to this device step. Unset preserves
    /// the per-protocol cold_hold trigger.
    #[arg(long)]
    path_a_v2_trigger_steps: Option<u32>,

    /// Bound the per-stream chunk loop at this chunk index. Unset preserves the
    /// engine's default chunk bound.
    #[arg(long)]
    path_a_t7_max_chunks: Option<u32>,

    /// Enable the Path-A production convenience profile. Defaults to true so
    /// existing behavior is preserved bit-for-bit; pass
    /// `--path-a-production-profile=false` to request a genuine wall-bounded
    /// run with no premature evidence exit and no implied 20,000-step cap.
    ///
    /// Declared with an optional value rather than as a bare switch: a bare
    /// `default_value_t = true` bool compiles to clap's SetTrue action, which
    /// can only ever be set *to* true — the flag would be unsettable and the
    /// source literal it replaced would simply have moved into the CLI.
    #[arg(
        long,
        action = clap::ArgAction::Set,
        num_args = 0..=1,
        default_value_t = true,
        default_missing_value = "true"
    )]
    path_a_production_profile: bool,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum MolecularContrastKind {
    ApoHolo,
    DesignReference,
    GlycanMechanisticProbe,
    IdenticalTopologyNegativeControl,
}

/// PACKAGE E — the acceptance expectation for the G26 gearbox.
///
/// The gearbox has no engine CLI switch: `set_gearbox_active(true)` is reached
/// exactly once, from the successful V2 monolithic instantiation
/// (crates/prism-nhs/src/bin/nhs_rt_full.rs:19139). So "enable the gearbox"
/// means two separable things, and this option states both: CONFIGURE the run
/// so the V2 pipeline can instantiate, and BIND acceptance to what the produced
/// evidence then shows. Neither state passes by absence — `RequireActive` fails
/// a run whose Ghost map stamps the not-measured sentinel, and `RequireInactive`
/// fails a run that reports a device-measured gear.
#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum GearboxLivenessRequirement {
    /// Accept whichever state the run positively evidences. Still refuses a
    /// fabricated gear: the adjudication in `verify_coupled_gearbox_liveness`
    /// applies either way.
    Auto,
    /// The run is acceptable only if the gearbox was live and the gear it ran
    /// was device-measured.
    RequireActive,
    /// The run is acceptable only if the gearbox was inactive and the gear is
    /// the explicit not-measured sentinel.
    RequireInactive,
}

impl GearboxLivenessRequirement {
    fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::RequireActive => "require-active",
            Self::RequireInactive => "require-inactive",
        }
    }

    /// A live gearbox is only reachable through the V2 ignition pipeline, so
    /// requiring liveness necessarily requires V2 ignition.
    fn implies_v2_ignition(self) -> bool {
        matches!(self, Self::RequireActive)
    }
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, clap::ValueEnum)]
enum HyperRuntimeEngineSurface {
    Auto,
    CapturedGraphTwin,
    InterferometricTwin,
    Twin16,
    GhostTiles,
}

impl HyperRuntimeEngineSurface {
    fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::CapturedGraphTwin => "captured-graph-twin",
            Self::InterferometricTwin => "interferometric-twin",
            Self::Twin16 => "twin16",
            Self::GhostTiles => "ghost-tiles",
        }
    }

    fn resolved_engine_value(self, topology_b_present: bool) -> Option<&'static str> {
        match (self, topology_b_present) {
            (Self::Auto, true) => None,
            (Self::Auto, false) => Some("interferometric-twin"),
            (Self::CapturedGraphTwin, _) => Some("captured-graph-twin"),
            (Self::InterferometricTwin, _) => Some("interferometric-twin"),
            (Self::Twin16, _) => Some("twin16"),
            (Self::GhostTiles, _) => Some("ghost-tiles"),
        }
    }

    fn expected_dispatch(self, topology_b_present: bool) -> &'static str {
        if topology_b_present && self == Self::Auto {
            "coupled_twin"
        } else {
            match self.resolved_engine_value(topology_b_present) {
                Some("captured-graph-twin") => "captured_graph_twin_multi_stream",
                Some("interferometric-twin" | "twin16" | "ghost-tiles") => "multi_differential",
                _ => "multi_differential",
            }
        }
    }
}

impl MolecularContrastKind {
    fn as_str(self) -> &'static str {
        match self {
            MolecularContrastKind::ApoHolo => "apo-holo",
            MolecularContrastKind::DesignReference => "design-reference",
            MolecularContrastKind::GlycanMechanisticProbe => "glycan-mechanistic-probe",
            MolecularContrastKind::IdenticalTopologyNegativeControl => {
                "identical-topology-negative-control"
            }
        }
    }
}

