fn eval_native_stream_metrics(native_receipts: &[Value]) -> Value {
    let mut capture_total = 0u64;
    let mut replay_total = 0u64;
    let mut resident_replay_total = 0u64;
    let mut legacy_replay_total = 0u64;
    let mut collapse_min: Option<f64> = None;
    let mut collapse_max: Option<f64> = None;
    let mut all_coverage_pass = !native_receipts.is_empty();
    let mut all_coverage_bounded_or_passed = !native_receipts.is_empty();
    let mut all_hotpath_pass = !native_receipts.is_empty();
    for candidate in native_receipts {
        let json = candidate.get("json").unwrap_or(&Value::Null);
        capture_total = capture_total.saturating_add(
            json.get("cuda_graph_capture_dispatch_count")
                .and_then(Value::as_u64)
                .unwrap_or(0),
        );
        replay_total = replay_total.saturating_add(
            json.get("cuda_graph_replay_dispatch_count")
                .and_then(Value::as_u64)
                .unwrap_or(0),
        );
        resident_replay_total = resident_replay_total.saturating_add(
            json.get("resident_graph_replay_dispatch_count")
                .and_then(Value::as_u64)
                .unwrap_or(0),
        );
        legacy_replay_total = legacy_replay_total.saturating_add(
            json.get("legacy_graph_replay_dispatch_count")
                .and_then(Value::as_u64)
                .unwrap_or(0),
        );
        if let Some(collapse) = json
            .get("graph_host_launch_collapse_ratio")
            .and_then(Value::as_f64)
        {
            collapse_min = Some(collapse_min.map_or(collapse, |value| value.min(collapse)));
            collapse_max = Some(collapse_max.map_or(collapse, |value| value.max(collapse)));
        }
        let coverage_status = json
            .get("coverage_status")
            .and_then(Value::as_str)
            .unwrap_or("MISSING");
        all_coverage_pass &= coverage_status == "PASS";
        all_coverage_bounded_or_passed &= md_coverage_bounded_or_passed(coverage_status);
        all_hotpath_pass &= json
            .get("hotpath_acceleration_status")
            .and_then(Value::as_str)
            == Some("PASS");
    }
    let hotpath_status = if all_coverage_pass
        && all_hotpath_pass
        && resident_replay_total > 0
        && legacy_replay_total == 0
        && collapse_min.unwrap_or(0.0) >= 64.0
    {
        "PASS"
    } else {
        "PARTIAL"
    };
    j_obj(vec![
        ("hotpath_status", j_str(hotpath_status)),
        ("native_stream_receipt_count", j_num(native_receipts.len())),
        ("all_coverage_pass", j_bool(all_coverage_pass)),
        (
            "all_coverage_bounded_or_passed",
            j_bool(all_coverage_bounded_or_passed),
        ),
        ("all_hotpath_pass", j_bool(all_hotpath_pass)),
        ("cuda_graph_capture_dispatch_total", j_num(capture_total)),
        ("cuda_graph_replay_dispatch_total", j_num(replay_total)),
        (
            "resident_graph_replay_dispatch_total",
            j_num(resident_replay_total),
        ),
        (
            "legacy_graph_replay_dispatch_total",
            j_num(legacy_replay_total),
        ),
        (
            "min_graph_host_launch_collapse_ratio",
            collapse_min.map(j_num).unwrap_or_else(j_null),
        ),
        (
            "max_graph_host_launch_collapse_ratio",
            collapse_max.map(j_num).unwrap_or_else(j_null),
        ),
    ])
}

fn eval_log_metrics(path: &Path) -> Value {
    let text = fs::read_to_string(path).unwrap_or_default();
    let mut total_spikes = None;
    let mut stream_count = None;
    let mut wall_clock_seconds = None;
    for line in text.lines() {
        if let Some(tail) = line.split("Graceful teardown complete").nth(1) {
            let numbers = numbers_in_text(tail);
            if numbers.len() >= 3 {
                total_spikes = numbers.first().and_then(|value| value.parse::<u64>().ok());
                stream_count = numbers.get(1).and_then(|value| value.parse::<u64>().ok());
                wall_clock_seconds = numbers.get(2).and_then(|value| value.parse::<f64>().ok());
            }
        } else if let Some(tail) = line.split("All ").nth(1) {
            if tail.contains("streams complete in") && wall_clock_seconds.is_none() {
                let numbers = numbers_in_text(tail);
                if numbers.len() >= 2 {
                    stream_count = numbers.first().and_then(|value| value.parse::<u64>().ok());
                    wall_clock_seconds = numbers.get(1).and_then(|value| value.parse::<f64>().ok());
                }
            }
        }
    }
    j_obj(vec![
        (
            "total_spikes",
            total_spikes.map(j_num).unwrap_or_else(j_null),
        ),
        (
            "stream_count",
            stream_count.map(j_num).unwrap_or_else(j_null),
        ),
        (
            "wall_clock_seconds",
            wall_clock_seconds.map(j_num).unwrap_or_else(j_null),
        ),
        (
            "resident_graph_chunk_log_rows",
            j_num(text.matches("path=graph.while_resident").count()),
        ),
        (
            "legacy_graph_chunk_log_rows",
            j_num(text.matches("path=graph.legacy").count() + text.matches("path=legacy").count()),
        ),
    ])
}

fn numbers_in_text(text: &str) -> Vec<String> {
    let mut values = Vec::new();
    let mut current = String::new();
    for ch in text.chars() {
        if ch.is_ascii_digit() || ch == '.' {
            current.push(ch);
        } else if !current.is_empty() {
            if current.chars().any(|value| value.is_ascii_digit()) {
                values.push(current.clone());
            }
            current.clear();
        }
    }
    if !current.is_empty() && current.chars().any(|value| value.is_ascii_digit()) {
        values.push(current);
    }
    values
}

fn value_at<'a>(value: &'a Value, path: &[&str]) -> Option<&'a Value> {
    let mut current = value;
    for key in path {
        current = current.get(key)?;
    }
    Some(current)
}

fn count_run_files<F>(run_dir: &Path, predicate: F) -> PcResult<u64>
where
    F: Fn(&Path) -> bool,
{
    let mut count = 0u64;
    for entry in fs::read_dir(run_dir)? {
        let path = entry?.path();
        if path.is_file() && predicate(&path) {
            count += 1;
        }
    }
    Ok(count)
}

fn eval_is_raw_bulk_file(path: &Path) -> bool {
    path.file_name()
        .and_then(|value| value.to_str())
        .map(|name| {
            (name.starts_with("prism_zstr_") && name.ends_with(".bin"))
                || name.ends_with("_warp_matrix.bin")
                || name.ends_with("_signal_grid.bin")
                || name.ends_with("_forces_final.bin")
                || name.ends_with("_asc_vectors.bin")
                || name.ends_with("_aromatic_centroids_final.bin")
                || name.ends_with("_kcc_v2full.bin")
                || name.ends_with("_adaptive_dt.bin")
                || name.ends_with("_adj_flags.bin")
                || name.ends_with("_asc_trajectory.bin")
                || name.ends_with("_v2_frames.bin")
                || name.ends_with(".spatial_grid_state.json")
        })
        .unwrap_or(false)
}

fn directory_file_bytes(path: &Path) -> PcResult<u64> {
    let mut total = 0u64;
    if !path.is_dir() {
        return Ok(0);
    }
    for entry in fs::read_dir(path)? {
        let path = entry?.path();
        if path.is_dir() {
            total = total.saturating_add(directory_file_bytes(&path)?);
        } else if path.is_file() {
            total = total.saturating_add(path.metadata().map(|m| m.len()).unwrap_or(0));
        }
    }
    Ok(total)
}

