fn strict_read_bounded_utf8_v3<R: Read>(reader: &mut R, label: &str) -> PcResult<String> {
    let length = split_t7_read_u64_v3(reader, &format!("{label} byte count"))?;
    let length = usize::try_from(length)
        .map_err(|_| PcError::Security(format!("{label} byte count exceeds usize")))?;
    if length == 0 || length > 1024 * 1024 {
        return Err(PcError::Security(format!(
            "{label} has invalid bounded byte count {length}"
        )));
    }
    let mut bytes = vec![0u8; length];
    reader
        .read_exact(&mut bytes)
        .map_err(|error| PcError::Security(format!("read {label}: {error}")))?;
    String::from_utf8(bytes)
        .map_err(|error| PcError::Security(format!("{label} is not UTF-8: {error}")))
}

// Byte-identical scalar fallback from half 2.7.1. This is local because prismcode cannot
// add prism-nhs (which owns the GPU upload path) as a dependency without creating a cycle.
fn strict_f32_to_f16_bits(value: f32) -> u16 {
    let x = value.to_bits();
    let sign = x & 0x8000_0000;
    let exp = x & 0x7f80_0000;
    let man = x & 0x007f_ffff;
    if exp == 0x7f80_0000 {
        let nan_bit = if man == 0 { 0 } else { 0x0200 };
        return ((sign >> 16) | 0x7c00 | nan_bit | (man >> 13)) as u16;
    }
    let half_sign = sign >> 16;
    let unbiased_exp = ((exp >> 23) as i32) - 127;
    let half_exp = unbiased_exp + 15;
    if half_exp >= 0x1f {
        return (half_sign | 0x7c00) as u16;
    }
    if half_exp <= 0 {
        if 14 - half_exp > 24 {
            return half_sign as u16;
        }
        let man = man | 0x0080_0000;
        let mut half_man = man >> (14 - half_exp);
        let round_bit = 1u32 << (13 - half_exp);
        if (man & round_bit) != 0 && (man & (3 * round_bit - 1)) != 0 {
            half_man += 1;
        }
        return (half_sign | half_man) as u16;
    }
    let half_exp = (half_exp as u32) << 10;
    let half_man = man >> 13;
    let round_bit = 0x0000_1000;
    if (man & round_bit) != 0 && (man & (3 * round_bit - 1)) != 0 {
        (half_sign | half_exp | half_man).wrapping_add(1) as u16
    } else {
        (half_sign | half_exp | half_man) as u16
    }
}

fn strict_f16_bits_to_f32(bits: u16) -> f32 {
    if bits & 0x7fff == 0 {
        return f32::from_bits((bits as u32) << 16);
    }
    let half_sign = (bits & 0x8000) as u32;
    let half_exp = (bits & 0x7c00) as u32;
    let half_man = (bits & 0x03ff) as u32;
    if half_exp == 0x7c00 {
        return if half_man == 0 {
            f32::from_bits((half_sign << 16) | 0x7f80_0000)
        } else {
            f32::from_bits((half_sign << 16) | 0x7fc0_0000 | (half_man << 13))
        };
    }
    let sign = half_sign << 16;
    if half_exp == 0 {
        let exponent_adjust = (half_man as u16).leading_zeros() - 6;
        let exp = (127 - 15 - exponent_adjust) << 23;
        let man = (half_man << (14 + exponent_adjust)) & 0x007f_ffff;
        return f32::from_bits(sign | exp | man);
    }
    let unbiased_exp = ((half_exp as i32) >> 10) - 15;
    let exp = ((unbiased_exp + 127) as u32) << 23;
    let man = half_man << 13;
    f32::from_bits(sign | exp | man)
}

fn strict_validate_kernel_source_v3(
    binding: &StrictTwinKernelSourceBindingV3,
    expected_identity: &str,
    expected_symbols: &[&str],
) -> PcResult<PathBuf> {
    let path = PathBuf::from(&binding.path);
    let metadata = fs::symlink_metadata(&path).map_err(|error| {
        PcError::Security(format!(
            "strict kernel source cannot be inspected: path={} error={error}",
            path.display()
        ))
    })?;
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() == 0 {
        return Err(PcError::Security(format!(
            "strict kernel source must be a nonempty regular non-symlink file: {}",
            path.display()
        )));
    }
    let canonical = fs::canonicalize(&path)?;
    let expected_symbol_set = expected_symbols
        .iter()
        .map(|value| (*value).to_string())
        .collect::<BTreeSet<_>>();
    let observed_symbol_set = binding
        .required_symbols
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    if binding.kernel_identity != expected_identity
        || binding.size_bytes != metadata.len()
        || observed_symbol_set.len() != binding.required_symbols.len()
        || observed_symbol_set != expected_symbol_set
        || !exact_lower_sha256(&binding.sha256)
        || !exact_lower_sha256(&binding.blake3)
    {
        return Err(PcError::Security(format!(
            "strict kernel source identity/symbol/size contract failed: {}",
            path.display()
        )));
    }
    let sha256 = prismcode::operand_ledger::sha256_file_hex(&canonical)
        .map_err(|error| PcError::Internal(error.to_string()))?;
    let blake3 = file_hash_hex_streaming(&canonical)?;
    if sha256 != binding.sha256 || blake3 != binding.blake3 {
        return Err(PcError::Security(format!(
            "strict kernel source digest mismatch: {}",
            canonical.display()
        )));
    }
    let bytes = fs::read(&canonical)?;
    if expected_symbols.iter().any(|symbol| {
        !bytes
            .windows(symbol.len())
            .any(|window| window == symbol.as_bytes())
    }) {
        return Err(PcError::Security(format!(
            "strict kernel source lacks an executable symbol: {}",
            canonical.display()
        )));
    }
    Ok(canonical)
}

fn strict_singleton_stream_artifact<'a>(
    artifacts: &'a [serde_json::Value],
    kind: &str,
    stream_id: u64,
) -> PcResult<&'a serde_json::Value> {
    let rows = artifacts
        .iter()
        .filter(|row| {
            row.get("kind").and_then(serde_json::Value::as_str) == Some(kind)
                && row.get("stream_id").and_then(serde_json::Value::as_u64) == Some(stream_id)
        })
        .collect::<Vec<_>>();
    if rows.len() != 1 {
        return Err(PcError::Security(format!(
            "coupled-TWIN requires exactly one {kind} artifact for stream {stream_id}; observed {}",
            rows.len()
        )));
    }
    Ok(rows[0])
}

fn strict_stream_spike_matrix_v3(
    path: &Path,
    row: &serde_json::Value,
    expected_stream_id: u32,
    expected_run_id: &str,
    expected_stem: &str,
    n_residues: usize,
    total_steps: i32,
) -> PcResult<StrictTwinSpikeMatrixReadback> {
    if total_steps < STRICT_TWIN_CCF_BIN_SIZE_STEPS * 12 || n_residues < 2 {
        return Err(PcError::Security(
            "strict TE source requires at least 12 complete bins and two residues".to_string(),
        ));
    }
    let n_bins = usize::try_from(total_steps.div_euclid(STRICT_TWIN_CCF_BIN_SIZE_STEPS))
        .map_err(|_| PcError::Security("strict TE bin count exceeds usize".to_string()))?;
    let n_bins_padded = n_bins
        .checked_add(15)
        .map(|value| value / 16 * 16)
        .ok_or_else(|| PcError::Security("strict TE padded bin count overflow".to_string()))?;
    let matrix_len = n_residues
        .checked_add(15)
        .map(|value| value / 16 * 16)
        .and_then(|rows| rows.checked_mul(n_bins_padded))
        .ok_or_else(|| PcError::Security("strict TE matrix allocation overflow".to_string()))?;
    let mut matrix = vec![0.0f32; matrix_len];
    let file = File::open(path)?;
    let mut reader = std::io::BufReader::with_capacity(1024 * 1024, file);
    let mut observations_by_residue = BTreeMap::<i32, Vec<StrictTwinResidueObservationV3>>::new();
    if split_t7_read_exact_v3::<8, _>(&mut reader, "PRSPK001 magic")? != *b"PRSPK001"
        || split_t7_read_u32_v3(&mut reader, "PRSPK001 schema")? != 1
        || split_t7_read_u32_v3(&mut reader, "PRSPK001 endian")? != 0x01020304
        || split_t7_read_u32_v3(&mut reader, "PRSPK001 stream")? != expected_stream_id
    {
        return Err(PcError::Security(
            "PRSPK001 strict stream header identity failed".to_string(),
        ));
    }
    let run_id = strict_read_bounded_utf8_v3(&mut reader, "PRSPK001 run id")?;
    let stem = strict_read_bounded_utf8_v3(&mut reader, "PRSPK001 target stem")?;
    let record_count = split_t7_read_u64_v3(&mut reader, "PRSPK001 record count")?;
    let stride = split_t7_read_u64_v3(&mut reader, "PRSPK001 record stride")?;
    let payload_size = split_t7_read_u64_v3(&mut reader, "PRSPK001 payload bytes")?;
    let manifest_count = row
        .get("record_count")
        .and_then(serde_json::Value::as_u64)
        .ok_or_else(|| PcError::Security("PRSPK001 manifest row lacks record_count".to_string()))?;
    if run_id != expected_run_id
        || stem != expected_stem
        || record_count == 0
        || record_count != manifest_count
        || stride != COUPLED_SPLIT_T7_SOURCE_EVENT_BYTES as u64
        || payload_size
            != record_count
                .checked_mul(stride)
                .ok_or_else(|| PcError::Security("PRSPK001 payload size overflow".to_string()))?
        || row
            .get("schema_version")
            .and_then(serde_json::Value::as_u64)
            != Some(1)
    {
        return Err(PcError::Security(format!(
            "PRSPK001 strict stream identity/count contract failed for stream {expected_stream_id}"
        )));
    }
    let mut fnv = 0xcbf2_9ce4_8422_2325u64;
    for event_index in 0..record_count {
        let bytes = split_t7_read_exact_v3::<COUPLED_SPLIT_T7_SOURCE_EVENT_BYTES, _>(
            &mut reader,
            &format!("PRSPK001 stream {expected_stream_id} event {event_index}"),
        )?;
        for byte in bytes {
            fnv ^= u64::from(byte);
            fnv = fnv.wrapping_mul(0x0000_0100_0000_01b3);
        }
        let event = parse_split_t7_canonical_event_v3(
            bytes,
            &format!("PRSPK001 stream {expected_stream_id} event {event_index}"),
        )?;
        if event.timestep < 0
            || event.timestep >= total_steps
            || event.intensity < 0.0
            || event.position.iter().any(|value| !value.is_finite())
            || event.n_residues < 1
            || event.n_residues > event.nearby_residues.len() as i32
        {
            return Err(PcError::Security(format!(
                "PRSPK001 stream {expected_stream_id} event {event_index} violates strict time/intensity/support semantics"
            )));
        }
        let support = &event.nearby_residues[..event.n_residues as usize];
        let admitted = support
            .iter()
            .copied()
            .filter(|residue| *residue >= 0 && (*residue as usize) < n_residues)
            .collect::<Vec<_>>();
        if admitted.iter().copied().collect::<BTreeSet<_>>().len() != admitted.len() {
            return Err(PcError::Security(format!(
                "PRSPK001 stream {expected_stream_id} event {event_index} duplicates an admitted residue"
            )));
        }
        for &residue in &admitted {
            observations_by_residue.entry(residue).or_default().push(
                StrictTwinResidueObservationV3 {
                    timestep: event.timestep,
                    intensity: event.intensity,
                },
            );
        }
        let bin = usize::try_from(event.timestep / STRICT_TWIN_CCF_BIN_SIZE_STEPS)
            .map_err(|_| PcError::Security("PRSPK001 bin index conversion failed".to_string()))?;
        if bin >= n_bins {
            continue;
        }
        for &residue in &admitted {
            let index = (residue as usize)
                .checked_mul(n_bins_padded)
                .and_then(|base| base.checked_add(bin))
                .ok_or_else(|| PcError::Security("PRSPK001 matrix index overflow".to_string()))?;
            matrix[index] += event.intensity;
            if !matrix[index].is_finite() {
                return Err(PcError::Security(format!(
                    "PRSPK001 stream {expected_stream_id} binned intensity overflowed"
                )));
            }
        }
    }
    let embedded_fnv = split_t7_read_u64_v3(&mut reader, "PRSPK001 payload FNV-1a")?;
    let trailer = split_t7_read_exact_v3::<8, _>(&mut reader, "PRSPK001 trailer")?;
    let mut trailing = [0u8; 1];
    if embedded_fnv != fnv || trailer != *b"PRSPKEND" || reader.read(&mut trailing)? != 0 {
        return Err(PcError::Security(format!(
            "PRSPK001 stream {expected_stream_id} failed checksum/trailer/EOF validation"
        )));
    }
    for residue in 0..n_residues {
        let start = residue * n_bins_padded;
        let mean = matrix[start..start + n_bins].iter().copied().sum::<f32>() / n_bins as f32;
        for value in &mut matrix[start..start + n_bins] {
            let centered = (*value - mean).clamp(-65504.0, 65504.0);
            *value = strict_f16_bits_to_f32(strict_f32_to_f16_bits(centered));
        }
    }
    for observations in observations_by_residue.values_mut() {
        observations.sort_by(|left, right| {
            left.timestep
                .cmp(&right.timestep)
                .then_with(|| left.intensity.total_cmp(&right.intensity))
        });
    }
    Ok(StrictTwinSpikeMatrixReadback {
        source_sha256: prismcode::operand_ledger::sha256_file_hex(path)
            .map_err(|error| PcError::Internal(error.to_string()))?,
        record_count,
        n_bins,
        n_bins_padded,
        quantized_centered_matrix: matrix,
        observations_by_residue,
    })
}

fn strict_binned_te_pair_v3(
    source: &[f32],
    target: &[f32],
    source_mean: f32,
    target_mean: f32,
) -> f32 {
    debug_assert_eq!(source.len(), target.len());
    let mut counts = [0u32; 8];
    for t in 1..source.len().saturating_sub(1) {
        let source_past = usize::from(source[t - 1] > source_mean);
        let target_past = usize::from(target[t - 1] > target_mean);
        let target_future = usize::from(target[t + 1] > target_mean);
        counts[source_past * 4 + target_past * 2 + target_future] += 1;
    }
    let total = source.len().saturating_sub(2) as u32;
    if total < STRICT_TWIN_TE_MINIMUM_TRANSITION_SAMPLES {
        return 0.0;
    }
    let inverse_total = 1.0f32 / total as f32;
    let mut te = 0.0f32;
    for source_past in 0..2 {
        for target_past in 0..2 {
            let count = |sp: usize, tp: usize, tf: usize| counts[sp * 4 + tp * 2 + tf];
            let n_target_past = count(0, target_past, 0)
                + count(0, target_past, 1)
                + count(1, target_past, 0)
                + count(1, target_past, 1);
            if n_target_past == 0 {
                continue;
            }
            for target_future in 0..2 {
                let n_joint = count(source_past, target_past, target_future);
                if n_joint == 0 {
                    continue;
                }
                let n_source_target_past =
                    count(source_past, target_past, 0) + count(source_past, target_past, 1);
                let n_target_past_future =
                    count(0, target_past, target_future) + count(1, target_past, target_future);
                if n_source_target_past == 0 || n_target_past_future == 0 {
                    continue;
                }
                let p_joint = n_joint as f32 * inverse_total;
                let p_full = n_joint as f32 / n_source_target_past as f32;
                let p_marginal = n_target_past_future as f32 / n_target_past as f32;
                let ratio = p_full / p_marginal.max(1.0e-10);
                te += p_joint * ratio.max(1.0e-10).log2();
            }
        }
    }
    te.max(0.0)
}

fn strict_cpu_te_reference_v3(
    stream_a: &StrictTwinSpikeMatrixReadback,
    stream_b: &StrictTwinSpikeMatrixReadback,
    n_residues: usize,
    total_steps: i32,
) -> PcResult<StrictTwinCpuTeReference> {
    if stream_a.n_bins != stream_b.n_bins
        || stream_a.n_bins_padded != stream_b.n_bins_padded
        || stream_a.quantized_centered_matrix.len() != stream_b.quantized_centered_matrix.len()
    {
        return Err(PcError::Security(
            "strict TE source matrices have incompatible shapes".to_string(),
        ));
    }
    let n_bins = stream_a.n_bins;
    let stride = stream_a.n_bins_padded;
    let mut means_a = Vec::with_capacity(n_residues);
    let mut means_b = Vec::with_capacity(n_residues);
    for residue in 0..n_residues {
        let start = residue * stride;
        means_a.push(
            stream_a.quantized_centered_matrix[start..start + n_bins]
                .iter()
                .copied()
                .sum::<f32>()
                / n_bins as f32,
        );
        means_b.push(
            stream_b.quantized_centered_matrix[start..start + n_bins]
                .iter()
                .copied()
                .sum::<f32>()
                / n_bins as f32,
        );
    }
    let matrix_count = n_residues
        .checked_mul(n_residues)
        .ok_or_else(|| PcError::Security("strict TE pair count overflow".to_string()))?;
    let mut a_to_b = vec![0.0f32; matrix_count];
    let mut b_to_a = vec![0.0f32; matrix_count];
    for source_residue in 0..n_residues {
        let source_a_start = source_residue * stride;
        let source_b_start = source_residue * stride;
        for target_residue in 0..n_residues {
            if source_residue == target_residue {
                continue;
            }
            let target_a_start = target_residue * stride;
            let target_b_start = target_residue * stride;
            let index = source_residue * n_residues + target_residue;
            a_to_b[index] = strict_binned_te_pair_v3(
                &stream_a.quantized_centered_matrix[source_a_start..source_a_start + n_bins],
                &stream_b.quantized_centered_matrix[target_b_start..target_b_start + n_bins],
                means_a[source_residue],
                means_b[target_residue],
            );
            b_to_a[index] = strict_binned_te_pair_v3(
                &stream_b.quantized_centered_matrix[source_b_start..source_b_start + n_bins],
                &stream_a.quantized_centered_matrix[target_a_start..target_a_start + n_bins],
                means_b[source_residue],
                means_a[target_residue],
            );
        }
    }
    let mut bidirectional_mass = vec![0.0f32; n_residues];
    let mut net_causal_flow = vec![0.0f32; n_residues];
    let mut thresholded_outgoing = vec![0.0f32; n_residues];
    for residue in 0..n_residues {
        let mut mass = 0.0f32;
        let mut outgoing = 0.0f32;
        let mut incoming = 0.0f32;
        let mut thresholded = 0.0f32;
        for partner in 0..n_residues {
            if partner == residue {
                continue;
            }
            let ab = a_to_b[residue * n_residues + partner];
            let ba = b_to_a[partner * n_residues + residue];
            mass += (ab + ba) * 0.5;
            outgoing += ab;
            incoming += ba;
            if ab > STRICT_TWIN_TE_OUTGOING_TERM_FLOOR_EXCLUSIVE {
                thresholded += ab;
            }
        }
        bidirectional_mass[residue] = mass;
        net_causal_flow[residue] = outgoing - incoming;
        thresholded_outgoing[residue] = thresholded;
    }
    if bidirectional_mass
        .iter()
        .chain(&net_causal_flow)
        .chain(&thresholded_outgoing)
        .any(|value| !value.is_finite())
    {
        return Err(PcError::Security(
            "strict CPU TE reference produced nonfinite output".to_string(),
        ));
    }
    let mut identity = Vec::new();
    identity.extend_from_slice(b"PRISMOS_STRICT_TWIN_CPU_TE_REFERENCE_V3\0");
    identity.extend_from_slice(stream_a.source_sha256.as_bytes());
    identity.extend_from_slice(stream_b.source_sha256.as_bytes());
    identity.extend_from_slice(&total_steps.to_le_bytes());
    identity.extend_from_slice(&(n_residues as u64).to_le_bytes());
    identity.extend_from_slice(&(n_bins as u64).to_le_bytes());
    identity.extend_from_slice(&(n_bins.saturating_sub(2) as u64).to_le_bytes());
    for value in bidirectional_mass
        .iter()
        .chain(&net_causal_flow)
        .chain(&thresholded_outgoing)
    {
        identity.extend_from_slice(&value.to_bits().to_le_bytes());
    }
    Ok(StrictTwinCpuTeReference {
        bidirectional_mass,
        net_causal_flow,
        thresholded_outgoing,
        identity_sha256: sha256_bytes_hex(&identity),
    })
}

fn strict_numeric_summary(values: &[f32]) -> PcResult<(u64, f64, f32)> {
    if values.iter().any(|value| !value.is_finite()) {
        return Err(PcError::Security(
            "strict numeric summary received nonfinite values".to_string(),
        ));
    }
    Ok((
        values
            .iter()
            .filter(|value| value.to_bits() & 0x7fff_ffff != 0)
            .count() as u64,
        values
            .iter()
            .map(|value| f64::from(*value) * f64::from(*value))
            .sum::<f64>()
            .sqrt(),
        values.iter().map(|value| value.abs()).fold(0.0, f32::max),
    ))
}

fn strict_te_max_error(reference: &[f32], observed: &[f32]) -> PcResult<f32> {
    if reference.len() != observed.len() {
        return Err(PcError::Security(
            "strict TE reference/observed lengths differ".to_string(),
        ));
    }
    let mut maximum = 0.0f32;
    for (expected, actual) in reference.iter().zip(observed) {
        if !expected.is_finite() || !actual.is_finite() {
            return Err(PcError::Security(
                "strict TE comparison received nonfinite output".to_string(),
            ));
        }
        let error = (*expected - *actual).abs();
        let tolerance = STRICT_TWIN_TE_CPU_REFERENCE_ABSOLUTE_TOLERANCE
            + STRICT_TWIN_TE_CPU_REFERENCE_RELATIVE_TOLERANCE * expected.abs().max(actual.abs())
            + STRICT_TWIN_TE_CPU_REFERENCE_PAIR_ACCUMULATION_TOLERANCE * reference.len() as f32;
        if error > tolerance {
            return Err(PcError::Security(format!(
                "strict GPU TE output differs from independent CPU reference: expected={expected:.9} observed={actual:.9} error={error:.9} tolerance={tolerance:.9}"
            )));
        }
        maximum = maximum.max(error);
    }
    Ok(maximum)
}

