fn recompute_molecular_contrast_pocket_v4(
    pocket_residue_ids: &BTreeSet<i32>,
    residue_rows_by_id: &BTreeMap<i32, &StrictMolecularContrastResidueV3>,
    strict_residue_ids: &BTreeSet<i32>,
) -> PcResult<RecomputedMolecularContrastPocketV4> {
    let mut decisions = Vec::with_capacity(pocket_residue_ids.len());
    let mut l1_signed_contrast = 0.0f64;
    let mut supported_residue_count = 0u32;
    for &residue_id in pocket_residue_ids {
        let row = residue_rows_by_id.get(&residue_id).copied();
        let event_row_present = row.is_some();
        let strict_residue_row_present = strict_residue_ids.contains(&residue_id);
        if event_row_present != strict_residue_row_present {
            return Err(PcError::Security(format!(
                "pocket residue {residue_id} event/strict support masks disagree"
            )));
        }
        let abs_signed_count_contrast = if let Some(row) = row {
            let denominator = u64::from(row.spikes_a) + u64::from(row.spikes_b);
            if denominator == 0 {
                return Err(PcError::Security(format!(
                    "supported pocket residue {residue_id} has zero event support"
                )));
            }
            let magnitude = row.signed_count_contrast.abs();
            if !magnitude.is_finite() || !(0.0..=1.0).contains(&magnitude) {
                return Err(PcError::Security(format!(
                    "supported pocket residue {residue_id} has invalid contrast magnitude"
                )));
            }
            l1_signed_contrast += f64::from(magnitude);
            supported_residue_count = supported_residue_count
                .checked_add(1)
                .ok_or_else(|| PcError::Security("pocket support count overflow".to_string()))?;
            Some(magnitude)
        } else {
            None
        };
        decisions.push(StrictMolecularContrastPocketResidueDecisionV4 {
            residue_id: usize::try_from(residue_id)
                .map_err(|_| PcError::Security("pocket residue ID is negative".to_string()))?,
            event_row_present,
            strict_residue_row_present,
            contrast_supported: abs_signed_count_contrast.is_some(),
            abs_signed_count_contrast,
            support_status: if event_row_present {
                MOLECULAR_CONTRAST_POCKET_SUPPORTED
            } else {
                MOLECULAR_CONTRAST_POCKET_UNAVAILABLE
            }
            .to_string(),
        });
    }
    let candidate_residue_count = u32::try_from(decisions.len())
        .map_err(|_| PcError::Security("pocket candidate count exceeds u32".to_string()))?;
    let unavailable_residue_count = candidate_residue_count
        .checked_sub(supported_residue_count)
        .ok_or_else(|| PcError::Security("pocket support partition underflow".to_string()))?;
    let mean_abs_signed_contrast = if supported_residue_count == 0 {
        None
    } else {
        Some(l1_signed_contrast / f64::from(supported_residue_count))
    };
    Ok(RecomputedMolecularContrastPocketV4 {
        decisions,
        candidate_residue_count,
        supported_residue_count,
        unavailable_residue_count,
        l1_signed_contrast,
        mean_abs_signed_contrast,
    })
}

fn verify_molecular_contrast_pocket_report_v4(
    reported: &RecomputedMolecularContrastPocketV4,
    expected: &RecomputedMolecularContrastPocketV4,
) -> PcResult<()> {
    let decisions_match = reported.decisions.len() == expected.decisions.len()
        && reported
            .decisions
            .iter()
            .zip(&expected.decisions)
            .all(|(observed, expected)| {
                observed.residue_id == expected.residue_id
                    && observed.event_row_present == expected.event_row_present
                    && observed.strict_residue_row_present == expected.strict_residue_row_present
                    && observed.contrast_supported == expected.contrast_supported
                    && observed.support_status == expected.support_status
                    && observed.abs_signed_count_contrast.map(f32::to_bits)
                        == expected.abs_signed_count_contrast.map(f32::to_bits)
            });
    if !decisions_match
        || reported.candidate_residue_count != expected.candidate_residue_count
        || reported.supported_residue_count != expected.supported_residue_count
        || reported.unavailable_residue_count != expected.unavailable_residue_count
        || reported.l1_signed_contrast.to_bits() != expected.l1_signed_contrast.to_bits()
        || reported.mean_abs_signed_contrast.map(f64::to_bits)
            != expected.mean_abs_signed_contrast.map(f64::to_bits)
    {
        return Err(PcError::Security(
            "molecular contrast pocket V4 report does not match independent support recomputation"
                .to_string(),
        ));
    }
    Ok(())
}

