fn build_prismos_isa_execution_plan(
    args: &RunMdArgs,
    topology: &Path,
    packet: &Path,
    qnanl_force_kernel_packet: Option<&Path>,
    cuda_opcode_coverage: &Path,
) -> Value {
    let effective_save_trajectory_interval = requested_trajectory_interval(args);
    let effective_path_a_chunk_size = if args.temporal_fidelity.requires_exact_chronology_cadence()
        && args.path_a_chunk_size > effective_save_trajectory_interval
    {
        effective_save_trajectory_interval
    } else {
        args.path_a_chunk_size.max(1)
    };
    let effective_min_hotpath_launch_collapse =
        if args.temporal_fidelity.requires_exact_chronology_cadence()
            && args.require_hotpath_acceleration
        {
            args.min_hotpath_launch_collapse
                .max(1.0)
                .min(effective_path_a_chunk_size as f64)
        } else {
            args.min_hotpath_launch_collapse.max(1.0)
        };
    j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_prismcode_isa_execution_plan"),
        ),
        ("schema_version", j_num(1)),
        ("status", j_str("DECLARED")),
        (
            "operator_surface",
            j_str("prismos run profile; raw md-run arguments are internal launch ABI"),
        ),
        (
            "topology",
            j_str(topology.display().to_string()),
        ),
        (
            "prismcode_substrate_packet",
            j_str(packet.display().to_string()),
        ),
        (
            "governed_input_authority",
            match (
                args.canonical_input_locator.as_ref(),
                args.expected_input_sha256.as_ref(),
            ) {
                (Some(locator), Some(sha256)) => j_obj(vec![
                    ("locator", j_str(locator.display().to_string())),
                    ("sha256", j_str(sha256.clone())),
                    ("admission_phase", j_str("PRE_NATIVE_CUDA")),
                ]),
                _ => j_null(),
            },
        ),
        (
            "qnanl_force_kernel_packet",
            j_path_opt(qnanl_force_kernel_packet),
        ),
        (
            "cuda_opcode_coverage_target",
            j_str(cuda_opcode_coverage.display().to_string()),
        ),
        (
            "runtime_hotpath_contract",
            j_obj(vec![
                ("runtime", j_str("nhs_rt_full")),
                ("execution_mode", j_str("native_prismcode_md_opcode_dispatch_cuda_macro_fused")),
                ("metal_resident_md_required", j_bool(args.require_metal_resident_md)),
                ("cuda_graph_native_required", j_bool(args.require_cuda_graph_native)),
                (
                    "hotpath_acceleration_required",
                    j_bool(args.require_hotpath_acceleration),
                ),
                (
                    "min_hotpath_launch_collapse",
                    j_num(effective_min_hotpath_launch_collapse),
                ),
                (
                    "required_evidence",
                    j_string_array(&[
                        "prismcode_substrate_receipt.status == PASS",
                        "native MD receipt per stream",
                        "coverage_status == PASS for every fully materialized native MD receipt",
                        "bounded TWIN16 native MD receipts may report coverage_status == BOUNDED_MATERIALIZATION_REQUIRED only when MD.SPIKE_READOUT is observed and SIGNAL_GRID/KCC materialization is explicitly blocked until canonical materialization",
                        "required_core_opcodes present in opcode_counts for every native MD receipt",
                        "cuda_graph_capture_dispatch_count > 0 for every native MD receipt",
                        "cuda_graph_replay_dispatch_count > 0 for every native MD receipt",
                        "resident_graph_replay_dispatch_count > 0 for every native MD receipt when metal_resident_md_required=true",
                        "legacy_graph_replay_dispatch_count == 0 for every native MD receipt when metal_resident_md_required=true",
                        "graph_host_launch_collapse_ratio >= min_hotpath_launch_collapse when hotpath_acceleration_required=true",
                    ]),
                ),
            ]),
        ),
        (
            "substrate_prismops",
            j_string_array(&substrate_prismop_contract()),
        ),
        (
            "md_prismops_known_instruction_set",
            j_string_array(&md_prismop_known_instruction_set()),
        ),
        (
            "md_prismops_required_core_contract",
            j_string_array(&md_prismop_required_core_contract()),
        ),
        (
            "codec_prismops_required_contract",
            j_string_array(&codec_prismop_contract()),
        ),
        (
            "artifact_codec_surfaces",
            j_string_array(&prismos_artifact_codec_surfaces()),
        ),
    ])
}

fn value_string_vec(value: Option<&Value>) -> Vec<String> {
    match value {
        Some(Value::Array(items)) => items
            .iter()
            .filter_map(|item| item.as_str().map(str::to_string))
            .collect(),
        _ => Vec::new(),
    }
}

fn opcode_count(json: &Value, opcode: &str) -> u64 {
    json.get("opcode_counts")
        .and_then(|counts| counts.get(opcode))
        .and_then(Value::as_u64)
        .unwrap_or(0)
}

fn md_coverage_bounded_or_passed(status: &str) -> bool {
    status == "PASS"
}

fn build_prismos_isa_execution_verification(
    plan_path: &Path,
    plan_hash_blake3: &str,
    native_receipt_path: &Path,
    cuda_opcode_coverage: &Path,
    native_md_receipt_candidates: &[Value],
    require_metal_resident_md: bool,
    require_hotpath_acceleration: bool,
    min_hotpath_launch_collapse: f64,
) -> Value {
    let substrate_receipt = read_json_optional(native_receipt_path);
    let substrate_status = substrate_receipt
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("MISSING");
    let required_core: Vec<String> = md_prismop_required_core_contract()
        .into_iter()
        .map(str::to_string)
        .collect();
    let known_md: Vec<String> = md_prismop_known_instruction_set()
        .into_iter()
        .map(str::to_string)
        .collect();
    let mut all_streams_pass = !native_md_receipt_candidates.is_empty();
    let mut all_streams_bounded_or_passed = !native_md_receipt_candidates.is_empty();
    let mut stream_rows = Vec::new();
    for candidate in native_md_receipt_candidates {
        let json = candidate.get("json").unwrap_or(&Value::Null);
        let coverage_status = json
            .get("coverage_status")
            .and_then(Value::as_str)
            .unwrap_or("MISSING");
        let receipt_conditionals = value_string_vec(json.get("required_conditional_opcodes"));
        // P2 — UV-OFF CONTROL. A run that declared `--uv-burst-suppress` never
        // launches `nhs_uv_pump_probe_step`, so its op stream carries
        // MD.PHOTO_UV_PUMP_SUPPRESSED in place of MD.PHOTO_UV_PUMP (producer:
        // md_native_runtime.rs core_required_opcodes). The governor keeps
        // authority over what the swap MEANS — the receipt only DECLARES its UV
        // mode, it cannot drop a required opcode. Without this swap a genuine
        // UV-off control would report `missing_required: ["MD.PHOTO_UV_PUMP"]`,
        // converting the control capability into a deny.
        let stream_uv_burst_suppressed = json
            .get("uv_burst_suppressed")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let mut required_this_stream: Vec<String> = if stream_uv_burst_suppressed {
            required_core
                .iter()
                .map(|opcode| {
                    if opcode == "MD.PHOTO_UV_PUMP" {
                        "MD.PHOTO_UV_PUMP_SUPPRESSED".to_string()
                    } else {
                        opcode.clone()
                    }
                })
                .collect()
        } else {
            required_core.clone()
        };
        for opcode in receipt_conditionals {
            if !required_this_stream
                .iter()
                .any(|existing| existing == &opcode)
            {
                required_this_stream.push(opcode);
            }
        }
        let missing_required: Vec<String> = required_this_stream
            .iter()
            .filter(|opcode| opcode_count(json, opcode) == 0)
            .cloned()
            .collect();
        let materialization_required: Vec<String> =
            value_string_vec(json.get("materialization_required_readout_opcodes"));
        let observed_known: Vec<Value> = known_md
            .iter()
            .map(|opcode| {
                j_obj(vec![
                    ("opcode", j_str(opcode)),
                    ("count", j_num(opcode_count(json, opcode))),
                    ("observed", j_bool(opcode_count(json, opcode) > 0)),
                ])
            })
            .collect();
        let capture_dispatches = json
            .get("cuda_graph_capture_dispatch_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let replay_dispatches = json
            .get("cuda_graph_replay_dispatch_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let resident_replays = json
            .get("resident_graph_replay_dispatch_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let legacy_replays = json
            .get("legacy_graph_replay_dispatch_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let launch_collapse = json
            .get("graph_host_launch_collapse_ratio")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);
        let graph_dispatch_pass = capture_dispatches > 0 && replay_dispatches > 0;
        let metal_resident_pass =
            !require_metal_resident_md || (resident_replays > 0 && legacy_replays == 0);
        let hotpath_pass =
            !require_hotpath_acceleration || launch_collapse >= min_hotpath_launch_collapse;
        let stream_pass = coverage_status == "PASS"
            && missing_required.is_empty()
            && graph_dispatch_pass
            && metal_resident_pass
            && hotpath_pass;
        let stream_bounded_or_passed = md_coverage_bounded_or_passed(coverage_status)
            && missing_required.is_empty()
            && graph_dispatch_pass
            && metal_resident_pass
            && hotpath_pass;
        all_streams_pass &= stream_pass;
        all_streams_bounded_or_passed &= stream_bounded_or_passed;
        stream_rows.push(j_obj(vec![
            (
                "path",
                candidate.get("path").cloned().unwrap_or_else(j_null),
            ),
            (
                "status",
                j_str(if stream_pass {
                    "PASS"
                } else if stream_bounded_or_passed {
                    "PARTIAL"
                } else {
                    "FAIL"
                }),
            ),
            ("coverage_status", j_str(coverage_status)),
            (
                "bounded_or_passed_status",
                j_str(if stream_bounded_or_passed {
                    if stream_pass {
                        "PASS"
                    } else {
                        "PARTIAL"
                    }
                } else {
                    "FAIL"
                }),
            ),
            (
                "required_this_stream",
                j_array(required_this_stream.iter().map(j_str).collect()),
            ),
            (
                "missing_required_prismops",
                j_array(missing_required.iter().map(j_str).collect()),
            ),
            (
                "materialization_required_readout_opcodes",
                j_array(materialization_required.iter().map(j_str).collect()),
            ),
            ("known_md_prismop_observation", j_array(observed_known)),
            (
                "cuda_graph_capture_dispatch_count",
                j_num(capture_dispatches),
            ),
            ("cuda_graph_replay_dispatch_count", j_num(replay_dispatches)),
            (
                "resident_graph_replay_dispatch_count",
                j_num(resident_replays),
            ),
            ("legacy_graph_replay_dispatch_count", j_num(legacy_replays)),
            (
                "metal_resident_md_required",
                j_bool(require_metal_resident_md),
            ),
            (
                "metal_resident_requirement_status",
                j_str(if metal_resident_pass { "PASS" } else { "FAIL" }),
            ),
            (
                "hotpath_acceleration_required",
                j_bool(require_hotpath_acceleration),
            ),
            (
                "hotpath_requirement_status",
                j_str(if hotpath_pass { "PASS" } else { "FAIL" }),
            ),
            (
                "graph_host_launch_collapse_ratio",
                j_num(format!("{launch_collapse:.9}")),
            ),
            (
                "dispatch_trace_hash_blake3",
                json.get("dispatch_trace_hash_blake3")
                    .cloned()
                    .unwrap_or_else(j_null),
            ),
        ]));
    }
    let cuda_coverage_exists = cuda_opcode_coverage.is_file();
    let status = substrate_status == "PASS" && cuda_coverage_exists && all_streams_pass;
    let partial_status =
        substrate_status == "PASS" && cuda_coverage_exists && all_streams_bounded_or_passed;
    j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_prismcode_isa_execution_verification"),
        ),
        ("schema_version", j_num(1)),
        (
            "status",
            j_str(if status {
                "PASS"
            } else if partial_status {
                "PARTIAL"
            } else {
                "FAIL"
            }),
        ),
        (
            "implementation_status_language",
            j_str(if status {
                "IMPLEMENTATION_VERIFIED"
            } else if partial_status {
                "IMPLEMENTATION_PARTIAL"
            } else {
                "IMPLEMENTATION_PARTIAL"
            }),
        ),
        ("plan_path", j_str(plan_path.display().to_string())),
        ("plan_hash_blake3", j_str(plan_hash_blake3)),
        (
            "native_prismcode_substrate_receipt_path",
            j_str(native_receipt_path.display().to_string()),
        ),
        ("substrate_status", j_str(substrate_status)),
        (
            "cuda_opcode_coverage_path",
            j_str(cuda_opcode_coverage.display().to_string()),
        ),
        ("cuda_opcode_coverage_exists", j_bool(cuda_coverage_exists)),
        (
            "native_md_receipt_count",
            j_num(native_md_receipt_candidates.len()),
        ),
        ("all_streams_pass", j_bool(all_streams_pass)),
        (
            "all_streams_bounded_or_passed",
            j_bool(all_streams_bounded_or_passed),
        ),
        (
            "metal_resident_md_required",
            j_bool(require_metal_resident_md),
        ),
        (
            "hotpath_acceleration_required",
            j_bool(require_hotpath_acceleration),
        ),
        (
            "min_hotpath_launch_collapse",
            j_num(min_hotpath_launch_collapse),
        ),
        ("streams", j_array(stream_rows)),
    ])
}

/// PHASE-1 NATIVE-CORPUS CLOSURE (IsaRegistrySummary, discriminant 42): derive a FLAT by-value ISA
/// registry×receipt coverage matrix from the in-memory execution PLAN + VERIFICATION Values.
///
/// The two RAW artifacts cannot be routed by value at opcode granularity as-is: the plan's ISA
/// registry (`md_prismops_known_instruction_set`) is a bare STRING ARRAY (the tokenizer's
/// route_object needs OBJECT records), and the verification's per-opcode observations sit TWO levels
/// deep (`streams[].known_md_prismop_observation[]`) while the tokenizer's resolve_path descends only
/// ONE `/key` level. This emitter flattens the plan×verification cross-product into a top-level
/// `records[]` array of one per-(stream,opcode) observation each, wrapped with a unique `schema_kind`
/// so the tokenizer's detect_family descends `/records` and routes every record by value.
///
/// BY-VALUE invariants held on real apo_cryptic data (8 streams × 25 opcodes = 200 records):
///   INV-A  per stream: distinct(opcode) == count(records) == registry_size == 25
///   INV-B  set(record.opcode) == set(md_prismop_known_instruction_set) exactly
///   INV-C  every required_core record has observed == true
///   INV-D  distinct(stream_id) == native_md_receipt_count == len(streams)
fn build_prismos_isa_registry_summary(plan: &Value, verification: &Value) -> Value {
    let known: Vec<&str> = plan
        .get("md_prismops_known_instruction_set")
        .and_then(Value::as_array)
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let registry_size = known.len() as u64;
    let required: BTreeSet<&str> = plan
        .get("md_prismops_required_core_contract")
        .and_then(Value::as_array)
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let required_core_size = required.len() as u64;
    let empty: &[Value] = &[];
    let streams = verification
        .get("streams")
        .and_then(Value::as_array)
        .unwrap_or(empty);
    let native_md_receipt_count = verification
        .get("native_md_receipt_count")
        .and_then(Value::as_u64)
        .unwrap_or(streams.len() as u64);

    let mut records: Vec<Value> = Vec::with_capacity(streams.len() * known.len());
    for (stream_id, stream) in streams.iter().enumerate() {
        let stream_status = stream
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("MISSING")
            .to_string();
        let stream_coverage_status = stream
            .get("coverage_status")
            .and_then(Value::as_str)
            .unwrap_or("MISSING")
            .to_string();
        let obs = stream
            .get("known_md_prismop_observation")
            .and_then(Value::as_array);
        for (opcode_index, opcode) in known.iter().enumerate() {
            // Look up the per-opcode observation by NAME (never positional) — order-independent.
            let (count, observed) = obs
                .and_then(|arr| {
                    arr.iter()
                        .find(|o| o.get("opcode").and_then(Value::as_str) == Some(*opcode))
                })
                .map(|o| {
                    (
                        o.get("count").and_then(Value::as_u64).unwrap_or(0),
                        o.get("observed").and_then(Value::as_bool).unwrap_or(false),
                    )
                })
                .unwrap_or((0, false));
            records.push(j_obj(vec![
                ("stream_id", j_num(stream_id as u64)),
                ("opcode", j_str(*opcode)),
                ("opcode_index", j_num(opcode_index as u64)),
                ("count", j_num(count)),
                ("observed", j_bool(observed)),
                ("planned", j_bool(true)),
                ("required_core", j_bool(required.contains(*opcode))),
                ("registry_size", j_num(registry_size)),
                ("required_core_size", j_num(required_core_size)),
                ("native_md_receipt_count", j_num(native_md_receipt_count)),
                ("stream_status", j_str(stream_status.clone())),
                (
                    "stream_coverage_status",
                    j_str(stream_coverage_status.clone()),
                ),
            ]));
        }
    }

    j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_prismcode_isa_registry_summary"),
        ),
        ("schema_version", j_num(1u64)),
        ("registry_size", j_num(registry_size)),
        ("required_core_size", j_num(required_core_size)),
        ("native_md_receipt_count", j_num(native_md_receipt_count)),
        ("record_count", j_num(records.len() as u64)),
        ("records", j_array(records)),
    ])
}

/// PHASE-1 NATIVE-CORPUS CLOSURE (PredictionState, discriminant 45): assemble ONE FIRST-CLASS
/// prediction record per PROMOTED materialized binding site. Operator correction 2026-07-01: a
/// PREDICTION STATE (a hypothesis ABOUT a binding site — a predicted surface with by-value
/// confidence/uncertainty and evidence lineage) is a DISTINCT epistemic object from a
/// next-operator recommendation (an engine-owner WORK LIST); this SUPERSEDES the earlier
/// DstwNextOperator-alias closure and routes INDEPENDENTLY (schema_kind == "prismos_prediction_state").
///
/// Every field is decoded BY VALUE from a REAL source (no placeholders/constants):
///   - confidence   = binding_sites.materialized[i].manifold_consistency.manifold_consistency_score
///                    (REAL ∈[0,1], VARIES across sites — 0.108..0.6475 in apo_cryptic).
///   - uncertainty  = centroid_spread_a normalized spread/(1+spread) (REAL ∈[0,1), VARIES).
///   - predicted_delta = new_prism_rank − old_density_rank (signed permutation-vs-density delta).
///   - source_vertex_id / target_vertex_id / evidence_parent_ids = the PATHB.MATERIALIZE_BINDING_SITE
///     transition's REAL vtx_ ids from PRISM_NATIVE_STATE_GRAPH.jsonl (each resolves to a vertex_id).
///   - operator_recommendation_id = next_operator_recommendation rank-1 operator.
///   - qnanl_receipt_ref = validation_state.pathb_site_records.sha256 (materialized artifact receipt).
///   - runtime_origin = validation_state.pathb_site_records.runtime_origin.
///
/// BY-VALUE invariants (verified downstream on real bytes): n_records == n_materialized_sites ==
/// len(binding_sites.materialized); confidence AND uncertainty vary (never a constant); every vertex
/// id ∈ state-graph vertex_id set.
fn build_prismos_prediction_state(
    binding_sites_materialized: &Value,
    site_accuracy: &Value,
    validation_state: &Value,
    next_operator_recommendation: &Value,
    state_graph: &[Value],
) -> Value {
    // --- run-level identity + provenance (REAL, from validation_state) -----------------------------
    let target_id = validation_state
        .get("target_id")
        .and_then(Value::as_str)
        .unwrap_or("unknown_target")
        .to_string();
    let ligand_state = validation_state
        .get("ligand_state")
        .and_then(Value::as_str)
        .unwrap_or("apo")
        .to_string();
    let receptor_state = if ligand_state.contains("holo") {
        "holo"
    } else {
        "apo"
    }
    .to_string();
    let pathb = validation_state.get("pathb_site_records");
    let runtime_origin = pathb
        .and_then(|p| p.get("runtime_origin"))
        .and_then(Value::as_str)
        .unwrap_or("RUNTIME_SUBPROCESS_ORCHESTRATED_BY_PRISMOS")
        .to_string();
    let qnanl_receipt_ref = pathb
        .and_then(|p| p.get("sha256"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();

    // --- validation / falsification posture (REAL, from site_accuracy_report) ----------------------
    let validation_computable = site_accuracy
        .get("validation_computable")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let validation_status = if validation_computable {
        "computable"
    } else {
        "reference_unavailable"
    }
    .to_string();
    let falsification_status = site_accuracy
        .get("ground_truth_status")
        .and_then(Value::as_str)
        .unwrap_or("reference_unavailable")
        .to_string();
    let n_materialized_sites = site_accuracy
        .get("n_materialized_sites")
        .and_then(Value::as_u64);

    // --- next-operator recommendation id (REAL, rank-1 operator) -----------------------------------
    let operator_recommendation_id = next_operator_recommendation
        .get("priority_ordered_recommendations")
        .and_then(Value::as_array)
        .and_then(|a| a.first())
        .map(|r| {
            let rank = r.get("rank").and_then(Value::as_u64).unwrap_or(0);
            let op = r
                .get("operator")
                .and_then(Value::as_str)
                .unwrap_or("UNKNOWN");
            format!("rank{}::{}", rank, op)
        })
        .unwrap_or_else(|| "none".to_string());

    // --- state-graph vertex resolution (REAL vtx_ ids) ---------------------------------------------
    // Collect every real vertex_id, then bind source/target to the PATHB.MATERIALIZE_BINDING_SITE
    // transition (the edge that produced the materialized sites). Fall back — ONLY if that transition
    // is absent — to the post_binding_sites vertex as target + the pre/post_md vertex as source
    // (still REAL graph vertex ids, never fabricated).
    let mut vertex_ids: BTreeSet<String> = BTreeSet::new();
    let mut post_pathb_vertex = String::new();
    let mut md_vertex = String::new();
    let mut source_vertex_id = String::new();
    let mut target_vertex_id = String::new();
    for node in state_graph {
        if let Some(v) = node.get("vertex_id").and_then(Value::as_str) {
            vertex_ids.insert(v.to_string());
            let kind = node
                .get("artifact_kind")
                .and_then(Value::as_str)
                .unwrap_or("");
            if kind == "post_binding_sites_state_vertex" {
                post_pathb_vertex = v.to_string();
            } else if kind == "pre_md_state_vertex" || kind == "post_md_state_vertex" {
                if md_vertex.is_empty() {
                    md_vertex = v.to_string();
                }
            }
        }
        if node.get("operator_name").and_then(Value::as_str)
            == Some("PATHB.MATERIALIZE_BINDING_SITE")
        {
            if let Some(s) = node.get("source_vertex_id").and_then(Value::as_str) {
                source_vertex_id = s.to_string();
            }
            if let Some(t) = node.get("target_vertex_id").and_then(Value::as_str) {
                target_vertex_id = t.to_string();
            }
        }
    }
    if source_vertex_id.is_empty() {
        source_vertex_id = md_vertex.clone();
    }
    if target_vertex_id.is_empty() {
        target_vertex_id = post_pathb_vertex.clone();
    }
    let evidence_parents: Vec<Value> = [&source_vertex_id, &target_vertex_id]
        .iter()
        .filter(|v| !v.is_empty())
        .map(|v| j_str((*v).clone()))
        .collect();

    // --- one prediction record per PROMOTED materialized site --------------------------------------
    let empty: &[Value] = &[];
    let sites = binding_sites_materialized
        .get("binding_sites")
        .and_then(Value::as_array)
        .unwrap_or(empty);
    let mut records: Vec<Value> = Vec::with_capacity(sites.len());
    for site in sites {
        let new_prism_rank = site.get("new_prism_rank").and_then(Value::as_f64);
        let old_density_rank = site.get("old_density_rank").and_then(Value::as_f64);
        let predicted_delta = match (new_prism_rank, old_density_rank) {
            (Some(n), Some(o)) => Some(n - o),
            _ => None,
        };
        // confidence: REAL manifold_consistency_score (∈[0,1], varies). Honest fallback only if the
        // decoded score is absent — the field-completeness fraction (also REAL, per-site, never a
        // fabricated constant).
        let confidence = site
            .get("manifold_consistency")
            .and_then(|m| m.get("manifold_consistency_score"))
            .and_then(Value::as_f64)
            .or_else(|| {
                site.get("field_completeness").and_then(|fc| match fc {
                    Value::Object(map) => {
                        let total = map.len() as f64;
                        if total == 0.0 {
                            None
                        } else {
                            let present = map
                                .values()
                                .filter(|v| {
                                    matches!(
                                        v.as_str(),
                                        Some("present") | Some("materialized_parsed")
                                    )
                                })
                                .count() as f64;
                            Some(present / total)
                        }
                    }
                    _ => None,
                })
            })
            .map(|c| c.clamp(0.0, 1.0));
        // uncertainty: REAL centroid_spread_a normalized spread/(1+spread) ∈[0,1) (varies; tight
        // centroid spread 0 => 0 = high certainty). Independent of confidence.
        let uncertainty = site
            .get("centroid_spread_a")
            .and_then(Value::as_f64)
            .map(|s| {
                let s = s.max(0.0);
                (s / (1.0 + s)).clamp(0.0, 1.0)
            });
        let epistemic_status = site
            .get("materialization_status")
            .and_then(Value::as_str)
            .unwrap_or("materialized")
            .to_string();
        // predicted_surface: REAL centroid + lining-residue digest (stable per site).
        let mut digest_seed = String::new();
        if let Some(xyz) = site.get("centroid_xyz").and_then(Value::as_array) {
            for c in xyz {
                if let Some(f) = c.as_f64() {
                    let _ = write!(digest_seed, "{:.4},", f);
                }
            }
        }
        digest_seed.push('|');
        if let Some(lining) = site.get("lining_residues").and_then(Value::as_array) {
            for r in lining {
                if let Some(u) = r.as_u64() {
                    let _ = write!(digest_seed, "{},", u);
                }
            }
        }
        let surf_hash = blake3::hash(digest_seed.as_bytes()).to_hex();
        let predicted_surface = format!("surf_{}", &surf_hash.as_str()[..16]);
        let prediction_id = match new_prism_rank {
            Some(n) => format!("{}::pred_r{:03}", target_id, n as i64),
            None => format!(
                "{}::pred_{}",
                target_id,
                site.get("site_id").and_then(Value::as_str).unwrap_or("na")
            ),
        };

        records.push(j_obj(vec![
            ("prediction_id", j_str(prediction_id)),
            ("target_id", j_str(target_id.clone())),
            ("receptor_state", j_str(receptor_state.clone())),
            ("ligand_state", j_str(ligand_state.clone())),
            ("predicted_surface", j_str(predicted_surface)),
            (
                "predicted_delta",
                predicted_delta
                    .map(|d| j_num(d as i64))
                    .unwrap_or(Value::Null),
            ),
            ("confidence", confidence.map(j_num).unwrap_or(Value::Null)),
            ("uncertainty", uncertainty.map(j_num).unwrap_or(Value::Null)),
            ("epistemic_status", j_str(epistemic_status)),
            ("evidence_parent_ids", j_array(evidence_parents.clone())),
            ("source_vertex_id", j_str(source_vertex_id.clone())),
            ("target_vertex_id", j_str(target_vertex_id.clone())),
            (
                "operator_recommendation_id",
                j_str(operator_recommendation_id.clone()),
            ),
            ("validation_status", j_str(validation_status.clone())),
            ("falsification_status", j_str(falsification_status.clone())),
            ("qnanl_receipt_ref", j_str(qnanl_receipt_ref.clone())),
            ("runtime_origin", j_str(runtime_origin.clone())),
            ("tokenizer_family", j_str("PredictionState")),
        ]));
    }

    j_obj(vec![
        ("schema_kind", j_str("prismos_prediction_state")),
        ("schema_version", j_num(1u64)),
        ("target_id", j_str(target_id)),
        ("ligand_state", j_str(ligand_state)),
        ("receptor_state", j_str(receptor_state)),
        ("source_vertex_id", j_str(source_vertex_id)),
        ("target_vertex_id", j_str(target_vertex_id)),
        (
            "n_materialized_sites",
            n_materialized_sites.map(j_num).unwrap_or(Value::Null),
        ),
        ("n_records", j_num(records.len() as u64)),
        ("record_count", j_num(records.len() as u64)),
        ("records", j_array(records)),
    ])
}

fn emit_prismos_dashboard(output: &Path, engine_passed: bool) -> PcResult<PathBuf> {
    let dashboard_path = output.join("dashboard.html");
    let status = if engine_passed { "PASS" } else { "FAIL" };
    let body = format!(
        concat!(
            "<!doctype html>\n",
            "<html lang=\"en\"><head><meta charset=\"utf-8\">",
            "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">",
            "<title>PrismOS MD Run Control Surface</title>",
            "<style>",
            "body{{font-family:system-ui,-apple-system,Segoe UI,sans-serif;margin:0;background:#0b1020;color:#e8edf7;}}",
            "main{{max-width:1100px;margin:0 auto;padding:32px;}}",
            "h1{{font-size:28px;margin:0 0 16px;}}",
            ".grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;}}",
            ".card{{border:1px solid #2b3658;background:#121a31;border-radius:8px;padding:14px;}}",
            "a{{color:#8fd3ff;word-break:break-all;}}",
            ".status{{display:inline-block;padding:4px 8px;border-radius:4px;background:#123b2a;color:#9df2be;font-weight:700;}}",
            "</style></head><body><main>",
            "<h1>PrismOS MD Run Control Surface</h1>",
            "<p><span class=\"status\">{}</span></p>",
            "<section class=\"grid\">",
            "<div class=\"card\"><strong>Run Receipt</strong><br><a href=\"prismos_md_run_receipt.json\">prismos_md_run_receipt.json</a></div>",
            "<div class=\"card\"><strong>QNANL Control</strong><br><a href=\"prismos_qnanl_control_surface.json\">prismos_qnanl_control_surface.json</a></div>",
            "<div class=\"card\"><strong>PrismCode ISA Plan</strong><br><a href=\"prismos_prismcode_isa_execution_plan.json\">prismos_prismcode_isa_execution_plan.json</a></div>",
            "<div class=\"card\"><strong>PrismCode ISA Verification</strong><br><a href=\"prismos_prismcode_isa_execution_verification.json\">prismos_prismcode_isa_execution_verification.json</a></div>",
            "<div class=\"card\"><strong>Run-Level QNANL Summary</strong><br><a href=\"prismos_qnanl_run_level_artifact_summary.json\">prismos_qnanl_run_level_artifact_summary.json</a></div>",
            "<div class=\"card\"><strong>Path A Completion</strong><br><a href=\"4BOE_chain_A_engine_path_a_completion.json\">Path A completion</a></div>",
            "<div class=\"card\"><strong>Evidence Manifest</strong><br><a href=\"md_evidence_manifest.json\">md_evidence_manifest.json</a></div>",
            "<div class=\"card\"><strong>Science Intelligence</strong><br><a href=\"prismos_science_eval.html\">prismos_science_eval.html</a></div>",
            "<div class=\"card\"><strong>ISA Coverage</strong><br><a href=\"prismos_isa_coverage.json\">prismos isa coverage</a></div>",
            "<div class=\"card\"><strong>QNANL Codec Status</strong><br><a href=\"prismos_codec_status.json\">prismos codec status</a></div>",
            "<div class=\"card\"><strong>Downstream Lineage</strong><br><a href=\"prismos_lineage.json\">prismos lineage</a></div>",
            "<div class=\"card\"><strong>Path B / DSTW / Forge</strong><br><a href=\"prismos_view_path_b.html\">Path B</a> &middot; <a href=\"prismos_view_dstw.html\">DSTW</a> &middot; <a href=\"prismos_view_molecules.html\">Molecules</a></div>",
            "<div class=\"card\"><strong>Models / Policy</strong><br><a href=\"prismos_view_teacher.html\">Teacher</a> &middot; <a href=\"prismos_view_student.html\">Student</a> &middot; <a href=\"prismos_view_gflownet.html\">GFlowNet</a></div>",
            "<div class=\"card\"><strong>Engine Logs</strong><br><a href=\"prismos_md_engine.stdout.log\">stdout</a><br><a href=\"prismos_md_engine.stderr.log\">stderr</a></div>",
            "</section></main></body></html>\n"
        ),
        status
    );
    fs::write(&dashboard_path, body)?;
    Ok(dashboard_path)
}

fn emit_prismos_force_kernel_opcode_bundle(
    output: &Path,
    qnanl_force_kernel_receipt: Option<&Path>,
    cuda_opcode_coverage: &Path,
    native_md_receipt_candidates: &[Value],
) -> PcResult<PathBuf> {
    let force_kernel_runtime_receipt = qnanl_force_kernel_receipt
        .map(read_json_optional)
        .unwrap_or_else(j_null);
    let cuda_opcode_coverage_json = read_json_optional(cuda_opcode_coverage);
    let native_streams: Vec<Value> = native_md_receipt_candidates
        .iter()
        .filter_map(|candidate| candidate.get("json"))
        .map(|json| {
            j_obj(vec![
                (
                    "coverage_status",
                    json.get("coverage_status").cloned().unwrap_or_else(j_null),
                ),
                (
                    "execution_mode",
                    json.get("execution_mode").cloned().unwrap_or_else(j_null),
                ),
                (
                    "force_kernel_opcode_coverage",
                    json.get("force_kernel_opcode_coverage")
                        .cloned()
                        .unwrap_or_else(j_null),
                ),
                (
                    "integration_opcode_coverage",
                    json.get("integration_opcode_coverage")
                        .cloned()
                        .unwrap_or_else(j_null),
                ),
                (
                    "observation_opcode_coverage",
                    json.get("observation_opcode_coverage")
                        .cloned()
                        .unwrap_or_else(j_null),
                ),
                (
                    "cuda_graph_capture_dispatch_count",
                    json.get("cuda_graph_capture_dispatch_count")
                        .cloned()
                        .unwrap_or_else(|| j_num(0)),
                ),
                (
                    "cuda_graph_replay_dispatch_count",
                    json.get("cuda_graph_replay_dispatch_count")
                        .cloned()
                        .unwrap_or_else(|| j_num(0)),
                ),
                (
                    "dispatch_trace_hash_blake3",
                    json.get("dispatch_trace_hash_blake3")
                        .cloned()
                        .unwrap_or_else(j_null),
                ),
                (
                    "kernel_counts",
                    json.get("kernel_counts")
                        .cloned()
                        .unwrap_or_else(|| j_obj(Vec::new())),
                ),
                (
                    "opcode_counts",
                    json.get("opcode_counts")
                        .cloned()
                        .unwrap_or_else(|| j_obj(Vec::new())),
                ),
                (
                    "required_core_opcodes",
                    json.get("required_core_opcodes")
                        .cloned()
                        .unwrap_or_else(|| j_array(Vec::new())),
                ),
                (
                    "missing_required_opcodes",
                    json.get("missing_required_opcodes")
                        .cloned()
                        .unwrap_or_else(|| j_array(Vec::new())),
                ),
            ])
        })
        .collect();
    let native_all_pass = !native_streams.is_empty()
        && native_streams.iter().all(|stream| {
            stream
                .get("coverage_status")
                .and_then(Value::as_str)
                .unwrap_or("")
                == "PASS"
        });
    let native_all_bounded_or_passed = !native_streams.is_empty()
        && native_streams.iter().all(|stream| {
            stream
                .get("coverage_status")
                .and_then(Value::as_str)
                .map(md_coverage_bounded_or_passed)
                .unwrap_or(false)
        });
    let native_graph_all_pass = !native_streams.is_empty()
        && native_streams.iter().all(|stream| {
            stream
                .get("cuda_graph_capture_dispatch_count")
                .and_then(Value::as_u64)
                .unwrap_or(0)
                > 0
                && stream
                    .get("cuda_graph_replay_dispatch_count")
                    .and_then(Value::as_u64)
                    .unwrap_or(0)
                    > 0
        });
    let force_kernel_runtime_pass = force_kernel_runtime_receipt
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("")
        == "PASS";
    let cuda_opcode_pass = cuda_opcode_coverage_json
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_else(|| {
            cuda_opcode_coverage_json
                .get("cuda_opcode_coverage")
                .and_then(|coverage| coverage.get("NANL.Q4_VALIDATE"))
                .and_then(Value::as_str)
                .unwrap_or("")
        })
        == "PASS";
    let native_stream_count = native_streams.len();
    let bundle = j_obj(vec![
        ("schema_kind", j_str("prismos_force_kernel_opcode_bundle")),
        ("schema_version", j_num(1)),
        (
            "status",
            j_str(
                if force_kernel_runtime_pass && native_all_pass && native_graph_all_pass {
                    "PASS"
                } else {
                    "PARTIAL"
                },
            ),
        ),
        ("artifact_family", j_str("MD_FORCE_KERNEL_OPCODE_BUNDLE")),
        ("force_kernel_runtime_receipt", force_kernel_runtime_receipt),
        (
            "cuda_opcode_coverage_status",
            j_str(if cuda_opcode_pass { "PASS" } else { "PARTIAL" }),
        ),
        ("cuda_opcode_coverage", cuda_opcode_coverage_json),
        ("native_stream_count", j_num(native_stream_count)),
        ("native_streams_all_pass", j_bool(native_all_pass)),
        (
            "native_streams_all_bounded_or_passed",
            j_bool(native_all_bounded_or_passed),
        ),
        (
            "native_streams_cuda_graph_all_pass",
            j_bool(native_graph_all_pass),
        ),
        ("native_streams", j_array(native_streams)),
        (
            "lowering_contract",
            j_obj(vec![
                ("packet_family", j_str("MD_FORCE_KERNEL_PTX")),
                (
                    "opcode_bundle_family",
                    j_str("MD_FORCE_KERNEL_OPCODE_BUNDLE"),
                ),
                ("runtime", j_str("nhs_rt_full")),
                (
                    "dispatch_substrate",
                    j_str("native_prismcode_md_opcode_dispatch_cuda_macro_fused"),
                ),
                (
                    "required_surfaces",
                    j_string_array(&[
                        "force_kernel_runtime_receipt",
                        "cuda_opcode_coverage",
                        "native_md_receipts",
                        "cuda_graph_capture_dispatch_count",
                        "cuda_graph_replay_dispatch_count",
                        "dispatch_trace_hash_blake3",
                        "kernel_counts",
                        "opcode_counts",
                    ]),
                ),
            ]),
        ),
    ]);
    let bundle_path = output.join("prismcode_force_kernel_opcode_bundle.json");
    fs::write(&bundle_path, bundle.to_pretty_json())?;
    Ok(bundle_path)
}

fn scientific_surface_qnanl_family_for_label(label: &str) -> Option<QnanlArtifactFamily> {
    match label {
        "ScientificPocketOpeningEvent"
        | "ScientificPocketOpeningEvents"
        | "scientific_pocket_opening_event"
        | "scientific_pocket_opening_events"
        | "prismos_scientific_pocket_opening_event"
        | "prismos_scientific_pocket_opening_events"
        | "FRAME_CAPTURE"
        | "POCKET_GEOMETRY_EVAL"
        | "SCIENTIFIC_POCKET_OPENING_EVENT"
        | "T4_EPOCH_OVERLAY"
        | "SITE_RANKING" => Some(QnanlArtifactFamily::ScientificPocketOpeningEvent),
        "LigandCausalActivityEvent"
        | "LigandCausalActivityEvents"
        | "ligand_causal_activity_event"
        | "ligand_causal_activity_events"
        | "prismos_ligand_causal_activity_event"
        | "prismos_ligand_causal_activity_events"
        | "LIGAND_CAUSAL_ACTIVITY_EVENT" => Some(QnanlArtifactFamily::LigandCausalActivityEvent),
        "ResidueActivityEvent"
        | "ResidueActivityEvents"
        | "residue_activity_event"
        | "residue_activity_events"
        | "prismos_residue_activity_event"
        | "prismos_residue_activity_events"
        | "RESIDUE_ACTIVITY_EVENT" => Some(QnanlArtifactFamily::ResidueActivityEvent),
        _ => None,
    }
}

fn scientific_surface_qnanl_family_for_value(value: &Value) -> Option<QnanlArtifactFamily> {
    value
        .get("schema_kind")
        .and_then(Value::as_str)
        .and_then(scientific_surface_qnanl_family_for_label)
        .or_else(|| {
            value
                .get("event_type")
                .and_then(Value::as_str)
                .and_then(scientific_surface_qnanl_family_for_label)
        })
}

fn scientific_surface_qnanl_family_for_file(path: &Path) -> Option<QnanlArtifactFamily> {
    let lower = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let by_name = match lower.as_str() {
        "scientific_pocket_opening_event.json"
        | "scientific_pocket_opening_event.jsonl"
        | "scientific_pocket_opening_events.json"
        | "scientific_pocket_opening_events.jsonl" => {
            Some(QnanlArtifactFamily::ScientificPocketOpeningEvent)
        }
        "ligand_causal_activity_event.json"
        | "ligand_causal_activity_event.jsonl"
        | "ligand_causal_activity_events.json"
        | "ligand_causal_activity_events.jsonl" => {
            Some(QnanlArtifactFamily::LigandCausalActivityEvent)
        }
        "residue_activity_event.json"
        | "residue_activity_event.jsonl"
        | "residue_activity_events.json"
        | "residue_activity_events.jsonl" => Some(QnanlArtifactFamily::ResidueActivityEvent),
        _ => None,
    };
    if by_name.is_some() {
        return by_name;
    }

    if lower.ends_with(".json") {
        return scientific_surface_qnanl_family_for_value(&read_json_optional(path));
    }
    if lower.ends_with(".jsonl") {
        if let Ok(text) = fs::read_to_string(path) {
            for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
                if let Ok(value) = JsonParser::new(line).parse() {
                    if let Some(family) = scientific_surface_qnanl_family_for_value(&value) {
                        return Some(family);
                    }
                }
            }
        }
    }
    None
}

fn qnanl_family_for_prismos_output(path: &Path) -> Option<QnanlArtifactFamily> {
    let filename = path.file_name().and_then(|v| v.to_str()).unwrap_or("");
    let filename_lower = filename.to_ascii_lowercase();
    if qnanl_artifact::is_qnanl_auxiliary_path(path)
        || filename.is_empty()
        || filename.ends_with(".prismqnanl")
        || filename.ends_with(".prismnanl")
        || filename.ends_with(".prismnanl.q4")
        || filename.ends_with(".prismqnanl.receipt.json")
        || filename.ends_with(".decoded")
    {
        return None;
    }
    if filename.ends_with("_spikes.bin")
        || filename.starts_with("prism_zstr_") && filename.ends_with(".bin")
    {
        return Some(QnanlArtifactFamily::EventStream);
    }
    if filename == "dashboard.html"
        || filename.ends_with(".css")
        || filename.ends_with(".js")
        || filename.ends_with(".html")
    {
        return Some(QnanlArtifactFamily::DashboardPackage);
    }
    if filename == "prismcode_force_kernel_opcode_bundle.json" {
        return Some(QnanlArtifactFamily::MdForceKernelOpcodeBundle);
    }
    if let Some(family) = scientific_surface_qnanl_family_for_file(path) {
        return Some(family);
    }
    if matches!(
        filename_lower.as_str(),
        "scientific_chronology_events.json"
            | "scientific_chronology_events.jsonl"
            | "scientific_chronology_event.json"
            | "scientific_chronology_event.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ScientificChronologyEvent);
    }
    if matches!(
        filename_lower.as_str(),
        "scientific_state_epochs.json"
            | "scientific_state_epochs.jsonl"
            | "scientific_state_epoch.json"
            | "scientific_state_epoch.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ScientificStateEpoch);
    }
    if matches!(
        filename_lower.as_str(),
        "dstw_t4_epoch_overlay.json" | "dstw_t4_epoch_overlay.jsonl"
    ) {
        return Some(QnanlArtifactFamily::T4EpochOverlay);
    }
    if matches!(
        filename_lower.as_str(),
        "chronology_acceptance_decision.json"
            | "chronology_acceptance_decision.jsonl"
            | "scientific_chronology_acceptance_decision.json"
            | "scientific_chronology_acceptance_decision.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ChronologyAcceptanceDecision);
    }
    if matches!(
        filename_lower.as_str(),
        "scientific_chronology_manifest.json" | "scientific_chronology_manifest.jsonl"
    ) {
        return Some(QnanlArtifactFamily::JsonTelemetry);
    }
    if filename_lower.contains("residue_map")
        || filename_lower.contains("atom_to_residue")
        || filename_lower.contains("chain_numbering")
        || filename_lower.contains("residue_alignment")
        || filename_lower.contains("numbering_ledger")
    {
        return Some(QnanlArtifactFamily::ResidueAlignmentMap);
    }
    if filename_lower.contains("binding_site_physiology")
        || filename_lower.contains("site_physiology")
    {
        return Some(QnanlArtifactFamily::BindingSitePhysiology);
    }
    if filename_lower.contains("pocket_morphology")
        || filename_lower.contains("geometric_pocket")
        || filename_lower.contains("binding_site_morphology")
    {
        return Some(QnanlArtifactFamily::GeometricPocketMorphology);
    }
    if filename_lower.contains("binding_sites")
        || filename_lower.contains("site_candidates")
        || filename_lower.contains("materialized_site")
        || filename_lower.contains("site_materialization")
        || filename_lower == "materialization_report.json"
        || filename_lower == "validation_inputs.json"
        || filename_lower == "site_accuracy_report.json"
        || filename_lower == "materialization_field_completeness.json"
        || filename_lower == "duplicate_cluster_report.json"
        || filename_lower == "ranking_ablation_report.json"
    {
        return Some(QnanlArtifactFamily::BindingSiteMaterialization);
    }
    if filename_lower.contains("kcc_visualization")
        || filename_lower.contains("merged_kcc")
        || filename_lower.contains("kcc_materialization")
    {
        return Some(QnanlArtifactFamily::KccMaterialization);
    }
    if filename_lower.contains("spectral")
        || filename_lower.contains("fiber_bundle")
        || filename_lower.contains("phase_fiber")
        || filename_lower.contains("manifold_tensor")
    {
        return Some(QnanlArtifactFamily::SpectralFiberBundle);
    }
    if filename_lower.contains("movie_window")
        || filename_lower.contains("movie_callable")
        || filename_lower.contains("focus_plan")
        || filename_lower.contains("site_window_index")
    {
        return Some(QnanlArtifactFamily::MovieCallableFocus);
    }
    if filename_lower.contains("ccns") || filename_lower.contains("sdst") {
        return Some(QnanlArtifactFamily::CcnsSdstSurface);
    }
    if filename_lower.contains("prism_therm")
        || filename_lower.contains("thermo_temporal")
        || filename_lower.contains("thermodynamic_phase")
        || filename_lower.contains("phase_state")
        || filename_lower.contains("twin16")
    {
        return Some(QnanlArtifactFamily::ThermodynamicPhaseManifold);
    }
    if (filename.starts_with("prism_v2_")
        && (filename.ends_with(".bin") || filename.ends_with(".bin.audit.json")))
        || (filename.contains("_v2_frames.")
            && (filename.ends_with(".bin") || filename.ends_with(".audit.json")))
        || filename.ends_with("_asc_trajectory.bin")
    {
        return Some(QnanlArtifactFamily::TrajectoryCheckpoint);
    }
    if filename.ends_with("_warp_matrix.bin") {
        return Some(QnanlArtifactFamily::DenseGpuField);
    }
    if filename.ends_with("_signal_grid.bin") || filename.ends_with(".spatial_grid_state.json") {
        return Some(QnanlArtifactFamily::SignalGrid);
    }
    if filename.ends_with("_forces_final.bin")
        || filename.ends_with("_asc_vectors.bin")
        || filename.ends_with("_aromatic_centroids_final.bin")
        || filename.ends_with("_kcc_v2full.bin")
        || filename.ends_with("_adaptive_dt.bin")
        || filename.ends_with("_adj_flags.bin")
        || filename.ends_with("_ghost_tiles.bin")
    {
        return Some(QnanlArtifactFamily::NumericArray);
    }
    if filename.ends_with(".pcout") || filename.ends_with(".pcode") {
        return Some(QnanlArtifactFamily::PrismcodeExecutionArtifact);
    }
    if filename.ends_with(".log") {
        return Some(QnanlArtifactFamily::LogStream);
    }
    if filename.ends_with(".json") || filename.ends_with(".jsonl") {
        return Some(QnanlArtifactFamily::JsonTelemetry);
    }
    if filename.ends_with(".bin") {
        return Some(QnanlArtifactFamily::Unknown);
    }
    None
}

fn qnanl_prismos_raw_bulk_family(family: QnanlArtifactFamily) -> bool {
    matches!(
        family,
        QnanlArtifactFamily::EventStream
            | QnanlArtifactFamily::DenseGpuField
            | QnanlArtifactFamily::SignalGrid
            | QnanlArtifactFamily::NumericArray
            | QnanlArtifactFamily::TrajectoryCheckpoint
    )
}

fn append_prismqnanl_suffix(path: &Path, suffix: &str) -> PathBuf {
    PathBuf::from(format!("{}{}", path.display(), suffix))
}

fn qnanl_receipt_value(receipt: &qnanl_artifact::QnanlArtifactReceipt) -> Value {
    j_obj(vec![
        ("schema_kind", j_str(receipt.schema_kind.clone())),
        ("schema_version", j_num(receipt.schema_version)),
        ("status", j_str(receipt.status.clone())),
        ("artifact_id", j_str(receipt.artifact_id.clone())),
        (
            "artifact_family",
            j_str(receipt.artifact_family.to_string()),
        ),
        (
            "artifact_transform",
            j_str(receipt.artifact_transform.clone()),
        ),
        ("source_path", j_str(receipt.source_path.clone())),
        ("packet_path", j_str(receipt.packet_path.clone())),
        ("receipt_path", j_str(receipt.receipt_path.clone())),
        ("raw_bytes", j_num(receipt.raw_bytes)),
        ("packet_bytes", j_num(receipt.packet_bytes)),
        (
            "compressed_body_bytes",
            j_num(receipt.compressed_body_bytes),
        ),
        ("qnanl_seal_bytes", j_num(receipt.qnanl_seal_bytes)),
        (
            "compression_ratio_vs_raw",
            j_num(format!("{:.9}", receipt.compression_ratio_vs_raw)),
        ),
        (
            "size_reduction_percent",
            j_num(format!("{:.9}", receipt.size_reduction_percent)),
        ),
        ("encode_ns", j_num(receipt.encode_ns)),
        ("decode_verify_ns", j_num(receipt.decode_verify_ns)),
        ("qnanl_seal_ns", j_num(receipt.qnanl_seal_ns)),
        (
            "encode_mib_s",
            j_num(format!("{:.9}", receipt.encode_mib_s)),
        ),
        (
            "decode_verify_mib_s",
            j_num(format!("{:.9}", receipt.decode_verify_mib_s)),
        ),
        ("raw_hash_blake3", j_str(receipt.raw_hash_blake3.clone())),
        (
            "packet_hash_blake3",
            j_str(receipt.packet_hash_blake3.clone()),
        ),
        (
            "compressed_body_hash_blake3",
            j_str(receipt.compressed_body_hash_blake3.clone()),
        ),
        (
            "qnanl_seal_hash_blake3",
            j_str(receipt.qnanl_seal_hash_blake3.clone()),
        ),
        ("roundtrip_verified", j_bool(receipt.roundtrip_verified)),
        (
            "codec_roundtrip_verified",
            j_bool(receipt.codec_roundtrip_verified),
        ),
        (
            "qnanl_seal_status",
            j_str(receipt.qnanl_seal_status.clone()),
        ),
        (
            "qnanl_seal_constraints_pass",
            j_bool(receipt.qnanl_seal_constraints_pass),
        ),
        (
            "qnanl_seal_merkle_verified",
            j_bool(receipt.qnanl_seal_merkle_verified),
        ),
        (
            "qnanl_seal_ecc_verified",
            j_bool(receipt.qnanl_seal_ecc_verified),
        ),
        // DSTW-T4 Step 3 honest provenance surface.
        ("runtime_origin", j_str(receipt.runtime_origin.as_str())),
        (
            "runtime_native",
            j_bool(receipt.runtime_origin.is_prismos_native()),
        ),
        (
            "chunk_hashes",
            Value::Array(
                receipt
                    .chunk_hashes
                    .iter()
                    .map(|h| j_str(h.clone()))
                    .collect(),
            ),
        ),
        // DSTW-T4 Step h1: PROCESS-PROVEN per-artifact provenance, or explicit
        // null when this receipt came from the pure-sealer path (no run context).
        (
            "runtime_provenance",
            receipt
                .runtime_provenance
                .as_ref()
                .map(|p| serde_to_value(&p.to_json()))
                .unwrap_or(Value::Null),
        ),
    ])
}

// DSTW-T4 Step 3 / plan Guardrail 4 + gate 11: this sweep runs ONLY after the
// engine subprocess exits (called from run_md after `command.status()` returns,
// prismos.rs ~:7018). It is structurally POST-RUN, so every packet it seals is
// honestly `runtime_origin = POST_RUN_SEAL_ONLY` (the conservative default
// stamped by `encode_file`/`encode_bytes`). This is the QNANL Primary Artifact
// Compression path (metadata + SECTION_ZSTD body + NANL-Q4 seal) applied
// post-loop; it is NOT runtime-primary in-loop emission. Native in-loop
// streaming is the RuntimeQnanlStreamWriter v1 / engine-owner gate
// (nhs_rt_full.rs:18358).
fn encode_prismos_run_level_qnanl_artifacts(
    output: &Path,
    remove_verified_raw_bulk: bool,
    provenance: &prismcode::runtime_provenance::RuntimeProvenance,
) -> PcResult<Value> {
    let mut paths = Vec::new();
    for entry in fs::read_dir(output)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            paths.push(path);
        }
    }
    paths.sort();

    let mut receipts = Vec::new();
    let mut failures = Vec::new();
    let mut encoded_count_by_family = std::collections::BTreeMap::<String, u64>::new();
    let mut raw_retention_records = Vec::new();
    let mut raw_retention_removed_bytes = 0u64;
    let mut raw_retention_failed_removals = Vec::new();
    for path in paths {
        let Some(family) = qnanl_family_for_prismos_output(&path) else {
            continue;
        };
        let packet_path = append_prismqnanl_suffix(&path, ".prismqnanl");
        let receipt_path = append_prismqnanl_suffix(&path, ".prismqnanl.receipt.json");
        let artifact_id = path
            .file_name()
            .and_then(|value| value.to_str())
            .map(ToOwned::to_owned)
            .unwrap_or_else(|| path.display().to_string());
        let publication =
            (|| -> qnanl_artifact::QnanlArtifactResult<qnanl_artifact::QnanlArtifactReceipt> {
                let raw_hash = file_hash_hex(&path)
                    .map_err(|e| qnanl_artifact::QnanlArtifactError::Io(e.to_string()))?;
                let receipt = match qnanl_artifact::recover_published_artifact(
                    &packet_path,
                    &receipt_path,
                )? {
                    Some(receipt) => receipt,
                    None => {
                        // Bind the RAW source record before publication. The packet
                        // does not yet exist; provenance must not be added by
                        // rewriting an already committed canonical receipt.
                        let record = provenance.artifact_record(
                            &path,
                            "qnanl_run_level_seal",
                            vec![raw_hash.clone()],
                        );
                        qnanl_artifact::encode_file(
                            &path,
                            &packet_path,
                            &receipt_path,
                            QnanlEncodeOptions::runtime_inline(
                                artifact_id.clone(),
                                family,
                                Some(path.clone()),
                                "prismos::seal_runtime_artifacts",
                            )
                            .with_runtime_provenance(record),
                        )?
                    }
                };
                let raw_sha256 = prismcode::operand_ledger::sha256_file_hex(&path)
                    .map_err(|e| qnanl_artifact::QnanlArtifactError::Io(e.to_string()))?;
                if receipt.runtime_origin != prismcode::operand_ledger::RuntimeOrigin::RuntimeInline
                    || receipt.runtime_origin_assignment_stage != "prismos::seal_runtime_artifacts"
                    || receipt
                        .runtime_provenance
                        .as_ref()
                        .and_then(|p| p.emitted_artifact_sha256.as_deref())
                        != Some(raw_sha256.as_str())
                    || receipt.artifact_id != artifact_id
                    || receipt.artifact_family != family
                    || receipt.source_path != path.display().to_string()
                    || receipt.raw_hash_blake3 != raw_hash
                    || file_hash_hex(&path)
                        .map_err(|e| qnanl_artifact::QnanlArtifactError::Io(e.to_string()))?
                        != raw_hash
                {
                    return Err(qnanl_artifact::QnanlArtifactError::Hash(
                        "retained QNANL packet differs from current raw source; retain raw".into(),
                    ));
                }
                Ok(receipt)
            })();
        match publication {
            Ok(receipt) => {
                *encoded_count_by_family
                    .entry(receipt.artifact_family.as_str().to_string())
                    .or_insert(0) += 1;
                if remove_verified_raw_bulk
                    && qnanl_prismos_raw_bulk_family(receipt.artifact_family)
                {
                    let source_path = PathBuf::from(&receipt.source_path);
                    if receipt.status == "PASS" && receipt.roundtrip_verified {
                        let raw_bytes = source_path.metadata().map(|m| m.len()).unwrap_or(0);
                        match fs::remove_file(&source_path) {
                            Ok(()) => {
                                if let Some(parent) = source_path.parent() {
                                    File::open(parent)?.sync_all()?;
                                }
                                raw_retention_removed_bytes =
                                    raw_retention_removed_bytes.saturating_add(raw_bytes);
                                raw_retention_records.push(j_obj(vec![
                                    ("raw_path", j_str(source_path.display().to_string())),
                                    ("packet_path", j_str(receipt.packet_path.clone())),
                                    ("receipt_path", j_str(receipt.receipt_path.clone())),
                                    (
                                        "artifact_family",
                                        j_str(receipt.artifact_family.to_string()),
                                    ),
                                    ("raw_bytes_removed", j_num(raw_bytes)),
                                    ("action", j_str("removed_raw_after_verified_packet")),
                                    ("status", j_str("PASS")),
                                    ("reason", j_str("prismos_qnanl_primary_artifacts")),
                                ]));
                            }
                            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                                raw_retention_records.push(j_obj(vec![
                                    ("raw_path", j_str(source_path.display().to_string())),
                                    ("packet_path", j_str(receipt.packet_path.clone())),
                                    ("receipt_path", j_str(receipt.receipt_path.clone())),
                                    (
                                        "artifact_family",
                                        j_str(receipt.artifact_family.to_string()),
                                    ),
                                    ("raw_bytes_removed", j_num(0)),
                                    ("action", j_str("raw_absent_after_verified_packet")),
                                    ("status", j_str("PASS")),
                                    ("reason", j_str("already_absent")),
                                ]));
                            }
                            Err(e) => {
                                let msg =
                                    format!("remove raw {} failed: {}", source_path.display(), e);
                                raw_retention_failed_removals.push(msg.clone());
                                raw_retention_records.push(j_obj(vec![
                                    ("raw_path", j_str(source_path.display().to_string())),
                                    ("packet_path", j_str(receipt.packet_path.clone())),
                                    ("receipt_path", j_str(receipt.receipt_path.clone())),
                                    (
                                        "artifact_family",
                                        j_str(receipt.artifact_family.to_string()),
                                    ),
                                    ("raw_bytes_removed", j_num(0)),
                                    ("action", j_str("remove_raw_after_verified_packet")),
                                    ("status", j_str("FAIL")),
                                    ("reason", j_str(msg)),
                                ]));
                            }
                        }
                    } else {
                        raw_retention_records.push(j_obj(vec![
                            ("raw_path", j_str(source_path.display().to_string())),
                            ("packet_path", j_str(receipt.packet_path.clone())),
                            ("receipt_path", j_str(receipt.receipt_path.clone())),
                            (
                                "artifact_family",
                                j_str(receipt.artifact_family.to_string()),
                            ),
                            ("raw_bytes_removed", j_num(0)),
                            ("action", j_str("retain_raw")),
                            ("status", j_str("SKIPPED")),
                            ("reason", j_str("roundtrip_not_verified")),
                        ]));
                    }
                }
                receipts.push(qnanl_receipt_value(&receipt));
            }
            Err(e) => {
                failures.push(j_obj(vec![
                    ("path", j_str(path.display().to_string())),
                    ("family", j_str(family.to_string())),
                    ("error", j_str(e.to_string())),
                ]));
            }
        }
    }

    let total_raw_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("raw_bytes").and_then(Value::as_u64))
        .sum();
    let total_packet_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("packet_bytes").and_then(Value::as_u64))
        .sum();
    let total_compressed_body_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("compressed_body_bytes").and_then(Value::as_u64))
        .sum();
    let compression_ratio_vs_raw = if total_packet_bytes > 0 {
        total_raw_bytes as f64 / total_packet_bytes as f64
    } else {
        0.0
    };
    let size_reduction_percent = if total_raw_bytes > 0 {
        100.0 * (1.0 - total_packet_bytes as f64 / total_raw_bytes as f64)
    } else {
        0.0
    };
    let all_roundtrips_verified = receipts.iter().all(|r| {
        r.get("roundtrip_verified")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    });
    let status = if failures.is_empty() && !receipts.is_empty() && all_roundtrips_verified {
        "PASS"
    } else if failures.is_empty() {
        "NO_ELIGIBLE_ARTIFACTS"
    } else {
        "FAIL"
    };
    let raw_retention_status = if !remove_verified_raw_bulk {
        "RAW_RETAINED"
    } else if raw_retention_failed_removals.is_empty() {
        "PASS"
    } else {
        "FAIL"
    };
    let raw_retention_summary = j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_qnanl_primary_raw_retention_summary"),
        ),
        ("schema_version", j_num(1)),
        ("status", j_str(raw_retention_status)),
        (
            "raw_retention_policy",
            j_str(if remove_verified_raw_bulk {
                "remove_raw_bulk_artifacts_after_verified_packet"
            } else {
                "retain_raw_artifacts"
            }),
        ),
        ("removed_raw_bytes", j_num(raw_retention_removed_bytes)),
        (
            "removed_raw_gib",
            j_num(format!(
                "{:.9}",
                raw_retention_removed_bytes as f64 / 1024.0 / 1024.0 / 1024.0
            )),
        ),
        ("record_count", j_num(raw_retention_records.len())),
        ("failure_count", j_num(raw_retention_failed_removals.len())),
        (
            "failures",
            j_array(
                raw_retention_failed_removals
                    .iter()
                    .map(|failure| j_str(failure.clone()))
                    .collect(),
            ),
        ),
        ("records", j_array(raw_retention_records)),
    ]);
    let summary = j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_qnanl_run_level_artifact_summary"),
        ),
        ("schema_version", j_num(1)),
        ("status", j_str(status)),
        // DSTW-T4 Step h2: this sweep is structurally POST-RUN (it scans the output
        // directory after the engine subprocess has exited), so it is explicitly
        // classified POST_RUN_SEAL_ONLY and is NOT counted as native runtime
        // emission. The native lifecycle emission path is
        // `prismos_qnanl_runtime_lifecycle_stream_summary.json`
        // (RUNTIME_SUBPROCESS_ORCHESTRATED_BY_PRISMOS). True in-MD-loop
        // RUNTIME_INLINE is the engine-owner v1 gate (nhs_rt_full.rs ~:18358).
        ("runtime_origin_classification", j_str("POST_RUN_SEAL_ONLY")),
        ("native_runtime_emission", j_bool(false)),
        (
            "classification_note",
            j_str(
                "post-subprocess directory sweep; not native. Native lifecycle \
                 emission = qnanl_runtime_lifecycle_stream \
                 (RUNTIME_SUBPROCESS_ORCHESTRATED_BY_PRISMOS). RUNTIME_INLINE \
                 (engine writes chunks inside the MD closure) is the engine-owner v1 gate.",
            ),
        ),
        (
            "eligible_artifact_count",
            j_num(receipts.len() + failures.len()),
        ),
        ("receipt_count", j_num(receipts.len())),
        ("failure_count", j_num(failures.len())),
        ("failures", j_array(failures)),
        (
            "encoded_count_by_family",
            j_u64_map(&encoded_count_by_family),
        ),
        ("total_raw_bytes", j_num(total_raw_bytes)),
        ("total_packet_bytes", j_num(total_packet_bytes)),
        (
            "total_compressed_body_bytes",
            j_num(total_compressed_body_bytes),
        ),
        (
            "compression_ratio_vs_raw",
            j_num(format!("{compression_ratio_vs_raw:.9}")),
        ),
        (
            "size_reduction_percent",
            j_num(format!("{size_reduction_percent:.9}")),
        ),
        ("all_roundtrips_verified", j_bool(all_roundtrips_verified)),
        ("raw_retention_summary", raw_retention_summary),
        ("receipts", j_array(receipts)),
    ]);
    fs::write(
        output.join("prismos_qnanl_run_level_artifact_summary.json"),
        summary.to_pretty_json(),
    )?;
    Ok(summary)
}

#[derive(Clone, Debug)]
struct QnanlSourceArtifact {
    path: PathBuf,
    family: QnanlArtifactFamily,
    source_kind: String,
}

fn collect_prismos_qnanl_source_artifacts(
    root: &Path,
    output: &Path,
    args: &RunMdArgs,
) -> PcResult<Vec<QnanlSourceArtifact>> {
    let mut artifacts = BTreeMap::<PathBuf, QnanlSourceArtifact>::new();
    if args.registry_artifact_discovery {
        for registry in [
            root.join("prism_postmd_superresolution/PRISM_OS_ACTIVE_LAYER_REGISTRY.json"),
            root.join("prism_postmd_superresolution/PRISM_OS_ACTIVE_LAYER_REGISTRY_R2_MIRROR.json"),
            root.join("prism_postmd_superresolution/PRISM_OS_E2E_CONVERSION_MASTER_LEDGER.json"),
        ] {
            collect_source_artifacts_from_registry_file(root, output, &registry, &mut artifacts)?;
        }
        let postmd_root = root.join("prism_postmd_superresolution");
        collect_source_artifacts_from_root(
            root,
            output,
            &postmd_root,
            "registry_default_postmd_root",
            None,
            3,
            &mut artifacts,
        )?;
    }
    for path in &args.artifact_roots {
        collect_source_artifacts_from_root(
            root,
            output,
            &resolve_under(root, path),
            "explicit_artifact_root",
            None,
            8,
            &mut artifacts,
        )?;
    }
    for path in &args.path_b_roots {
        collect_source_artifacts_from_root(
            root,
            output,
            &resolve_under(root, path),
            "explicit_path_b_root",
            Some(QnanlArtifactFamily::PathBPostMdTensor),
            8,
            &mut artifacts,
        )?;
    }
    for path in &args.dstw_roots {
        collect_source_artifacts_from_root(
            root,
            output,
            &resolve_under(root, path),
            "explicit_dstw_root",
            Some(QnanlArtifactFamily::DrfDstwForgeTensor),
            8,
            &mut artifacts,
        )?;
    }
    for path in &args.forge_roots {
        collect_source_artifacts_from_root(
            root,
            output,
            &resolve_under(root, path),
            "explicit_forge_root",
            Some(QnanlArtifactFamily::MoleculeDesignArtifact),
            8,
            &mut artifacts,
        )?;
    }
    for path in &args.model_export_roots {
        collect_source_artifacts_from_root(
            root,
            output,
            &resolve_under(root, path),
            "explicit_model_export_root",
            Some(QnanlArtifactFamily::DrfDstwForgeTensor),
            8,
            &mut artifacts,
        )?;
    }
    Ok(artifacts.into_values().collect())
}

fn collect_source_artifacts_from_registry_file(
    root: &Path,
    output: &Path,
    registry: &Path,
    artifacts: &mut BTreeMap<PathBuf, QnanlSourceArtifact>,
) -> PcResult<()> {
    if !registry.is_file() {
        return Ok(());
    }
    let registry_json = read_json_optional(registry);
    let mut strings = Vec::new();
    collect_json_strings(&registry_json, &mut strings);
    insert_source_artifact(
        root,
        output,
        registry,
        "active_layer_registry",
        Some(QnanlArtifactFamily::RunInputReference),
        artifacts,
    )?;
    for value in strings {
        let Some(candidate) = resolve_existing_source_path(root, &value) else {
            continue;
        };
        insert_source_artifact(
            root,
            output,
            &candidate,
            "active_layer_registry_reference",
            None,
            artifacts,
        )?;
    }
    Ok(())
}

fn collect_source_artifacts_from_root(
    root: &Path,
    output: &Path,
    artifact_root: &Path,
    source_kind: &str,
    default_family: Option<QnanlArtifactFamily>,
    max_depth: usize,
    artifacts: &mut BTreeMap<PathBuf, QnanlSourceArtifact>,
) -> PcResult<()> {
    if !artifact_root.exists() {
        return Ok(());
    }
    let mut files = Vec::new();
    collect_artifact_files_recursive(artifact_root, 0, max_depth, &mut files)?;
    for path in files {
        insert_source_artifact(root, output, &path, source_kind, default_family, artifacts)?;
    }
    Ok(())
}

fn collect_artifact_files_recursive(
    path: &Path,
    depth: usize,
    max_depth: usize,
    files: &mut Vec<PathBuf>,
) -> PcResult<()> {
    if path.is_file() {
        files.push(path.to_path_buf());
        return Ok(());
    }
    if !path.is_dir() || depth > max_depth || skip_artifact_dir(path) {
        return Ok(());
    }
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let child = entry.path();
        if child.is_dir() {
            collect_artifact_files_recursive(&child, depth + 1, max_depth, files)?;
        } else if child.is_file() {
            files.push(child);
        }
    }
    Ok(())
}

fn insert_source_artifact(
    root: &Path,
    output: &Path,
    path: &Path,
    source_kind: &str,
    default_family: Option<QnanlArtifactFamily>,
    artifacts: &mut BTreeMap<PathBuf, QnanlSourceArtifact>,
) -> PcResult<()> {
    if skip_source_artifact_file(path) || path.starts_with(output) {
        return Ok(());
    }
    let canonical = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    if canonical.starts_with(output) || !canonical.is_file() || skip_source_artifact_file(&canonical) {
        return Ok(());
    }
    let family = qnanl_family_for_source_artifact(root, &canonical).or(default_family);
    let Some(family) = family else {
        return Ok(());
    };
    artifacts
        .entry(canonical.clone())
        .or_insert(QnanlSourceArtifact {
            path: canonical,
            family,
            source_kind: source_kind.to_string(),
        });
    Ok(())
}

fn resolve_existing_source_path(root: &Path, value: &str) -> Option<PathBuf> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.contains('\n')
        || trimmed.contains('\r')
        || trimmed.starts_with("http://")
        || trimmed.starts_with("https://")
        || trimmed.starts_with("s3://")
        || trimmed.starts_with("r2://")
    {
        return None;
    }
    let normalized = trimmed.strip_prefix("file://").unwrap_or(trimmed);
    let candidate = if normalized.starts_with('/') {
        PathBuf::from(normalized)
    } else {
        root.join(normalized)
    };
    candidate.is_file().then_some(candidate)
}

fn collect_json_strings(value: &Value, strings: &mut Vec<String>) {
    match value {
        Value::String(value) => strings.push(value.clone()),
        Value::Array(values) => {
            for value in values {
                collect_json_strings(value, strings);
            }
        }
        Value::Object(map) => {
            for value in map.values() {
                collect_json_strings(value, strings);
            }
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => {}
    }
}

fn skip_artifact_dir(path: &Path) -> bool {
    if qnanl_artifact::is_native_continuation_recovery_path(path) { return true; }
    let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
        return false;
    };
    matches!(
        name,
        ".git"
            | ".cargo"
            | ".codex"
            | ".wrangler"
            | "node_modules"
            | "target"
            | "target_codex_check"
            | "dist"
            | "build"
    ) || name.starts_with("backup")
        || name.starts_with("BACKUP")
        || name.starts_with("DELETED")
        || name.starts_with("quarantine")
}

fn skip_source_artifact_file(path: &Path) -> bool {
    let filename = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("");
    if qnanl_artifact::is_qnanl_auxiliary_path(path)
        || filename.is_empty()
        || filename.ends_with(".prismqnanl")
        || filename.ends_with(".prismnanl")
        || filename.ends_with(".prismnanl.q4")
        || filename.ends_with(".prismqnanl.receipt.json")
        || filename.ends_with(".decoded")
        || filename.ends_with(".tmp")
        || filename.ends_with(".body.zst.tmp")
    {
        return true;
    }
    let lower = filename.to_ascii_lowercase();
    let allowed = [
        ".bin",
        ".json",
        ".jsonl",
        ".csv",
        ".tsv",
        ".parquet",
        ".arrow",
        ".npy",
        ".npz",
        ".pt",
        ".pth",
        ".safetensors",
        ".pkl",
        ".sdf",
        ".mol",
        ".mol2",
        ".smi",
        ".smiles",
        ".yaml",
        ".yml",
        ".md",
        ".pcode",
        ".pcout",
    ];
    !allowed.iter().any(|suffix| lower.ends_with(suffix))
}

fn qnanl_family_for_source_artifact(root: &Path, path: &Path) -> Option<QnanlArtifactFamily> {
    let rel = path.strip_prefix(root).unwrap_or(path);
    let text = rel.display().to_string().to_ascii_lowercase();
    let filename = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let ext = path
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();

    if filename.ends_with(".pcode") || filename.ends_with(".pcout") {
        return Some(QnanlArtifactFamily::PrismcodeExecutionArtifact);
    }
    if let Some(family) = scientific_surface_qnanl_family_for_file(path) {
        return Some(family);
    }
    if matches!(
        filename.as_str(),
        "scientific_chronology_events.json"
            | "scientific_chronology_events.jsonl"
            | "scientific_chronology_event.json"
            | "scientific_chronology_event.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ScientificChronologyEvent);
    }
    if matches!(
        filename.as_str(),
        "scientific_state_epochs.json"
            | "scientific_state_epochs.jsonl"
            | "scientific_state_epoch.json"
            | "scientific_state_epoch.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ScientificStateEpoch);
    }
    if matches!(
        filename.as_str(),
        "dstw_t4_epoch_overlay.json" | "dstw_t4_epoch_overlay.jsonl"
    ) {
        return Some(QnanlArtifactFamily::T4EpochOverlay);
    }
    if matches!(
        filename.as_str(),
        "chronology_acceptance_decision.json"
            | "chronology_acceptance_decision.jsonl"
            | "scientific_chronology_acceptance_decision.json"
            | "scientific_chronology_acceptance_decision.jsonl"
    ) {
        return Some(QnanlArtifactFamily::ChronologyAcceptanceDecision);
    }
    if matches!(
        filename.as_str(),
        "scientific_chronology_manifest.json" | "scientific_chronology_manifest.jsonl"
    ) {
        return Some(QnanlArtifactFamily::JsonTelemetry);
    }
    if filename.contains("residue_map")
        || filename.contains("atom_to_residue")
        || filename.contains("chain_numbering")
        || filename.contains("residue_alignment")
        || filename.contains("numbering_ledger")
    {
        return Some(QnanlArtifactFamily::ResidueAlignmentMap);
    }
    if filename.contains("binding_site_physiology") || filename.contains("site_physiology") {
        return Some(QnanlArtifactFamily::BindingSitePhysiology);
    }
    if filename.contains("pocket_morphology")
        || filename.contains("geometric_pocket")
        || filename.contains("binding_site_morphology")
    {
        return Some(QnanlArtifactFamily::GeometricPocketMorphology);
    }
    if filename.contains("binding_sites")
        || filename.contains("site_candidates")
        || filename.contains("materialized_site")
        || filename.contains("site_materialization")
        || filename == "materialization_report.json"
        || filename == "validation_inputs.json"
        || filename == "site_accuracy_report.json"
        || filename == "materialization_field_completeness.json"
        || filename == "duplicate_cluster_report.json"
        || filename == "ranking_ablation_report.json"
    {
        return Some(QnanlArtifactFamily::BindingSiteMaterialization);
    }
    if filename.contains("kcc_visualization")
        || filename.contains("merged_kcc")
        || filename.contains("kcc_materialization")
    {
        return Some(QnanlArtifactFamily::KccMaterialization);
    }
    if filename.contains("spectral")
        || filename.contains("fiber_bundle")
        || filename.contains("phase_fiber")
        || filename.contains("manifold_tensor")
    {
        return Some(QnanlArtifactFamily::SpectralFiberBundle);
    }
    if filename.contains("movie_window")
        || filename.contains("movie_callable")
        || filename.contains("focus_plan")
        || filename.contains("site_window_index")
    {
        return Some(QnanlArtifactFamily::MovieCallableFocus);
    }
    if filename.contains("ccns") || filename.contains("sdst") {
        return Some(QnanlArtifactFamily::CcnsSdstSurface);
    }
    if filename.contains("prism_therm")
        || filename.contains("thermo_temporal")
        || filename.contains("thermodynamic_phase")
        || filename.contains("phase_state")
        || filename.contains("twin16")
    {
        return Some(QnanlArtifactFamily::ThermodynamicPhaseManifold);
    }
    if filename.contains("topology")
        || filename.contains("source_pdb")
        || filename.contains("source_mmcif")
        || filename.contains("config")
        || filename.contains("registry")
    {
        return Some(QnanlArtifactFamily::RunInputReference);
    }
    if ext == "sdf"
        || ext == "mol"
        || ext == "mol2"
        || ext == "smi"
        || ext == "smiles"
        || text.contains("molecule")
        || text.contains("candidate")
        || text.contains("cand_")
        || text.contains("sdf/")
        || text.contains("smiles")
        || text.contains("synthon")
        || text.contains("anchor")
        || text.contains("115k")
        || text.contains("design")
    {
        return Some(QnanlArtifactFamily::MoleculeDesignArtifact);
    }
    if text.contains("dstw")
        || text.contains("drf")
        || text.contains("nrf")
        || text.contains("gflownet")
        || text.contains("reward")
        || text.contains("meta_reward")
        || text.contains("multihead_student")
        || text.contains("super_student")
        || text.contains("chronology")
        || text.contains("neuromorphic")
        || text.contains("nanl")
        || text.contains("codec")
        || text.contains("forge")
    {
        return Some(QnanlArtifactFamily::DrfDstwForgeTensor);
    }
    if text.contains("postmd")
        || text.contains("post_md")
        || text.contains("teacher")
        || text.contains("student")
        || text.contains("tensor")
        || text.contains("phase_tile")
        || text.contains("phase_fiber")
        || text.contains("fiber")
        || text.contains("msm")
        || text.contains("kinetic")
        || text.contains("thermodynamic")
        || text.contains("occupancy")
        || text.contains("transition")
        || text.contains("timebase")
        || text.contains("raw_trajectory_spike")
        || text.contains("raw_spike")
    {
        return Some(QnanlArtifactFamily::PathBPostMdTensor);
    }
    None
}

fn encode_prismos_source_qnanl_artifacts(
    output: &Path,
    artifacts: &[QnanlSourceArtifact],
    streaming_threshold_bytes: u64,
    stream_large_artifacts: bool,
) -> PcResult<Value> {
    let packet_root = output.join("prismos_qnanl_source_artifacts");
    fs::create_dir_all(&packet_root)?;
    let mut receipts = Vec::new();
    let mut failures = Vec::new();
    let mut encoded_count_by_family = BTreeMap::<String, u64>::new();
    let mut source_kind_counts = BTreeMap::<String, u64>::new();
    let mut seen_artifact_ids = BTreeSet::<String>::new();

    for artifact in artifacts {
        let raw_bytes = fs::metadata(&artifact.path)
            .map(|meta| meta.len())
            .unwrap_or(0);
        let use_streaming = stream_large_artifacts && raw_bytes >= streaming_threshold_bytes;
        let artifact_id =
            unique_source_artifact_id(&artifact.path, artifact.family, &mut seen_artifact_ids);
        let family_dir = packet_root.join(artifact.family.as_str());
        fs::create_dir_all(&family_dir)?;
        let packet_path = family_dir.join(format!("{artifact_id}.prismqnanl"));
        let receipt_path = family_dir.join(format!("{artifact_id}.prismqnanl.receipt.json"));
        let options = QnanlEncodeOptions::runtime_inline(
            artifact_id,
            artifact.family,
            Some(artifact.path.clone()),
            "prismos::emit_runtime_qnanl_source_artifacts",
        );
        let result = if use_streaming {
            qnanl_artifact::encode_file_streaming(
                &artifact.path,
                &packet_path,
                &receipt_path,
                options,
            )
        } else {
            qnanl_artifact::encode_file(&artifact.path, &packet_path, &receipt_path, options)
        };
        match result {
            Ok(receipt) => {
                *encoded_count_by_family
                    .entry(receipt.artifact_family.as_str().to_string())
                    .or_insert(0) += 1;
                *source_kind_counts
                    .entry(artifact.source_kind.clone())
                    .or_insert(0) += 1;
                receipts.push(qnanl_source_receipt_value(
                    &receipt,
                    &artifact.source_kind,
                    if use_streaming {
                        "STREAMING"
                    } else {
                        "IN_MEMORY"
                    },
                ));
            }
            Err(e) => failures.push(j_obj(vec![
                ("path", j_str(artifact.path.display().to_string())),
                ("family", j_str(artifact.family.to_string())),
                ("source_kind", j_str(artifact.source_kind.clone())),
                (
                    "encoding_mode",
                    j_str(if use_streaming {
                        "STREAMING"
                    } else {
                        "IN_MEMORY"
                    }),
                ),
                ("error", j_str(e.to_string())),
            ])),
        }
    }

    let total_raw_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("raw_bytes").and_then(Value::as_u64))
        .sum();
    let total_packet_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("packet_bytes").and_then(Value::as_u64))
        .sum();
    let total_compressed_body_bytes: u64 = receipts
        .iter()
        .filter_map(|r| r.get("compressed_body_bytes").and_then(Value::as_u64))
        .sum();
    let compression_ratio_vs_raw = if total_packet_bytes > 0 {
        total_raw_bytes as f64 / total_packet_bytes as f64
    } else {
        0.0
    };
    let size_reduction_percent = if total_raw_bytes > 0 {
        100.0 * (1.0 - total_packet_bytes as f64 / total_raw_bytes as f64)
    } else {
        0.0
    };
    let all_roundtrips_verified = receipts.iter().all(|r| {
        r.get("roundtrip_verified")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    });
    let required_family_status =
        qnanl_required_source_family_status(&encoded_count_by_family, failures.is_empty());
    let required_families_pass = required_family_status
        .values()
        .all(|status| status == "PASS");
    let status = if failures.is_empty()
        && !receipts.is_empty()
        && all_roundtrips_verified
        && required_families_pass
    {
        "PASS"
    } else if failures.is_empty() && receipts.is_empty() {
        "NO_ELIGIBLE_ARTIFACTS"
    } else if failures.is_empty() {
        "PARTIAL"
    } else {
        "FAIL"
    };
    let summary = j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_qnanl_source_artifact_summary"),
        ),
        ("schema_version", j_num(1)),
        ("status", j_str(status)),
        ("packet_root", j_str(packet_root.display().to_string())),
        ("eligible_artifact_count", j_num(artifacts.len())),
        ("receipt_count", j_num(receipts.len())),
        ("failure_count", j_num(failures.len())),
        ("failures", j_array(failures)),
        (
            "encoded_count_by_family",
            j_u64_map(&encoded_count_by_family),
        ),
        ("source_kind_counts", j_u64_map(&source_kind_counts)),
        (
            "required_family_status",
            j_string_map(&required_family_status),
        ),
        ("total_raw_bytes", j_num(total_raw_bytes)),
        ("total_packet_bytes", j_num(total_packet_bytes)),
        (
            "total_compressed_body_bytes",
            j_num(total_compressed_body_bytes),
        ),
        (
            "compression_ratio_vs_raw",
            j_num(format!("{compression_ratio_vs_raw:.9}")),
        ),
        (
            "size_reduction_percent",
            j_num(format!("{size_reduction_percent:.9}")),
        ),
        ("all_roundtrips_verified", j_bool(all_roundtrips_verified)),
        ("stream_large_artifacts", j_bool(stream_large_artifacts)),
        (
            "streaming_threshold_bytes",
            j_num(streaming_threshold_bytes),
        ),
        ("receipts", j_array(receipts)),
    ]);
    fs::write(
        output.join("prismos_qnanl_source_artifact_summary.json"),
        summary.to_pretty_json(),
    )?;
    Ok(summary)
}

fn qnanl_source_receipt_value(
    receipt: &qnanl_artifact::QnanlArtifactReceipt,
    source_kind: &str,
    encoding_mode: &str,
) -> Value {
    let mut value = qnanl_receipt_value(receipt);
    if let Value::Object(map) = &mut value {
        map.insert("source_kind".to_string(), j_str(source_kind));
        map.insert("encoding_mode".to_string(), j_str(encoding_mode));
    }
    value
}

fn qnanl_required_source_family_status(
    counts: &BTreeMap<String, u64>,
    no_failures: bool,
) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for family in [
        "PATH_B_POST_MD_TENSOR",
        "DRF_DSTW_FORGE_TENSOR",
        "MOLECULE_DESIGN_ARTIFACT",
    ] {
        let count = counts.get(family).copied().unwrap_or(0);
        out.insert(
            family.to_string(),
            if no_failures && count > 0 {
                "PASS".to_string()
            } else {
                "MISSING_OR_FAIL".to_string()
            },
        );
    }
    out
}

fn unique_source_artifact_id(
    path: &Path,
    family: QnanlArtifactFamily,
    seen: &mut BTreeSet<String>,
) -> String {
    let mut base = sanitize_artifact_id(&format!(
        "{}_{}",
        family.as_str(),
        path.file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("artifact")
    ));
    let path_hash = blake3::hash(path.display().to_string().as_bytes())
        .to_hex()
        .to_string();
    if base.len() > 112 {
        base.truncate(112);
    }
    let mut id = format!("{}_{}", base, &path_hash[..16]);
    let original = id.clone();
    let mut idx = 1usize;
    while !seen.insert(id.clone()) {
        id = format!("{original}_{idx}");
        idx += 1;
    }
    id
}

fn sanitize_artifact_id(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-') {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn j_string_map(map: &BTreeMap<String, String>) -> Value {
    Value::Object(
        map.iter()
            .map(|(key, value)| (key.clone(), j_str(value.clone())))
            .collect(),
    )
}

fn canonical_science_codec_receipt_status(summary: &Value) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for required in [
        "PRISM_NANL_CANONICAL_CODEC_SCHEMA.json",
        "PRISM_NANL_CANONICAL_LAUNCH_MANIFEST.json",
        "PRISM_NRF_DSTW_CANONICAL_LAYER_MANIFEST.json",
        "PRISM_OS_NEUROMORPHIC_TIME_CODEC_MANIFEST.json",
    ] {
        out.insert(
            required.to_string(),
            if source_summary_has_receipt_for(summary, required) {
                "PASS".to_string()
            } else {
                "MISSING_OR_FAIL".to_string()
            },
        );
    }
    out
}

fn source_summary_has_receipt_for(summary: &Value, needle: &str) -> bool {
    let needle = needle.to_ascii_lowercase();
    let Some(Value::Array(receipts)) = summary.get("receipts") else {
        return false;
    };
    receipts.iter().any(|receipt| {
        let source_path = receipt
            .get("source_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        let packet_path = receipt
            .get("packet_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        let status = receipt.get("status").and_then(Value::as_str).unwrap_or("");
        let roundtrip = receipt
            .get("roundtrip_verified")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        status == "PASS"
            && roundtrip
            && (source_path.contains(&needle) || packet_path.contains(&needle))
    })
}

fn build_prismos_science_validation_surface(
    root: &Path,
    output: &Path,
    args: &RunMdArgs,
) -> PcResult<Value> {
    let science_roots = science_roots(root, args);
    let categories = vec![
        science_category_thermodynamic(&science_roots)?,
        science_category_temporal_timebase(&science_roots)?,
        science_category_kinetic(&science_roots)?,
        science_category_spectral_msm(&science_roots)?,
        science_category_phase_fiber(&science_roots)?,
        science_category_fused_tensor(&science_roots)?,
        science_category_teacher_student(&science_roots)?,
        science_category_gflownet(&science_roots)?,
        science_category_scientific_uncertainty_tensor(output, &science_roots)?,
    ];
    let all_pass = categories.iter().all(|category| {
        category
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("MISSING")
            == "PASS"
    });
    let claim_evidence_ledger = categories
        .iter()
        .map(|category| {
            j_obj(vec![
                (
                    "claim_family",
                    category
                        .get("evidence_class")
                        .cloned()
                        .unwrap_or_else(j_null),
                ),
                (
                    "claim_scope",
                    j_str("PRISM4D computational science evidence"),
                ),
                (
                    "status",
                    category.get("status").cloned().unwrap_or_else(j_null),
                ),
                (
                    "artifact_count",
                    j_num(
                        category
                            .get("artifacts")
                            .and_then(Value::as_array_len)
                            .unwrap_or(0),
                    ),
                ),
                (
                    "predicate_count",
                    j_num(
                        category
                            .get("predicates")
                            .and_then(Value::as_array_len)
                            .unwrap_or(0),
                    ),
                ),
            ])
        })
        .collect();
    let surface = j_obj(vec![
        (
            "schema_kind",
            j_str("prismos_science_validation_surface"),
        ),
        ("schema_version", j_num(1)),
        ("status", j_str(if all_pass { "PASS" } else { "PARTIAL" })),
        (
            "science_status_language",
            j_str(if all_pass {
                "PRISM4D_SCIENCE_VALIDATED_FOR_COMPUTATIONAL_EVIDENCE"
            } else {
                "PRISM4D_SCIENCE_EVIDENCE_PARTIAL"
            }),
        ),
        (
            "science_roots",
            j_array(
                science_roots
                    .iter()
                    .map(|path| j_str(path.display().to_string()))
                    .collect(),
            ),
        ),
        (
            "evidence_class_contract",
            j_string_array(&[
                "thermodynamic occupancy evidence is row-bound and hash-bound",
                "temporal and multirate timebase evidence is row-bound and hash-bound",
                "kinetic assignment evidence is row-bound and hash-bound",
                "spectral/MSM non-equilibrium evidence is row-bound and hash-bound",
                "phase/fiber and fused post-MD tensor evidence is row-bound and hash-bound",
                "teacher/student inference exports are bound to the fused tensor evidence",
                "GFlowNet generation and ranking evidence is bound to verified sampler summaries and reward exports",
                "ScientificUncertaintyTensor evidence is measured, source-hash-bound, provenance-bound, and SNR/uncertainty-consumption checked",
            ]),
        ),
        ("evidence_surfaces", j_array(categories)),
        ("claim_evidence_ledger", j_array(claim_evidence_ledger)),
        (
            "hard_failure_predicates",
            j_string_array(&[
                "any required science evidence artifact is missing",
                "any required science evidence artifact is zero bytes",
                "any required science evidence artifact cannot be hashed",
                "any required row-count predicate fails",
                "thermodynamic occupancy completion_status != SUCCESS",
                "timebase failed_row_count != 0",
                "kinetic row_count_1319 predicate missing or false",
                "MSM/spectral event_level_preserved != true",
                "fused tensor 1319_coverage != true",
                "teacher/student active metadata status missing",
                "GFlowNet gate_status != PASS",
                "GFlowNet runtime chemistry gate != true",
                "GFlowNet runtime chemistry invalid count > 0",
                "ScientificUncertaintyTensor measured uncertainty gate != PASS",
            ]),
        ),
    ]);
    fs::write(
        output.join("prismos_science_validation_surface.json"),
        surface.to_pretty_json(),
    )?;
    Ok(surface)
}

fn science_roots(root: &Path, args: &RunMdArgs) -> Vec<PathBuf> {
    if args.science_roots.is_empty() {
        vec![root.join("prism_postmd_superresolution")]
    } else {
        args.science_roots
            .iter()
            .map(|path| resolve_under(root, path))
            .collect()
    }
}

fn science_category_scientific_uncertainty_tensor(
    output: &Path,
    science_roots: &[PathBuf],
) -> PcResult<Value> {
    let mut roots = vec![output.to_path_buf()];
    roots.extend(science_roots.iter().cloned());
    let inspection = inspect_scientific_uncertainty_tensors(&roots)?;
    let status = inspection
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("MISSING_OR_FAIL");
    Ok(j_obj(vec![
        ("evidence_class", j_str("SCIENTIFIC_UNCERTAINTY_TENSOR")),
        (
            "description",
            j_str(
                "Measured runtime uncertainty tensors and ScientificEvent uncertainty-consumption evidence",
            ),
        ),
        ("status", j_str(status)),
        ("artifacts_pass", j_bool(status == "PASS")),
        ("predicates_pass", j_bool(status == "PASS")),
        (
            "artifacts",
            inspection
                .get("artifacts")
                .cloned()
                .unwrap_or_else(|| j_array(Vec::new())),
        ),
        (
            "predicates",
            j_array(vec![
                j_obj(vec![
                    (
                        "predicate",
                        j_str("scientific_uncertainty_core_valid_count > 0"),
                    ),
                    (
                        "actual",
                        inspection
                            .get("scientific_uncertainty_core_valid_count")
                            .cloned()
                            .unwrap_or_else(j_null),
                    ),
                    ("expected", j_str("> 0")),
                    (
                        "status",
                        j_str(
                            if inspection
                                .get("scientific_uncertainty_core_valid_count")
                                .and_then(Value::as_u64)
                                .unwrap_or(0)
                                > 0
                            {
                                "PASS"
                            } else {
                                "MISSING_OR_FAIL"
                            },
                        ),
                    ),
                ]),
                j_obj(vec![
                    (
                        "predicate",
                        j_str("signal_to_uncertainty_valid_count > 0"),
                    ),
                    (
                        "actual",
                        inspection
                            .get("signal_to_uncertainty_valid_count")
                            .cloned()
                            .unwrap_or_else(j_null),
                    ),
                    ("expected", j_str("> 0")),
                    (
                        "status",
                        j_str(
                            if inspection
                                .get("signal_to_uncertainty_valid_count")
                                .and_then(Value::as_u64)
                                .unwrap_or(0)
                                > 0
                            {
                                "PASS"
                            } else {
                                "MISSING_OR_FAIL"
                            },
                        ),
                    ),
                ]),
            ]),
        ),
        ("inspection", inspection),
    ]))
}

