    fn parse_defaults(output: &Path) -> HyperRuntimeMdCliArgs {
        let output = output.display().to_string();
        let cli = Cli::try_parse_from(["prismos", "hyper-runtime-md", "--output", output.as_str()])
            .expect("hyper-runtime-md defaults parse");
        match cli.command {
            Command::HyperRuntimeMd(args) => args,
            _ => panic!("expected hyper-runtime-md command"),
        }
    }

    #[test]
    fn native_client_intent_keeps_science_tokens_and_appends_only_bound_authority() {
        let native = NativeEngineIntentV1 {
            argv: vec!["--temperature".into(), "315".into(), "--replica-seed".into(), "73".into(),
                "--engine-surface".into(), "twin16+ghost-tiles".into()],
            normalized_arguments: BTreeMap::from([
                ("replica_seed".into(), vec!["73".into()]),
                ("multi_stream".into(), vec!["0".into()]),
                ("engine_surface".into(), vec!["twin16+ghost-tiles".into()]),
                ("path_a_max_wall_seconds".into(), vec!["180".into()]),
                ("prismcode_validation_level".into(), vec!["L3".into()]),
                ("save_trajectory_interval".into(), vec!["0".into()]),
                ("captured_graph_body_unroll".into(), vec!["1".into()]),
            ]),
            replicate: None,
            artifact_transport: Some(prismcode::hyper_runtime_request::ClientArtifactTransportV1 {
                prism_bundle_root: Some(PathBuf::from("/fixture/bundle")),
                qnanl_force_kernel_packet: Some(PathBuf::from("/fixture/kernel.prismqnanl")),
                qnanl_force_kernel_receipt: Some(PathBuf::from("/fixture/receipt.json")),
                science_roots: Some(vec![PathBuf::from("/fixture/science")]),
                ligand_mode: Some(ClientLigandModeV1::Holo), ..Default::default()
            }),
            transport_input_bindings: Vec::new(),
        };
        let mut generated = vec!["--temperature".into(), "100".into()];
        for flag in ["--expected-prismcode-packet-sha256", "--expected-prismcode-packet-hash-blake3",
            "--expected-source-epoch-id", "--expected-hyper-runtime-request-id", "--expected-engine-sha256",
            "--canonical-input", "--expected-input-sha256"] {
            generated.extend([flag.to_string(), "bound-identity".to_string()]);
        }
        let argv = canonical_native_launch_argv(&native, &generated).unwrap();
        assert_eq!(&argv[..native.argv.len()], native.argv.as_slice());
        assert!(!argv.iter().any(|value| value == "100"));
        let mut args = parse_defaults(Path::new("/tmp/intent-attempt"));
        apply_native_client_intent(&mut args, &native).unwrap();
        assert_eq!(args.replica_seed, 73);
        assert_eq!(args.multi_stream, 16);
        assert_eq!(args.engine_surface, HyperRuntimeEngineSurface::GhostTiles);
        assert_eq!(args.prism_bundle_root, Some(PathBuf::from("/fixture/bundle")));
        assert_eq!(args.qnanl_force_kernel_packet, Some(PathBuf::from("/fixture/kernel.prismqnanl")));
        assert_eq!(args.qnanl_force_kernel_receipt, Some(PathBuf::from("/fixture/receipt.json")));
        assert_eq!(args.science_roots, vec![PathBuf::from("/fixture/science")]);
        assert_eq!(args.ligand_mode, LigandMode::Holo);
        assert_eq!(args.max_wall_seconds, Some(180));
        assert_eq!(args.path_a_chunk_size, 500);
        assert_eq!(args.captured_graph_body_unroll, 1);
        assert_eq!(args.canonical_native_engine_intent.as_ref().unwrap().argv, native.argv);
        let run = hyper_runtime_md_run_args(&args).unwrap();
        assert!(run.typed_engine_arguments);
        assert_eq!(requested_trajectory_interval(&run), 0);
        assert!(canonical_native_launch_argv(&native, &generated[..generated.len()-2]).is_err());
        let mut forged = native.clone();
        forged.argv.push("--expected-engine-sha256=forged".into());
        assert!(canonical_native_launch_argv(&forged, &generated).is_err());
    }

