    #[test]
    fn native_client_tsh_side_inputs_reach_typed_preflight_without_science_rewrite() {
        let signature = format!("blake3:{}", "a".repeat(64));
        let native = NativeEngineIntentV1 {
            argv: vec!["--engine-surface".into(), "ghost-tiles+tsh-stage-ii".into(),
                "--tsh-uncertainty-tensor".into(), "/science/uncertainty-a.json".into(),
                "--tsh-uncertainty-tensor".into(), "/science/uncertainty-b.json".into(),
                "--tsh-negative-controls".into(), "/science/negative.json".into(),
                "--tsh-baseline-physics-signature".into(), signature.clone()],
            normalized_arguments: BTreeMap::from([
                ("engine_surface".into(), vec!["ghost-tiles+tsh-stage-ii".into()]),
                ("enable_tsh_stage_ii".into(), vec!["false".into()]),
                ("tsh_uncertainty_tensors".into(), vec!["/science/uncertainty-a.json".into(), "/science/uncertainty-b.json".into()]),
                ("tsh_negative_controls".into(), vec!["/science/negative.json".into()]),
                ("tsh_baseline_physics_signature".into(), vec![signature.clone()]),
                ("prismcode_validation_level".into(), vec!["L3".into()]),
            ]),
            replicate: None, artifact_transport: None, transport_input_bindings: Vec::new(),
        };
        let mut args = parse_defaults(Path::new("/tmp/tsh-intent-attempt"));
        apply_native_client_intent(&mut args, &native).unwrap();
        assert!(args.enable_tsh_stage_ii);
        assert_eq!(args.tsh_uncertainty_tensors, vec![PathBuf::from("/science/uncertainty-a.json"), PathBuf::from("/science/uncertainty-b.json")]);
        assert_eq!(args.tsh_negative_controls, Some(PathBuf::from("/science/negative.json")));
        assert_eq!(args.tsh_baseline_physics_signature.as_deref(), Some(signature.as_str()));
        let run = hyper_runtime_md_run_args(&args).unwrap();
        assert!(run.engine_args.iter().any(|token| token == "--enable-tsh-stage-ii"));
        assert_eq!(run.engine_args.iter().filter(|token| *token == "--tsh-uncertainty-tensor").count(), 2);
        let mut generated = Vec::new();
        for flag in ["--expected-prismcode-packet-sha256", "--expected-prismcode-packet-hash-blake3",
            "--expected-source-epoch-id", "--expected-hyper-runtime-request-id", "--expected-engine-sha256",
            "--canonical-input", "--expected-input-sha256"] {
            generated.extend([flag.to_string(), "bound-identity".to_string()]);
        }
        let argv = canonical_native_launch_argv(&native, &generated).unwrap();
        assert_eq!(&argv[..native.argv.len()], native.argv.as_slice());
        assert_eq!(args.canonical_native_engine_intent.as_ref().unwrap().normalized_arguments, native.normalized_arguments);
    }

    #[test]
    fn governed_branch_cli_is_one_strict_request_mode() {
        let cli = Cli::try_parse_from([
            "prismos",
            "hyper-runtime",
            "--governed-branch-selection",
            "/var/lib/prismos/cognition/branch/selection.json",
            "--request",
            "/var/lib/prismos/cognition/branch/request.json",
            "--plan",
        ])
        .expect("governed branch mode parses without raw engine authority");
        let Command::HyperRuntime(args) = cli.command else {
            panic!("expected hyper-runtime command");
        };
        assert!(args.execution_profile.is_none());
        assert!(args.target_id.is_none());
        assert!(args.output.is_none());
        assert!(args.client_surface.is_none());
        assert!(args.governed_branch_selection.is_some());
        assert!(args.request.is_some());
        assert!(args.plan);

        for missing_pair in [
            ["--governed-branch-selection", "/selection"],
            ["--request", "/request"],
        ] {
            let result =
                Cli::try_parse_from(["prismos", "hyper-runtime", missing_pair[0], missing_pair[1]]);
            assert!(result.is_err(), "accepted incomplete governed branch pair");
        }
        let direct = Cli::try_parse_from([
            "prismos",
            "hyper-runtime-md",
            "--governed-branch-selection",
            "/selection",
            "--request",
            "/request",
        ]);
        assert!(
            direct.is_err(),
            "raw Hyper-Runtime surface accepted branch mode"
        );
        let smuggled_profile = Cli::try_parse_from([
            "prismos",
            "hyper-runtime",
            "--governed-branch-selection",
            "/selection",
            "--request",
            "/request",
            "--execution-profile",
            "/caller-profile",
        ]);
        assert!(
            smuggled_profile.is_err(),
            "branch mode accepted caller-supplied profile identity"
        );
    }

    #[test]
    fn canonical_facade_delegates_through_existing_hyper_runtime_defaults() {
        let output = Path::new("/var/lib/prismos/runs/md/target-1");
        let baseline = hyper_runtime_md_run_args(&parse_defaults(output)).unwrap();
        let request = canonical_facade_request(output);
        assert_eq!(
            request
                .request
                .therm_and_post_md_policy
                .requested_post_md_aggregation,
            PostMdAggregationPolicyV1::Full
        );
        assert_eq!(
            canonical_hyper_runtime_post_md_engine_flag(
                &request
                    .request
                    .therm_and_post_md_policy
                    .effective_post_md_aggregation
            ),
            "--post-md-aggregation=full"
        );
        let facade = canonical_hyper_runtime_md_invocation(&request).unwrap();
        assert!(facade.args.engine_args.is_empty());
        assert!(facade.args.canonical_therm_and_post_md_policy.is_some());
        let delegated = hyper_runtime_md_run_args(&facade.args).unwrap();
        assert_eq!(delegated.max_wall_seconds, baseline.max_wall_seconds);
        assert_eq!(delegated.multi_stream, baseline.multi_stream);
        assert_eq!(delegated.fused_steps, baseline.fused_steps);
        assert_eq!(delegated.path_a_chunk_size, baseline.path_a_chunk_size);
        assert_eq!(
            delegated.captured_graph_body_unroll,
            baseline.captured_graph_body_unroll
        );
        assert_eq!(
            delegated.require_cuda_graph_native,
            baseline.require_cuda_graph_native
        );
        assert_eq!(delegated.metal_resident_md, baseline.metal_resident_md);
        assert_eq!(
            delegated.require_metal_resident_md,
            baseline.require_metal_resident_md
        );
        assert_eq!(
            delegated.require_hotpath_acceleration,
            baseline.require_hotpath_acceleration
        );
        assert!(delegated.engine_args.windows(2).any(|pair|
            pair == ["--engine-surface", "ghost-tiles"]));
        assert!(facade.args.require_v2_ignition);
        assert!(!delegated.engine_args.iter().any(|arg| arg.contains("governed-gearbox")));
        let (post_md_flag, therm_surface_flag) = resolved_hyper_runtime_therm_engine_flags(
            delegated.canonical_therm_and_post_md_policy.as_ref(),
        );
        assert_eq!(post_md_flag, "--post-md-aggregation=full");
        assert_eq!(therm_surface_flag, "--prism-therm-site-surface=lattice");
        assert_ne!(post_md_flag, "--md-only-evidence");
        assert_eq!(delegated.prismcode_backend, baseline.prismcode_backend);
        assert_eq!(
            delegated.prismcode_validation_level,
            baseline.prismcode_validation_level
        );
        assert!(delegated.expected_prismcode_packet_sha256.is_none());
        assert_eq!(
            facade.authority.request_id_sha256,
            request.request_id_sha256
        );
        assert_eq!(
            facade.authority.input_locator,
            request.request.input.locator
        );
        assert_eq!(facade.authority.input_sha256, request.request.input.sha256);
    }

