    #[test]
    fn direct_hyper_runtime_md_cli_rejects_every_governed_identity_field() {
        for field in [
            "--expected-prismcode-packet-sha256",
            "--expected-prismcode-packet-hash-blake3",
            "--expected-source-epoch-id",
            "--expected-hyper-runtime-request-id",
            "--expected-engine-sha256",
            "--canonical-input",
            "--expected-input-sha256",
        ] {
            let result = Cli::try_parse_from([
                "prismos",
                "hyper-runtime-md",
                "--output",
                "/tmp/raw-compatibility",
                field,
                "0",
            ]);
            assert!(result.is_err(), "direct CLI unexpectedly accepted {field}");
            for forwarded in [field.to_string(), format!("{field}={}", "0".repeat(64))] {
                let error = validate_hyper_runtime_engine_args(&[forwarded.clone()])
                    .expect_err("governed identity must not cross --engine-arg");
                assert!(error.to_string().contains("typed PrismOS option"));
                assert!(error.to_string().contains(field));
            }
            let error = validate_hyper_runtime_engine_args(&[field.to_string(), "0".repeat(64)])
                .expect_err("split governed identity must not cross --engine-arg");
            assert!(error.to_string().contains("typed PrismOS option"));
            assert!(error.to_string().contains(field));
        }
        let raw = hyper_runtime_md_run_args(&parse_defaults(Path::new("/tmp/raw"))).unwrap();
        assert!(raw.expected_prismcode_packet_sha256.is_none());
        assert!(raw.expected_prismcode_packet_hash_blake3.is_none());
        assert!(raw.expected_source_epoch_id.is_none());
        assert!(raw.expected_hyper_runtime_request_id.is_none());
        assert!(raw.expected_engine_sha256.is_none());
        assert!(raw.canonical_input_locator.is_none());
        assert!(raw.expected_input_sha256.is_none());
    }

    #[test]
    fn governed_input_locator_and_hash_fail_closed_before_native_launch() {
        let temporary = tempfile::tempdir().unwrap();
        let selected = temporary.path().join("selected.prmtop");
        let alternate = temporary.path().join("alternate.prmtop");
        fs::write(&selected, b"same bytes").unwrap();
        fs::write(&alternate, b"same bytes").unwrap();
        let sha256 = prismcode::operand_ledger::sha256_file_hex(&selected).unwrap();

        assert_eq!(
            verify_governed_input_identity(&selected, &selected, &sha256).unwrap(),
            selected
        );
        assert!(
            verify_governed_input_identity(&alternate, &selected, &sha256)
                .unwrap_err()
                .to_string()
                .contains("locator changed")
        );
        assert!(
            verify_governed_input_identity(&selected, &selected, &"0".repeat(64))
                .unwrap_err()
                .to_string()
                .contains("bytes changed")
        );
    }

