    #[test]
    fn strict_binding_sites_v3_preserves_ids_across_array_reordering() {
        let first = serde_json::json!({
            "sites": [
                strict_binding_site_fixture(73, 1, 3),
                strict_binding_site_fixture(5, 2, 4)
            ]
        });
        let reversed = serde_json::json!({
            "sites": [
                strict_binding_site_fixture(5, 2, 4),
                strict_binding_site_fixture(73, 1, 3)
            ]
        });
        let first = parse_strict_binding_sites_v3(&first, 8).expect("valid sites");
        let reversed = parse_strict_binding_sites_v3(&reversed, 8).expect("reordered sites");
        assert_eq!(first, reversed);
        assert_eq!(
            first
                .iter()
                .map(|site| (site.site_id, site.site_rank))
                .collect::<Vec<_>>(),
            vec![(5, 2), (73, 1)]
        );
    }

