    #[test]
    fn molecular_ghost_v4_rejects_aabb_inside_exact_distance_outside() {
        let geometry = strict_s4_geometry_fixture();
        let topology_b_sha256 = "a".repeat(64);
        let aabb_only = strict_s4_ghost_record_fixture(0, 9, 4, [5.0, 0.0, 0.0]);
        assert_eq!(
            strict_s4_aabb_separation(
                [5.0, 0.0, 0.0],
                [5.0, 0.0, 0.0],
                geometry.ligand_aabb_min,
                geometry.ligand_aabb_max,
            )
            .to_bits(),
            0.0f32.to_bits()
        );
        let (_, exact_distance) =
            strict_s4_nearest_heavy_atom([5.0, 0.0, 0.0], &geometry.ligand_heavy_atoms)
                .expect("exact heavy-atom distance");
        assert_eq!(exact_distance.to_bits(), 5.0f32.to_bits());
        let (components, witnesses) = recompute_strict_s4_ghost_witnesses_v4(
            &[aabb_only],
            &geometry,
            &topology_b_sha256,
            2.0,
        )
        .expect("AABB-only witness is parsed but not admitted");
        assert!(components.is_empty());
        assert!(witnesses.is_empty());
        let claimed_component = vec!["ghost-v2-stream1-frame0-site9".to_string()];
        let error = verify_strict_s4_ghost_witness_projection_v4(
            &claimed_component,
            &[],
            1,
            true,
            "engine_owned_native_v2_exact_witness_to_ligand_heavy_atom_distance_and_pocket_support_match",
            &components,
            &witnesses,
        )
        .expect_err("AABB overlap alone must never grant Ghost admission");
        assert!(error.to_string().contains("exact heavy-atom distance"));
    }

    #[test]
    fn molecular_ghost_v4_accepts_only_exact_witnesses_and_rejects_source_drift() {
        let geometry = strict_s4_geometry_fixture();
        let topology_b_sha256 = "a".repeat(64);
        let valid = strict_s4_ghost_record_fixture(0, 7, 1, [0.0, 0.5, 0.0]);
        let aabb_only = strict_s4_ghost_record_fixture(0, 9, 4, [5.0, 0.0, 0.0]);
        let (components, witnesses) = recompute_strict_s4_ghost_witnesses_v4(
            &[valid.clone(), aabb_only],
            &geometry,
            &topology_b_sha256,
            2.0,
        )
        .expect("exact witness recomputation");
        assert_eq!(components, vec!["ghost-v2-stream1-frame0-site7"]);
        assert_eq!(witnesses.len(), 1);
        assert_eq!(
            witnesses[0]
                .minimum_ligand_heavy_atom_distance_angstrom
                .to_bits(),
            0.5f32.to_bits()
        );
        verify_strict_s4_ghost_witness_projection_v4(
            &components,
            &witnesses,
            1,
            true,
            "engine_owned_native_v2_exact_witness_to_ligand_heavy_atom_distance_and_pocket_support_match",
            &components,
            &witnesses,
        )
        .expect("exact admitted witness");

        let mut drift_cases = Vec::new();
        let mut source_index = witnesses.clone();
        source_index[0].source_index += 1;
        drift_cases.push(source_index);
        let mut event_hash = witnesses.clone();
        event_hash[0].canonical_event_sha256 = "f".repeat(64);
        drift_cases.push(event_hash);
        let mut position = witnesses.clone();
        position[0].position[1] = 0.75;
        drift_cases.push(position);
        let mut support = witnesses.clone();
        support[0].support_residue_ids = vec![1];
        drift_cases.push(support);
        let mut duplicate = witnesses.clone();
        duplicate.push(witnesses[0].clone());
        drift_cases.push(duplicate);
        for drift in drift_cases {
            assert!(verify_strict_s4_ghost_witness_projection_v4(
                &components,
                &drift,
                drift.len() as u64,
                true,
                "engine_owned_native_v2_exact_witness_to_ligand_heavy_atom_distance_and_pocket_support_match",
                &components,
                &witnesses,
            )
            .is_err());
        }

        let duplicate_source = serde_json::json!({
            "frame_idx": 0,
            "site_id": 7,
            "aabb_min": [0.0, 0.5, 0.0],
            "aabb_max": [0.0, 0.5, 0.0],
            "source_event_witnesses": [
                valid["source_event_witnesses"][0].clone(),
                valid["source_event_witnesses"][0].clone()
            ]
        });
        assert!(recompute_strict_s4_ghost_witnesses_v4(
            &[duplicate_source],
            &geometry,
            &topology_b_sha256,
            2.0,
        )
        .is_err());
    }

