    #[test]
    fn coupled_topology_identity_is_hash_bound_and_fail_closed() {
        let tmp = tempfile::tempdir().unwrap();
        let topology_a = tmp.path().join("a.json");
        let topology_b = tmp.path().join("b.json");
        fs::write(&topology_a, b"{\"identity\":\"apo\"}\n").unwrap();
        fs::write(&topology_b, b"{\"identity\":\"holo\"}\n").unwrap();

        let distinct = resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_b),
            Some(MolecularContrastKind::ApoHolo),
            false,
            &[],
            COUPLED_CRYPTIC_SEARCH_OUTER_CUTOFF_ANGSTROM,
        )
        .expect("distinct pair is admitted")
        .expect("coupled identity exists");
        assert_ne!(distinct.topology_a_sha256, distinct.topology_b_sha256);

        let error = resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_b),
            Some(MolecularContrastKind::IdenticalTopologyNegativeControl),
            true,
            &[],
            COUPLED_CRYPTIC_SEARCH_OUTER_CUTOFF_ANGSTROM,
        )
        .expect_err("distinct pair cannot be labeled as identical control");
        assert!(error
            .to_string()
            .contains("rejects distinct input identities"));

        let error = resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_a),
            Some(MolecularContrastKind::ApoHolo),
            false,
            &[],
            COUPLED_CRYPTIC_SEARCH_OUTER_CUTOFF_ANGSTROM,
        )
        .expect_err("same-hash pair requires explicit negative control");
        assert!(error.to_string().contains("same-hash topology inputs"));

        let identical = resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_a),
            Some(MolecularContrastKind::IdenticalTopologyNegativeControl),
            true,
            &[],
            COUPLED_CRYPTIC_SEARCH_OUTER_CUTOFF_ANGSTROM,
        )
        .expect("explicit same-hash negative control is admitted")
        .expect("coupled identity exists");
        assert_eq!(identical.topology_a_sha256, identical.topology_b_sha256);
        assert!(identical.identical_topology_negative_control);

        let glycan = resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_b),
            Some(MolecularContrastKind::GlycanMechanisticProbe),
            false,
            &[380, 381, 382],
            12.0,
        )
        .expect("canonical multi-residue glycan probe is admitted")
        .expect("glycan coupled identity exists");
        assert_eq!(glycan.probe_residue_ids, vec![380, 381, 382]);
        assert_eq!(
            glycan.cryptic_search_outer_cutoff_angstrom.to_bits(),
            12.0f32.to_bits()
        );

        for probe_ids in [&[][..], &[381, 380][..], &[380, 380][..]] {
            assert!(resolve_coupled_topology_identity(
                tmp.path(),
                &topology_a,
                Some(&topology_b),
                Some(MolecularContrastKind::GlycanMechanisticProbe),
                false,
                probe_ids,
                12.0,
            )
            .is_err());
        }
        assert!(resolve_coupled_topology_identity(
            tmp.path(),
            &topology_a,
            Some(&topology_b),
            Some(MolecularContrastKind::GlycanMechanisticProbe),
            false,
            &[380],
            COUPLED_LIGAND_CONTACT_CUTOFF_ANGSTROM,
        )
        .is_err());
    }

    #[test]
    fn glycan_probe_candidate_accumulation_is_paired_annular_and_direct_shell_excluding() {
        let sha_a = "a".repeat(64);
        let sha_b = "b".repeat(64);
        let run_id = "glycan-probe-test";
        let map = |stream_id: u64, topology_sha256: &str, witnesses: serde_json::Value| {
            serde_json::json!({
                "schema_kind": "prismos.coupled_twin_ghost_site_map.v3",
                "schema_version": 2,
                "run_id": run_id,
                "stream_id": stream_id,
                "coordinate_frame": "topology_cartesian_angstrom",
                "topology_sha256": topology_sha256,
                "record_count": 1,
                "fallback_used": false,
                "records": [{
                    "evidence_available": true,
                    "spatial_native": true,
                    "frame_idx": 4,
                    "site_id": 9,
                    "source_event_witnesses": witnesses
                }]
            })
        };
        let map_a = map(
            0,
            &sha_a,
            serde_json::json!([{
                "source_index": 0,
                "canonical_event_sha256": "c".repeat(64),
                "position": [7.0, 0.0, 0.0],
                "support_residue_ids": [10, 20, 30]
            }]),
        );
        let map_b = map(
            1,
            &sha_b,
            serde_json::json!([{
                "source_index": 0,
                "canonical_event_sha256": "d".repeat(64),
                "position": [6.0, 0.0, 0.0],
                "support_residue_ids": [10, 20, 30]
            }, {
                "source_index": 1,
                "canonical_event_sha256": "e".repeat(64),
                "position": [8.0, 0.0, 0.0],
                "support_residue_ids": [40]
            }]),
        );
        let input_pose_annulus_minimum_distance_by_residue =
            BTreeMap::from([(30, 6.0f32), (40, 8.0f32)]);
        let mut accumulators = BTreeMap::new();
        for (stream_id, sha, map) in [(0, sha_a.as_str(), map_a), (1, sha_b.as_str(), map_b)] {
            accumulate_glycan_probe_candidates_v1(
                &map,
                stream_id,
                sha,
                run_id,
                &BTreeSet::from([10]),
                &input_pose_annulus_minimum_distance_by_residue,
                &mut accumulators,
            )
            .expect("accumulate exact paired annular witnesses");
        }
        assert_eq!(accumulators.len(), 2);
        let shared = &accumulators[&vec![30]];
        assert_eq!(shared.stream_a_witness_count, 1);
        assert_eq!(shared.stream_b_witness_count, 1);
        assert_eq!(
            shared
                .minimum_input_pose_probe_to_candidate_receptor_heavy_atom_distance_angstrom
                .map(f32::to_bits),
            Some(6.0f32.to_bits())
        );
        let probe_only = &accumulators[&vec![40]];
        assert_eq!(probe_only.stream_a_witness_count, 0);
        assert_eq!(probe_only.stream_b_witness_count, 1);
        assert!(!accumulators.contains_key(&vec![10]));
        assert!(!accumulators.contains_key(&vec![20]));
    }

    #[derive(Clone)]
    struct Prkcc001TestField {
        name: String,
        dtype: u8,
        bytes: Vec<u8>,
    }

    fn prkcc001_test_f32(name: &str, values: &[f32]) -> Prkcc001TestField {
        Prkcc001TestField {
            name: name.to_string(),
            dtype: 1,
            bytes: values
                .iter()
                .flat_map(|value| value.to_le_bytes())
                .collect(),
        }
    }

    fn prkcc001_test_u32(name: &str, values: &[u32]) -> Prkcc001TestField {
        Prkcc001TestField {
            name: name.to_string(),
            dtype: 2,
            bytes: values
                .iter()
                .flat_map(|value| value.to_le_bytes())
                .collect(),
        }
    }

    fn canonical_prkcc001_test_fields() -> Vec<Prkcc001TestField> {
        let ordinary = [0.25f32, -0.5, 0.75];
        vec![
            prkcc001_test_f32("temporal_corr", &ordinary),
            prkcc001_test_f32("direction_score", &ordinary),
            prkcc001_test_f32("motion_efficiency", &ordinary),
            prkcc001_test_f32("burst_motion", &ordinary),
            prkcc001_test_f32("phase_shift", &ordinary),
            prkcc001_test_f32("causal_lag", &[2.0, f32::NAN, -3.0]),
            prkcc001_test_f32("lag_corr_peak", &[0.75, f32::NAN, -0.5]),
            prkcc001_test_f32("local_cov", &ordinary),
            prkcc001_test_f32("net_dx", &ordinary),
            prkcc001_test_f32("net_dy", &ordinary),
            prkcc001_test_f32("net_dz", &ordinary),
            prkcc001_test_f32("sum_m", &ordinary),
            prkcc001_test_u32("residue_count", &[1, 2, 3]),
            prkcc001_test_u32("active_causal", &[1, 0, 1]),
        ]
    }

    fn set_prkcc001_test_f32(
        fields: &mut [Prkcc001TestField],
        name: &str,
        index: usize,
        value: f32,
    ) {
        let field = fields
            .iter_mut()
            .find(|field| field.name == name)
            .expect("test field exists");
        let start = index * 4;
        field.bytes[start..start + 4].copy_from_slice(&value.to_le_bytes());
    }

    fn build_prkcc001_test_carrier(fields: &[Prkcc001TestField]) -> Vec<u8> {
        let mut payload = Vec::new();
        payload.extend_from_slice(&3u64.to_le_bytes());
        payload.extend_from_slice(&(fields.len() as u64).to_le_bytes());
        for field in fields {
            payload.extend_from_slice(&(field.name.len() as u64).to_le_bytes());
            payload.extend_from_slice(field.name.as_bytes());
            payload.push(field.dtype);
            payload.extend_from_slice(&(field.bytes.len() as u64).to_le_bytes());
            payload.extend_from_slice(&field.bytes);
        }
        let mut carrier = Vec::new();
        carrier.extend_from_slice(b"PRKCC001");
        carrier.extend_from_slice(&1u32.to_le_bytes());
        carrier.extend_from_slice(&0x0102_0304u32.to_le_bytes());
        carrier.extend_from_slice(&0u32.to_le_bytes());
        carrier.extend_from_slice(&8u64.to_le_bytes());
        carrier.extend_from_slice(b"run-test");
        carrier.extend_from_slice(&6u64.to_le_bytes());
        carrier.extend_from_slice(b"target");
        carrier.extend_from_slice(&3u64.to_le_bytes());
        carrier.extend_from_slice(&4u64.to_le_bytes());
        carrier.extend_from_slice(&(payload.len() as u64).to_le_bytes());
        carrier.extend_from_slice(&payload);
        carrier.extend_from_slice(&coupled_prkcc001_fnv1a64(&payload).to_le_bytes());
        carrier.extend_from_slice(b"PRKCCEND");
        carrier
    }

    fn verify_prkcc001_test_carrier(carrier: &[u8]) -> PcResult<CoupledPrkcc001LagValidity> {
        verify_coupled_prkcc001_bytes(carrier, 0, "run-test", "target", 3)
    }

    #[test]
    fn coupled_prkcc001_accepts_finite_and_paired_nan_lags_without_byte_rewrite() {
        let carrier = build_prkcc001_test_carrier(&canonical_prkcc001_test_fields());
        let original = carrier.clone();
        let validity = verify_prkcc001_test_carrier(&carrier)
            .expect("paired-NaN unavailable lag semantics are valid");
        assert_eq!(validity.finite_pairs, 2);
        assert_eq!(validity.unavailable_pairs, 1);
        assert_eq!(validity.record_count, 3);
        assert_eq!(carrier, original);

        let tmp = tempfile::tempdir().unwrap();
        let path = tmp.path().join("target_stream0_kcc_v2full.bin");
        fs::write(&path, &carrier).unwrap();
        let receipt = verify_coupled_prkcc001_artifact(&path, 0, "run-test", "target", 3)
            .expect("path-bound immutable artifact passes");
        assert_eq!(
            receipt
                .get("paired_nan_unavailable_count")
                .and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            receipt
                .get("synthetic_zero_substitution")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(fs::read(path).unwrap(), original);
    }

