    #[test]
    fn coupled_prkcc001_rejects_malformed_field_lengths_and_schema() {
        let mut malformed_length = canonical_prkcc001_test_fields();
        malformed_length[0].bytes.truncate(8);
        let error = verify_prkcc001_test_carrier(&build_prkcc001_test_carrier(&malformed_length))
            .expect_err("every field must contain one value per residue");
        assert!(error.to_string().contains("length mismatch"));

        let mut missing_field = canonical_prkcc001_test_fields();
        missing_field.pop();
        let error = verify_prkcc001_test_carrier(&build_prkcc001_test_carrier(&missing_field))
            .expect_err("all fourteen PRKCC001 fields are mandatory");
        assert!(error.to_string().contains("payload shape mismatch"));

        let mut renamed_field = canonical_prkcc001_test_fields();
        renamed_field[0].name = "temporal_corz".to_string();
        let error = verify_prkcc001_test_carrier(&build_prkcc001_test_carrier(&renamed_field))
            .expect_err("field order and identity are binding");
        assert!(error.to_string().contains("identity mismatch"));

        let mut wrong_dtype = canonical_prkcc001_test_fields();
        wrong_dtype[0].dtype = 2;
        let error = verify_prkcc001_test_carrier(&build_prkcc001_test_carrier(&wrong_dtype))
            .expect_err("field dtype is binding");
        assert!(error.to_string().contains("dtype mismatch"));
    }

    #[test]
    fn coupled_prkcc001_rejects_checksum_drift_and_trailing_bytes() {
        let mut checksum_drift = build_prkcc001_test_carrier(&canonical_prkcc001_test_fields());
        let payload_byte = checksum_drift.len() - 17;
        checksum_drift[payload_byte] ^= 0x01;
        let error = verify_prkcc001_test_carrier(&checksum_drift)
            .expect_err("payload mutation must fail independent checksum validation");
        assert!(error.to_string().contains("checksum or trailer"));

        let mut trailing = build_prkcc001_test_carrier(&canonical_prkcc001_test_fields());
        trailing.push(0);
        let error = verify_prkcc001_test_carrier(&trailing)
            .expect_err("trailing carrier bytes must fail exact envelope length");
        assert!(error.to_string().contains("envelope length mismatch"));
    }

