        validate_coupled_run_md_contract(&md)
            .expect("standard cadence preserves the canonical coupled graph geometry");

        md.temporal_fidelity = TemporalFidelity::High;
        md.save_trajectory_interval = 0;
        let error = validate_coupled_run_md_contract(&md)
            .expect_err("high-fidelity auto-tightening below the graph floor must fail closed");
        let message = error.to_string();
        assert!(message.contains("effective_collapse=8"));
