    #[test]
    fn ghost_atomic_record_slot_order_is_not_semantic_site_order() {
        let occupied_clusters = vec![3, 11, 29];
        // Simulate atomic output slots arriving as semantic sites 2, 0, 1.
        let atomic_slot_site_ids = [2u32, 0, 1];
        let semantic_clusters = atomic_slot_site_ids
            .iter()
            .map(|site_id| {
                split_t7_topology_cluster_for_site(
                    &occupied_clusters,
                    *site_id,
                    "reordered Ghost record",
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        assert_eq!(semantic_clusters, vec![29, 3, 11]);
        let seen = atomic_slot_site_ids.into_iter().collect::<BTreeSet<_>>();
        assert!(split_t7_site_id_set_complete(
            &seen,
            occupied_clusters.len()
        ));

        let incomplete = [0u32, 2].into_iter().collect::<BTreeSet<_>>();
        assert!(!split_t7_site_id_set_complete(
            &incomplete,
            occupied_clusters.len()
        ));
        let error =
            split_t7_topology_cluster_for_site(&occupied_clusters, 3, "out-of-range Ghost record")
                .expect_err("out-of-range semantic site id must fail closed");
        assert!(error
            .to_string()
            .contains("exceeds the 3 occupied semantic sites"));
    }

    #[test]
    fn ghost_payload_rejects_nonzero_counter_padding_and_record_slack() {
        let record_count = 2usize;
        let mut payload = vec![
            0u8;
            COUPLED_GHOST_COUNTER_SECTOR_BYTES
                + record_count * COUPLED_GHOST_RECORD_BYTES
        ];
        payload[0..4].copy_from_slice(&(record_count as u32).to_le_bytes());
        payload[COUPLED_GHOST_COUNTER_SECTOR_BYTES + 12] = 1;
        payload[COUPLED_GHOST_COUNTER_SECTOR_BYTES + COUPLED_GHOST_RECORD_BYTES + 20] = 2;
        verify_coupled_ghost_zeroed_slack(&payload, record_count)
            .expect("defined Ghost record fields may be nonzero while all slack is zero");

        let mut stale_counter = payload.clone();
        stale_counter[4] = 1;
        let error = verify_coupled_ghost_zeroed_slack(&stale_counter, record_count)
            .expect_err("nonzero counter-sector padding must fail closed");
        assert!(error.to_string().contains("counter-sector padding"));

        let mut stale_record = payload;
        stale_record[COUPLED_GHOST_COUNTER_SECTOR_BYTES + COUPLED_GHOST_RECORD_USED_BYTES] = 1;
        let error = verify_coupled_ghost_zeroed_slack(&stale_record, record_count)
            .expect_err("nonzero record slack must fail closed");
        assert!(error.to_string().contains("record 0 slack"));
    }

    #[test]
    fn split_t7_c003_reconstructs_source_selection_and_rich_spikes() {
        let event = |timestep: i32, residue: i32, intensity: f32| {
            let mut bytes = [0u8; COUPLED_SPLIT_T7_SOURCE_EVENT_BYTES];
            bytes[0..4].copy_from_slice(&timestep.to_le_bytes());
            bytes[8..12].copy_from_slice(&(residue as f32 + 0.25).to_bits().to_le_bytes());
            bytes[12..16].copy_from_slice(&(residue as f32 + 0.5).to_bits().to_le_bytes());
            bytes[16..20].copy_from_slice(&(residue as f32 + 0.75).to_bits().to_le_bytes());
            bytes[20..24].copy_from_slice(&intensity.to_bits().to_le_bytes());
            bytes[24..28].copy_from_slice(&residue.to_le_bytes());
            for index in 1..8 {
                bytes[24 + index * 4..28 + index * 4].copy_from_slice(&(-1i32).to_le_bytes());
            }
            bytes[56..60].copy_from_slice(&1i32.to_le_bytes());
            bytes[60..64].copy_from_slice(&1i32.to_le_bytes());
            bytes[64..68].copy_from_slice(&280.0f32.to_bits().to_le_bytes());
            bytes[76..80].copy_from_slice(&0.4f32.to_bits().to_le_bytes());
            bytes[80..84].copy_from_slice(&0.8f32.to_bits().to_le_bytes());
            bytes[84..88].copy_from_slice(&2i32.to_le_bytes());
            bytes[88..92].copy_from_slice(&0.1f32.to_bits().to_le_bytes());
            bytes[92..96].copy_from_slice(&3u32.to_le_bytes());
            bytes
        };
        let event_bytes = [
            event(10, 0, 0.25),
            event(11, 1, 0.50),
            event(12, 2, 0.75),
            event(13, 3, 1.00),
            event(14, 4, 1.25),
        ];
        let mut source = b"PRISMOS_SPLIT_T7_SOURCE_EVENTS_V1\0".to_vec();
        source.extend_from_slice(&(event_bytes.len() as u64).to_le_bytes());
        for bytes in event_bytes {
            source.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
            source.extend_from_slice(&bytes);
        }
        let layout = SplitT7TopologyLayoutIdentity {
            sha256: "a".repeat(64),
            aabb_min: [0.0; 3],
            aabb_max: [5.0; 3],
            cell: [1.25; 3],
            role_aabb_min: [[0.0; 3], [f32::INFINITY; 3]],
            role_aabb_max: [[5.0; 3], [f32::NEG_INFINITY; 3]],
            residue_to_anchor_atom: vec![0, 1, 2, 3, 4],
            residue_to_cluster: vec![3, 2, 2, 1, 0],
            cluster_representative_residue: {
                let mut values = vec![u32::MAX; COUPLED_SPLIT_T7_CLUSTER_COUNT as usize];
                values[0] = 4;
                values[1] = 3;
                values[2] = 1;
                values[3] = 0;
                values
            },
            cluster_chain_role: vec![0; COUPLED_SPLIT_T7_CLUSTER_COUNT as usize],
            chain_offsets: [
                0,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
            ],
            residue_chain: vec![Some("A".to_string()); 5],
        };
        let events = parse_split_t7_source_events(&source, 5, "test source").unwrap();
        let indices = split_t7_full_span_indices(5, 4).unwrap();
        assert_eq!(indices, vec![0, 1, 2, 4]);
        let (rich, _, _, _) =
            reconstruct_split_t7_rich(&events, &indices, &layout, "test").unwrap();
        let selection = indices
            .iter()
            .flat_map(|index| index.to_le_bytes())
            .collect::<Vec<_>>();
        let mut envelope = vec![0u8; COUPLED_SPLIT_T7_FRAME_METADATA_BYTES];
        envelope[0..4].copy_from_slice(&7u32.to_le_bytes());
        envelope[4..12].copy_from_slice(&2048u64.to_le_bytes());
        envelope[12..16].copy_from_slice(&10i32.to_le_bytes());
        envelope[16..20].copy_from_slice(&14i32.to_le_bytes());
        envelope[20..24].copy_from_slice(&5u32.to_le_bytes());
        envelope[24..28].copy_from_slice(&4u32.to_le_bytes());
        envelope[28..36].copy_from_slice(&(source.len() as u64).to_le_bytes());
        envelope[36..44].copy_from_slice(&(selection.len() as u64).to_le_bytes());
        envelope[44..52].copy_from_slice(&(rich.len() as u64).to_le_bytes());
        envelope[52..116].copy_from_slice(sha256_bytes_hex(&source).as_bytes());
        envelope[116..180].copy_from_slice(sha256_bytes_hex(&rich).as_bytes());
        envelope.extend_from_slice(&source);
        let selection_offset = envelope.len();
        envelope.extend_from_slice(&selection);
        let rich_offset = envelope.len();
        envelope.extend_from_slice(&rich);
        let (parsed, cursor) = parse_split_t7_frame(&envelope, 0, 7, 4, &layout, "test C003")
            .expect("well-formed C003 frame must pass independent reconstruction");
        assert_eq!(cursor, envelope.len());
        assert_eq!(parsed.occupied_clusters, vec![0, 2, 3]);
        let cluster_three = parsed.witnesses_by_cluster.get(&3).unwrap();
        let witness_json = serde_json::json!([{
            "selected_ordinal": 0,
            "source_index": 0,
            "canonical_event_sha256": sha256_bytes_hex(&event_bytes[0]),
            "position": [0.25, 0.5, 0.75],
            "primary_residue_id": 0,
            "support_residue_ids": [0],
        }]);
        assert!(split_t7_source_witnesses_match(&witness_json, cluster_three).unwrap());
        let mut false_witness = witness_json;
        false_witness[0]["position"][0] = serde_json::json!(99.0);
        assert!(!split_t7_source_witnesses_match(&false_witness, cluster_three).unwrap());

        let mut bad_selection = envelope.clone();
        bad_selection[selection_offset + 4..selection_offset + 8]
            .copy_from_slice(&0u32.to_le_bytes());
        let error = parse_split_t7_frame(&bad_selection, 0, 7, 4, &layout, "bad selection")
            .expect_err("non-full-span selection must fail");
        assert!(error.to_string().contains("full-span selection"));

        let mut self_attested_rich = envelope;
        self_attested_rich[rich_offset + 20] ^= 0x01;
        let changed_hash =
            sha256_bytes_hex(&self_attested_rich[rich_offset..rich_offset + rich.len()]);
        self_attested_rich[116..180].copy_from_slice(changed_hash.as_bytes());
        let error = parse_split_t7_frame(
            &self_attested_rich,
            0,
            7,
            4,
            &layout,
            "self-attested RichSpike",
        )
        .expect_err("rehashing fabricated RichSpike bytes must not bypass reconstruction");
        assert!(error.to_string().contains("byte-exact reconstruction"));
    }

    #[test]
    fn split_t7_v3_independent_shadow_verifier_rejects_cross_frame_reassignment() {
        let mut event = [0u8; COUPLED_SPLIT_T7_SOURCE_EVENT_BYTES];
        event[0..4].copy_from_slice(&100i32.to_le_bytes());
        event[8..12].copy_from_slice(&0.25f32.to_bits().to_le_bytes());
        event[12..16].copy_from_slice(&0.50f32.to_bits().to_le_bytes());
        event[16..20].copy_from_slice(&0.75f32.to_bits().to_le_bytes());
        event[20..24].copy_from_slice(&0.5f32.to_bits().to_le_bytes());
        for index in 1..8 {
            event[24 + index * 4..28 + index * 4].copy_from_slice(&(-1i32).to_le_bytes());
        }
        event[56..60].copy_from_slice(&1i32.to_le_bytes());
        event[60..64].copy_from_slice(&2i32.to_le_bytes());
        event[64..68].copy_from_slice(&280.0f32.to_bits().to_le_bytes());
        event[76..80].copy_from_slice(&0.4f32.to_bits().to_le_bytes());
        event[80..84].copy_from_slice(&0.8f32.to_bits().to_le_bytes());
        event[84..88].copy_from_slice(&2i32.to_le_bytes());
        event[88..92].copy_from_slice(&0.1f32.to_bits().to_le_bytes());
        event[92..96].copy_from_slice(&3u32.to_le_bytes());
        let mut source = b"PRISMOS_SPLIT_T7_SOURCE_EVENTS_V1\0".to_vec();
        source.extend_from_slice(&1u64.to_le_bytes());
        source.extend_from_slice(&(event.len() as u32).to_le_bytes());
        source.extend_from_slice(&event);
        let source_sha256 = sha256_bytes_hex(&source);
        let layout = SplitT7TopologyLayoutIdentity {
            sha256: "a".repeat(64),
            aabb_min: [0.0; 3],
            aabb_max: [1.0; 3],
            cell: [0.25; 3],
            role_aabb_min: [[0.0; 3], [f32::INFINITY; 3]],
            role_aabb_max: [[1.0; 3], [f32::NEG_INFINITY; 3]],
            residue_to_anchor_atom: vec![0],
            residue_to_cluster: vec![0],
            cluster_representative_residue: {
                let mut values = vec![u32::MAX; COUPLED_SPLIT_T7_CLUSTER_COUNT as usize];
                values[0] = 0;
                values
            },
            cluster_chain_role: vec![0; COUPLED_SPLIT_T7_CLUSTER_COUNT as usize],
            chain_offsets: [
                0,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
                u32::MAX,
            ],
            residue_chain: vec![Some("A".to_string())],
        };
        verify_split_t7_shadow_source_v3(
            &mut std::io::Cursor::new(source.clone()),
            1,
            source.len() as u64,
            &source_sha256,
            0,
            100,
            &layout,
            "frame-zero canonical source",
        )
        .expect("completed-step timestamp 100 belongs to frame zero");
        let error = verify_split_t7_shadow_source_v3(
            &mut std::io::Cursor::new(source.clone()),
            1,
            source.len() as u64,
            &source_sha256,
            1,
            100,
            &layout,
            "frame-one reassignment",
        )
        .expect_err("rehashing the prior frame endpoint under frame one must fail closed");
        assert!(error
            .to_string()
            .contains("exact completed-step frame (100,200]"));
    }

