    #[test]
    fn named_profile_captured_graph_twin_selects_eight_stream_graph_dispatch() {
        let cli = Cli::try_parse_from([
            "prismos",
            "hyper-runtime-md",
            "--output",
            "/tmp/prismos-hyper-runtime-captured-dispatch",
            "--engine-surface",
            "captured-graph-twin",
        ])
        .expect("typed captured surface parses");
        let Command::HyperRuntimeMd(args) = cli.command else {
            panic!("expected hyper-runtime-md command");
        };
        assert_eq!(args.multi_stream, 8);
        assert_eq!(
            args.engine_surface.expected_dispatch(false),
            "captured_graph_twin_multi_stream"
        );
        assert!(hyper_runtime_md_run_args(&args)
            .expect("typed captured graph arguments resolve")
            .engine_args
            .windows(2)
            .any(|pair| pair == ["--engine-surface", "captured-graph-twin"]));

        let mut wrong_stream_count = args;
        wrong_stream_count.multi_stream = 7;
        let error = hyper_runtime_trust_preflight(&wrong_stream_count)
            .expect_err("captured graph TWIN must reject non-eight-stream requests");
        assert!(error.to_string().contains("requires exactly eight streams"));
    }

    // ── PACKAGE E ─────────────────────────────────────────────────────────

    fn package_e_hyper_runtime_args(extra: &[&str]) -> HyperRuntimeMdCliArgs {
        let mut argv = vec![
            "prismos",
            "hyper-runtime-md",
            "--output",
            "/tmp/prismos-package-e-test",
        ];
        argv.extend_from_slice(extra);
        let cli = Cli::try_parse_from(argv).expect("package E options parse");
        let Command::HyperRuntimeMd(args) = cli.command else {
            panic!("expected hyper-runtime-md command");
        };
        args
    }

    #[test]
    fn package_e_full_pipeline_requests_path_a_path_b_v2_and_live_gearbox() {
        let args = package_e_hyper_runtime_args(&["--full-pipeline"]);
        let admission = resolve_hyper_runtime_full_pipeline_admission(&args)
            .expect("--full-pipeline resolves on the default single-topology profile");
        assert_eq!(
            admission.engine_surface,
            HyperRuntimeEngineSurface::GhostTiles
        );
        assert!(admission.path_b_primary_surface);
        assert!(admission.require_v2_ignition);
        assert_eq!(
            admission.gearbox_liveness,
            GearboxLivenessRequirement::RequireActive
        );

        // Both surfaces must reach the engine from ONE invocation, and the
        // reserved orchestration flags must be forwarded from their typed
        // options rather than from --engine-arg.
        let md = hyper_runtime_md_run_args(&args)
            .expect("full-pipeline Hyper-Runtime arguments resolve");
        assert!(md
            .engine_args
            .windows(2)
            .any(|pair| pair == ["--engine-surface", "ghost-tiles+governed-gearbox"]));
        assert!(md
            .engine_args
            .iter()
            .any(|argument| argument == "--path-b-primary-surface=true"));

        let profile = hyper_runtime_profile_value(&args);
        let recorded = profile
            .get("full_pipeline_admission")
            .expect("profile records the resolved admission");
        assert_eq!(
            recorded.get("path_a_requested").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            recorded
                .get("path_b_primary_surface_requested")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            recorded
                .get("v2_ignition_required")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            recorded
                .get("gearbox_liveness_requirement")
                .and_then(Value::as_str),
            Some("require-active")
        );
    }

    #[test]
    fn package_e_full_pipeline_binds_native_v2_and_governor_evidence() {
        let tmp = tempfile::tempdir().expect("temporary native V2 run root");
        let output = tmp.path();
        let stream_count = 8usize;
        let stage_dir = output.join("pathb_runtime_stage");
        fs::create_dir(&stage_dir).expect("native V2 stage directory");

        // This generic root map is intentionally not an ignition proof.  The
        // acceptance path below must pass from the actual routing + native V2
        // stage artifacts, then fail when that routing evidence is withdrawn.
        fs::write(
            output.join("ghost_site_map.json"),
            br#"{"schema_kind":"pathb_ghost_site_map"}"#,
        )
        .expect("generic Ghost map fixture");

        let native_site_map_path = stage_dir.join("ghost_site_map.native_v2.json");
        let entries = (0..stream_count)
            .map(|stream_id| {
                serde_json::json!({
                    "component_id": format!("ghost-v2-stream{stream_id}-frame10-site1"),
                    "stream_id": stream_id,
                    "frame_idx": 10,
                    "site_id": 1,
                })
            })
            .collect::<Vec<_>>();
        let source_files = (0..stream_count)
            .map(|stream_id| serde_json::json!({"stream_id": stream_id}))
            .collect::<Vec<_>>();
        let native_site_map = serde_json::json!({
            "schema": "prismos.ghost_v2_native_site_map.v1",
            "schema_version": 2,
            "schema_kind": "pathb_ghost_v2_native_site_map",
            "status": "available_native_v2",
            "coordinate_frame": "topology_cartesian_angstrom",
            "source_file_count": stream_count,
            "source_files": source_files,
            "native_v2_event_count": entries.len(),
            "entries": entries,
        });
        fs::write(
            &native_site_map_path,
            serde_json::to_vec_pretty(&native_site_map).expect("native V2 map JSON"),
        )
        .expect("native V2 map fixture");
        let native_site_map_sha256 =
            prismcode::operand_ledger::sha256_file_hex(&native_site_map_path)
                .expect("native V2 map hash");
        let native_site_map_bytes = fs::metadata(&native_site_map_path)
            .expect("native V2 map metadata")
            .len();
        let compiler_receipt = serde_json::json!({
            "schema": "prismos.ghost_v2_native_site_map_compilation_receipt.v1",
            "status": "IMPLEMENTATION_VERIFIED",
            "gate_status": "PASS",
            "source_file_count": stream_count,
            "native_v2_event_count": stream_count,
            "output": {
                "path": native_site_map_path.display().to_string(),
                "sha256": native_site_map_sha256,
                "bytes": native_site_map_bytes,
                "schema": "prismos.ghost_v2_native_site_map.v1",
            },
            "checks": {
                "schema_v2_only": true,
                "spatial_native_bit_all_records": true,
                "finite_ordered_aabb_all_records": true,
                "centroid_midpoint_all_records": true,
                "event_count_nonzero": true,
                "component_identity_unique": true,
                "exact_file_and_byte_offset_provenance": true,
                "causal_driver_support_preserved_without_lining_relabel": true,
            },
        });
        fs::write(
            stage_dir.join("ghost_site_map.native_v2.receipt.json"),
            serde_json::to_vec_pretty(&compiler_receipt).expect("compiler receipt JSON"),
        )
        .expect("compiler receipt fixture");
        fs::write(
            output.join("prismos_runtime_pathb_stage_receipt.json"),
            serde_json::to_vec_pretty(&serde_json::json!({
                "schema_kind": "prismos_runtime_pathb_stage_receipt",
                "schema_version": 2,
                "status": "PASS",
                "runtime_native": true,
                "route": "REFERENCE_ONLY_GHOST_PHASE_LATTICE_DISCOVERY",
                "stream_count": stream_count,
                "native_v2_event_count": stream_count,
                "native_site_map_path": native_site_map_path.display().to_string(),
                "native_site_map": compiler_receipt,
            }))
            .expect("Path-B receipt JSON"),
        )
        .expect("Path-B receipt fixture");
        let routing = serde_json::json!({
            "schema_version": 1,
            "backend_request": "ghost-phase-lattice-4d",
            "v2_was_live": true,
            "v2_capture_requested": true,
            "lattice_run_status": "ok",
            "fallback_used": false,
            "n_nodes": 8,
        });
        fs::write(
            output.join("ghost_lattice_routing_status.json"),
            serde_json::to_vec_pretty(&routing).expect("routing JSON"),
        )
        .expect("routing fixture");
        for stream_id in 0..stream_count {
            let stem = format!("1JDH_stream{stream_id}");
            let decision_path = output.join(format!("{stem}_governor_decisions.jsonl"));
            fs::write(
                &decision_path,
                format!(
                    "{}\n",
                    serde_json::to_string(&serde_json::json!({
                        "schema": "prismos_physical_governor_decision",
                        "stream_id": stream_id,
                        "record_sequence": 1,
                        "actuation": {
                            "surface": "adj.gear_override@100",
                            "host_mutation": true,
                        },
                    }))
                    .expect("decision JSON")
                ),
            )
            .expect("decision fixture");
            fs::write(
                output.join(format!("{stem}_governor_closeout.json")),
                serde_json::to_vec_pretty(&serde_json::json!({
                    "stream_id": stream_id,
                    "decisions": 1,
                    "gear_transitions_emitted": 0,
                    "decision_stream": decision_path.display().to_string(),
                    "gear_transition_stream": output
                        .join(format!("{stem}_gear_transitions.jsonl"))
                        .display()
                        .to_string(),
                    "actuation": {
                        "surface": "adj.gear_override@100",
                        "applied": 1,
                        "unactuated": 0,
                        "governed_actuation_live": true,
                    },
                }))
                .expect("closeout JSON"),
            )
            .expect("closeout fixture");
        }

        let args = package_e_hyper_runtime_args(&["--full-pipeline"]);
        assert_eq!(
            hyper_runtime_full_pipeline_delivery_failure(output, &args)
                .expect("native V2 fixture has a resolved admission"),
            None,
        );

        // The root generic map remains present, but a false V2 routing fact
        // must fail: acceptance has no legacy-map fallback for V2 ignition.
        fs::write(
            output.join("ghost_lattice_routing_status.json"),
            serde_json::to_vec_pretty(&serde_json::json!({
                "schema_version": 1,
                "backend_request": "ghost-phase-lattice-4d",
                "v2_was_live": false,
                "v2_capture_requested": true,
                "lattice_run_status": "ok",
                "fallback_used": false,
                "n_nodes": 8,
            }))
            .expect("negative routing JSON"),
        )
        .expect("negative routing fixture");
        let failure = hyper_runtime_full_pipeline_delivery_failure(output, &args)
            .expect("failed V2 routing remains an admission result")
            .expect("invalid routing must fail closed");
        assert!(failure.contains("PRISMOS_V2_IGNITION_NOT_EVIDENCED"));
    }

    #[test]
    fn package_e_full_pipeline_conflicts_are_named_not_silently_overridden() {
        for (extra, needle) in [
            (
                vec!["--full-pipeline", "--engine-surface", "twin16"],
                "PRISMOS_FULL_PIPELINE_CONFLICT",
            ),
            (
                vec!["--full-pipeline", "--path-b-primary-surface=false"],
                "PRISMOS_FULL_PIPELINE_CONFLICT",
            ),
            (
                vec!["--full-pipeline", "--gearbox-liveness", "require-inactive"],
                "PRISMOS_FULL_PIPELINE_CONFLICT",
            ),
            (
                vec!["--require-v2-ignition", "--engine-surface", "twin16"],
                "PRISMOS_V2_IGNITION_UNREACHABLE",
            ),
        ] {
            let args = package_e_hyper_runtime_args(&extra);
            let error = resolve_hyper_runtime_full_pipeline_admission(&args)
                .expect_err("contradictory full-pipeline request must fail by name");
            assert!(
                error.to_string().contains(needle),
                "expected {needle} for {extra:?}, got {error}"
            );
        }
    }

    #[test]
    fn package_e_gearbox_liveness_requirement_implies_v2_ignition() {
        let args = package_e_hyper_runtime_args(&["--gearbox-liveness", "require-active"]);
        let admission = resolve_hyper_runtime_full_pipeline_admission(&args)
            .expect("require-active resolves on the Ghost/V2-capable default");
        assert!(
            admission.require_v2_ignition,
            "a live gearbox is only reachable through V2 ignition"
        );
        let md = hyper_runtime_md_run_args(&args).expect("typed demand maps to native argv");
        assert!(md.engine_args.windows(2).any(|pair|
            pair == ["--engine-surface", "ghost-tiles+governed-gearbox"]));

        let raw = hyper_runtime_md_run_args(&package_e_hyper_runtime_args(&[]))
            .expect("raw compatibility defaults resolve");
        assert!(!raw.engine_args.iter().any(|arg| arg.contains("governed-gearbox")));
        assert!(!raw.engine_args.iter().any(|arg| arg == "--gearbox"));
        assert!(hyper_runtime_md_run_args(&package_e_hyper_runtime_args(&[
            "--full-pipeline", "--gearbox-liveness", "require-inactive"
        ])).is_err());
    }

