    #[test]
    fn package_e_nonzero_gear_bit_mirrors_the_device_predicate_exactly() {
        // ghost_tile_kernel.cu:594 —
        //   (gear_id != 0u && gear_id != GHOST_V2_GEAR_ID_UNMEASURED) ? 0x0002u : 0u
        // Gear 0 is a legitimate 0.5 fs measurement and CLEARS the bit, exactly
        // as the not-measured sentinel does. A host check written as
        // `gear_id != 0` would reject every sentinel record the producer emits.
        assert!(!ghost_record_nonzero_gear_bit_expected(0));
        assert!(!ghost_record_nonzero_gear_bit_expected(
            COUPLED_GEAR_ID_UNMEASURED
        ));
        for gear in 1..=3u32 {
            assert!(
                ghost_record_nonzero_gear_bit_expected(gear),
                "gear {gear} must set the nonzero-gear witness bit"
            );
        }
        assert_eq!(COUPLED_GHOST_FCF_BIT_GEAR_MEASURED_NONZERO, 0x0002);
    }

    #[test]
    fn package_e_accepted_record_schemas_admit_the_live_kernel_version() {
        // The producing kernel writes GHOST_FRAME_SCHEMA_V3 into offset 128
        // (ghost_tile_kernel.cu:580). A gate pinned to the literal 2 rejects
        // 100% of live records.
        assert!(COUPLED_GHOST_ACCEPTED_RECORD_SCHEMAS.contains(&COUPLED_GHOST_FRAME_SCHEMA_V3));
        // V2 stays DEPRECATED-AND-REACHABLE.
        assert!(COUPLED_GHOST_ACCEPTED_RECORD_SCHEMAS.contains(&COUPLED_GHOST_FRAME_SCHEMA_V2));
        assert!(!COUPLED_GHOST_ACCEPTED_RECORD_SCHEMAS.contains(&1));
        assert!(!COUPLED_GHOST_ACCEPTED_RECORD_SCHEMAS.contains(&4));
    }

    /// Build one well-formed coupled-chronology record.
    #[allow(clippy::too_many_arguments)]
    fn package_e_ccr_record(
        step: u64,
        cumulative_ps: f64,
        dt_ps: f64,
        epoch: u64,
        snapshot: u64,
        flags: u32,
        requested: u32,
        authorized: u32,
        measured: u32,
        reason: u32,
        hmr: u32,
        seq: u64,
    ) -> Vec<u8> {
        let mut record = vec![0u8; COUPLED_CCR_RECORD_BYTES];
        let put_u64 = |record: &mut Vec<u8>, offset: usize, value: u64| {
            record[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
        };
        let put_u32 = |record: &mut Vec<u8>, offset: usize, value: u32| {
            record[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
        };
        put_u64(&mut record, COUPLED_CCR_OFF_GLOBAL_MD_STEP, step);
        put_u64(
            &mut record,
            COUPLED_CCR_OFF_CUM_SIM_TIME_PS,
            cumulative_ps.to_bits(),
        );
        put_u64(&mut record, COUPLED_CCR_OFF_DT_APPLIED_PS, dt_ps.to_bits());
        put_u64(&mut record, COUPLED_CCR_OFF_GEAR_EPOCH_ID, epoch);
        put_u64(&mut record, COUPLED_CCR_OFF_TENSOR_SNAPSHOT_ID, snapshot);
        put_u64(
            &mut record,
            COUPLED_CCR_OFF_TSH_SALIENCE_PER_PS,
            0.25f64.to_bits(),
        );
        put_u64(
            &mut record,
            COUPLED_CCR_OFF_OBSERVATION_CONF,
            0.9f64.to_bits(),
        );
        put_u32(
            &mut record,
            COUPLED_CCR_OFF_SCHEMA_VERSION,
            COUPLED_CCR_SCHEMA_VERSION,
        );
        put_u32(&mut record, COUPLED_CCR_OFF_RECORD_FLAGS, flags);
        put_u32(&mut record, COUPLED_CCR_OFF_REQUESTED_GEAR, requested);
        put_u32(&mut record, COUPLED_CCR_OFF_AUTHORIZED_GEAR, authorized);
        put_u32(&mut record, COUPLED_CCR_OFF_DEVICE_MEASURED_GEAR, measured);
        put_u32(&mut record, COUPLED_CCR_OFF_PHYSICAL_GUARD_STATUS, 0);
        put_u32(&mut record, COUPLED_CCR_OFF_TRANSITION_REASON, reason);
        put_u32(&mut record, COUPLED_CCR_OFF_HMR_VERIFIED, hmr);
        put_u32(&mut record, COUPLED_CCR_OFF_STREAM_ID, 0);
        put_u32(&mut record, COUPLED_CCR_OFF_REPLICA_ID, 0);
        put_u32(&mut record, COUPLED_CCR_OFF_EMITTER_TAG, 1);
        put_u32(
            &mut record,
            COUPLED_CCR_OFF_PUBLICATION_FENCE,
            COUPLED_CCR_FENCE_PUBLISHED,
        );
        put_u64(&mut record, COUPLED_CCR_OFF_RECORD_SEQ, seq);
        record
    }

    /// Three records: initialization at gear 1, a held interval, then an
    /// authorized downshift to gear 0. Stream ids 0 and replica 0 are
    /// legitimate values here, not sentinels.
    fn package_e_valid_chronology_records() -> Vec<Vec<u8>> {
        vec![
            package_e_ccr_record(
                0,
                0.0,
                0.0020,
                0,
                0,
                COUPLED_CCR_FLAG_DECISION_EXECUTED,
                1,
                1,
                1,
                1,
                COUPLED_CCR_HMR_NOT_APPLIED,
                0,
            ),
            package_e_ccr_record(
                100,
                0.2,
                0.0020,
                0,
                1,
                COUPLED_CCR_FLAG_GEAR_HELD | COUPLED_CCR_FLAG_DECISION_EXECUTED,
                1,
                1,
                1,
                COUPLED_CCR_REASON_HELD_NO_CHANGE,
                COUPLED_CCR_HMR_NOT_APPLIED,
                1,
            ),
            package_e_ccr_record(
                200,
                0.25,
                0.0005,
                1,
                2,
                COUPLED_CCR_FLAG_GEAR_CHANGED | COUPLED_CCR_FLAG_DECISION_EXECUTED,
                1,
                0,
                0,
                4,
                COUPLED_CCR_HMR_NOT_APPLIED,
                2,
            ),
        ]
    }

    fn package_e_write_chronology(
        directory: &Path,
        records: &[Vec<u8>],
    ) -> (PathBuf, serde_json::Value) {
        let payload: Vec<u8> = records.iter().flatten().copied().collect();
        let path = directory.join("coupled_chronology.ccr");
        fs::write(&path, &payload).expect("chronology stream writes");
        let map = serde_json::json!({
            COUPLED_CHRONOLOGY_MAP_PATH_KEY: path.display().to_string(),
            COUPLED_CHRONOLOGY_MAP_SHA256_KEY: sha256_bytes_hex(&payload),
            COUPLED_CHRONOLOGY_MAP_BYTES_KEY: payload.len(),
            COUPLED_CHRONOLOGY_MAP_RECORDS_KEY: records.len(),
            COUPLED_CHRONOLOGY_MAP_SCHEMA_KEY: COUPLED_CCR_SCHEMA_VERSION,
        });
        (path, map)
    }

    fn package_e_active_gearbox(measured: u32, requested: u32) -> CoupledGearboxLiveness {
        CoupledGearboxLiveness {
            active: true,
            expected_record_gear_id: measured,
            measured_gear_id: Some(measured),
            requested_gear_id: Some(requested),
            authorized_gear_id: Some(measured),
            gear_id_source: "device_measured_chronometric_state_tensor_current_gear".to_string(),
            authority: Some("physical_governor".to_string()),
            expected_gear_dt_fs: Some(0.5),
            hmr_applied: Some(false),
            hmr_source: None,
        }
    }

