        let tmp = tempfile::tempdir().unwrap();
        let path = tmp.path().join("legacy-receipt.json");
        fs::write(
            &path,
            br#"{"schema_kind":"receipt_projection","missing":NaN,"positive":Infinity,"negative":-Infinity,"text":"NaN"}"#,
        )
        .unwrap();
        let (receipt, normalization_count) =
            read_json_document_with_legacy_normalization(&path).unwrap();
        assert_eq!(normalization_count, 3);
