    #[test]
    fn md_attempt_output_rejects_prior_closeout_authority_without_deletion() {
        let tmp = tempfile::tempdir().expect("attempt output parent");
        let output = tmp.path().join("attempt");
        require_fresh_md_attempt_output(&output).expect("absent attempt root is fresh");
        fs::create_dir_all(output.join("OPERATOR_CONTROL"))
            .expect("operator control may pre-create an attempt root");
        require_fresh_md_attempt_output(&output)
            .expect("control-plane contents are not MD closeout authority");

        for receipt_name in [
            "prismos_md_run_receipt.json",
            "prismos_runtime_pathb_stage_receipt.json",
        ] {
            let receipt = output.join(receipt_name);
            fs::write(&receipt, b"{\"status\":\"PASS\"}\n").expect("write prior receipt fixture");
            let error = require_fresh_md_attempt_output(&output)
                .expect_err("prior closeout authority must reject a new native child launch");
            assert!(error
                .to_string()
                .contains("fresh attempt-scoped output root"));
            assert_eq!(
                fs::read(&receipt).expect("prior receipt remains preserved"),
                b"{\"status\":\"PASS\"}\n"
            );
            fs::remove_file(&receipt).expect("remove temporary fixture receipt");
        }

        let stale_native = output.join("stream00_prismcode_md_native_receipt.json");
        fs::write(&stale_native, b"{\"status\":\"PASS\"}\n")
            .expect("write stale native evidence fixture");
        let error = require_fresh_md_attempt_output(&output)
            .expect_err("stale native evidence cannot enter a fresh attempt");
        assert!(error.to_string().contains("non-control artifact"));
        assert_eq!(
            fs::read(&stale_native).expect("stale native evidence remains preserved"),
            b"{\"status\":\"PASS\"}\n"
        );
        fs::remove_file(&stale_native).expect("remove temporary stale native fixture");
    }

    #[test]
    fn md_attempt_output_reservation_is_exclusive_and_seals_uncertain_execution() {
        let tmp = tempfile::tempdir().expect("attempt reservation root");
        let output = tmp.path().join("attempt");
        fs::create_dir_all(&output).expect("create attempt root");
        let reservation_path = output.join(MD_ATTEMPT_OUTPUT_RESERVATION_FILE);

        {
            let first = MdAttemptOutputReservation::acquire(&output)
                .expect("first attempt acquires output reservation");
            assert!(reservation_path.is_file());
            assert!(qnanl_family_for_prismos_output(&reservation_path).is_none());
            assert!(first.attempt_id().starts_with("md-run-"));
            let competing_handle = File::open(&output).expect("open competing output handle");
            assert!(matches!(
                competing_handle.try_lock(),
                Err(std::fs::TryLockError::WouldBlock)
            ));
            let second = MdAttemptOutputReservation::acquire(&output)
                .expect_err("second attempt cannot claim the same output root");
            assert!(second
                .to_string()
                .contains("fresh attempt-scoped output root"));
            assert!(require_fresh_md_attempt_output(&output).is_err());
        }
        assert!(!reservation_path.exists());
        require_fresh_md_attempt_output(&output)
            .expect("pre-spawn reservation cleanup restores a fresh root");

        let mut launched = MdAttemptOutputReservation::acquire(&output)
            .expect("second lifecycle acquires output reservation");
        launched.mark_native_child_spawned();
        drop(launched);
        assert!(reservation_path.is_file());
        let error = require_fresh_md_attempt_output(&output)
            .expect_err("uncertain native execution keeps the root sealed");
        assert!(error
            .to_string()
            .contains("active or unreconciled md-run output reservation"));
    }

    #[test]
    fn native_engine_nonzero_closeout_writes_md_and_skipped_pathb_receipts() {
        let tmp = tempfile::tempdir().expect("closeout output directory");
        require_fresh_md_attempt_output(tmp.path()).expect("fresh closeout output");
        let mut reservation = MdAttemptOutputReservation::acquire(tmp.path())
            .expect("reserve closeout output before native child");
        let reservation_id = reservation.attempt_id().to_string();
        reservation.mark_native_child_spawned();
        let md_receipt_path = tmp.path().join("prismos_md_run_receipt.json");
        let pathb_receipt_path = tmp.path().join("prismos_runtime_pathb_stage_receipt.json");
        let process_launch = j_obj(vec![
            ("schema_kind", j_str("prismos_native_process_launch")),
            ("gpu_lease_required", j_bool(false)),
            ("arbiter_invoked", j_bool(false)),
            ("child_pid", j_num(4242)),
            ("child_wait_completed", j_bool(true)),
            ("engine_exit_code", j_num(2)),
        ]);
        let report = emit_native_engine_nonzero_closeout_receipts(
            &md_receipt_path,
            &pathb_receipt_path,
            tmp.path(),
            Path::new("/opt/prismos"),
            Path::new("/opt/prismos/bin/nhs_rt_full"),
            "aabbcc",
            4242,
            2,
            None,
            &reservation_id,
            &process_launch,
            true,
            &tmp.path().join("prismos_md_engine.stdout.log"),
            &tmp.path().join("prismos_md_engine.stderr.log"),
            &["--topology".to_string(), "1JDH.topology.json".to_string()],
            None,
        )
        .expect("nonzero closeout receipts publish");

        assert_eq!(report.get("status").and_then(Value::as_str), Some("FAIL"));
        assert_eq!(
            report.get("post_engine_emitters").and_then(Value::as_str),
            Some("SKIPPED_ENGINE_NONZERO")
        );
        assert_eq!(
            report
                .get("closeout_receipt_pair_publication")
                .and_then(Value::as_str),
            Some("PATHB_THEN_MD_NO_CLOBBER_DURABLY_PUBLISHED")
        );
        assert_eq!(
            report
                .get("attempt_output_reservation_id")
                .and_then(Value::as_str),
            Some(reservation_id.as_str())
        );
        let pathb = read_json_optional(&pathb_receipt_path);
        assert_eq!(pathb.get("status").and_then(Value::as_str), Some("SKIPPED"));
        assert_eq!(
            pathb.get("stage_execution").and_then(Value::as_str),
            Some("SKIPPED_ENGINE_NONZERO_BEFORE_PATHB_MATERIALIZATION")
        );
        assert_eq!(
            pathb
                .get("pathb_subprocess_launched")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            pathb
                .get("binding_sites_materialized")
                .map(|value| matches!(value, Value::Null)),
            Some(true)
        );
        assert_eq!(
            pathb
                .get("attempt_output_reservation_id")
                .and_then(Value::as_str),
            Some(reservation_id.as_str())
        );
        assert!(md_receipt_path.is_file());
        assert!(pathb_receipt_path.is_file());
        assert!(!tmp
            .path()
            .join("pathb_runtime_stage/binding_sites.materialized.json")
            .exists());
        reservation
            .release_after_terminal_receipt()
            .expect("terminal closeout releases the output reservation");
        assert!(!tmp.path().join(MD_ATTEMPT_OUTPUT_RESERVATION_FILE).exists());
        let error = require_fresh_md_attempt_output(tmp.path())
            .expect_err("completed closeout pair cannot become a new attempt");
        assert!(error
            .to_string()
            .contains("fresh attempt-scoped output root"));
    }

