#[cfg(test)]
mod isa_registry_summary_tests {
    use super::*;

    // Grouped-by-stream by-value invariants over the emitted records[] (INV-A/C/D).
    fn assert_invariants(summary: &Value) {
        let records = summary
            .get("records")
            .and_then(Value::as_array)
            .expect("records[] present");
        // group by stream_id
        let mut streams: BTreeMap<u64, Vec<&Value>> = BTreeMap::new();
        for r in records {
            let sid = r.get("stream_id").and_then(Value::as_u64).unwrap();
            streams.entry(sid).or_default().push(r);
        }
        let native_md_receipt_count = summary
            .get("native_md_receipt_count")
            .and_then(Value::as_u64)
            .unwrap();
        // INV-D: distinct(stream_id) == native_md_receipt_count
        assert_eq!(
            streams.len() as u64,
            native_md_receipt_count,
            "INV-D receipt fan-out"
        );
        for (sid, recs) in &streams {
            let registry_size = recs[0]
                .get("registry_size")
                .and_then(Value::as_u64)
                .unwrap();
            let distinct: BTreeSet<&str> = recs
                .iter()
                .map(|r| r.get("opcode").and_then(Value::as_str).unwrap())
                .collect();
            // INV-A: distinct(opcode) == count(records) == registry_size
            assert_eq!(
                recs.len() as u64,
                registry_size,
                "INV-A count (stream {sid})"
            );
            assert_eq!(
                distinct.len() as u64,
                registry_size,
                "INV-A distinct (stream {sid})"
            );
            // INV-C: every required_core record has observed == true
            for r in recs {
                if r.get("required_core").and_then(Value::as_bool).unwrap() {
                    assert!(
                        r.get("observed").and_then(Value::as_bool).unwrap(),
                        "INV-C required-core observed (stream {sid})"
                    );
                }
            }
        }
    }

    #[test]
    fn emitter_inline_shape_and_invariants() {
        let plan = j_obj(vec![
            (
                "md_prismops_known_instruction_set",
                j_array(vec![
                    j_str("MD.PROTOCOL_DIRECTOR"),
                    j_str("MD.COM_REMOVE"),
                    j_str("MD.FORCE_BONDED"),
                ]),
            ),
            (
                "md_prismops_required_core_contract",
                j_array(vec![
                    j_str("MD.PROTOCOL_DIRECTOR"),
                    j_str("MD.FORCE_BONDED"),
                ]),
            ),
        ]);
        let mk_stream = |a: u64, b: u64, c: u64| {
            j_obj(vec![
                ("status", j_str("PASS")),
                ("coverage_status", j_str("PASS")),
                (
                    "known_md_prismop_observation",
                    j_array(vec![
                        j_obj(vec![
                            ("opcode", j_str("MD.PROTOCOL_DIRECTOR")),
                            ("count", j_num(a)),
                            ("observed", j_bool(a > 0)),
                        ]),
                        j_obj(vec![
                            ("opcode", j_str("MD.COM_REMOVE")),
                            ("count", j_num(b)),
                            ("observed", j_bool(b > 0)),
                        ]),
                        j_obj(vec![
                            ("opcode", j_str("MD.FORCE_BONDED")),
                            ("count", j_num(c)),
                            ("observed", j_bool(c > 0)),
                        ]),
                    ]),
                ),
            ])
        };
        let verification = j_obj(vec![
            ("native_md_receipt_count", j_num(2u64)),
            (
                "streams",
                j_array(vec![mk_stream(452, 12, 100), mk_stream(461, 0, 108)]),
            ),
        ]);
        let summary = build_prismos_isa_registry_summary(&plan, &verification);
        assert_eq!(
            summary.get("schema_kind").and_then(Value::as_str),
            Some("prismos_prismcode_isa_registry_summary")
        );
        let records = summary.get("records").and_then(Value::as_array).unwrap();
        assert_eq!(records.len(), 6, "2 streams x 3 opcodes");
        assert_invariants(&summary);
    }

    // Emits the REAL apo_cryptic ISA registry summary from the on-laptop plan+verification when
    // present, asserts the by-value invariants on it, and (if PRISM_ISA_SUMMARY_OUT is set) writes
    // the Rust-emitted summary there so the corpus-compile matched_fields gate runs on genuine bytes.
    #[test]
    #[ignore = "HOST_DATA_REQUIRED: set PRISM_APO_CRYPTIC_MATRIX_DIR to the laptop_matrix/apo_cryptic artifact dir"]
    fn emitter_real_apo_cryptic_when_present() {
        let base = std::env::var("PRISM_APO_CRYPTIC_MATRIX_DIR")
            .expect("PRISM_APO_CRYPTIC_MATRIX_DIR must name the apo_cryptic artifact dir");
        let plan_p = Path::new(&base).join("prismos_prismcode_isa_execution_plan.json");
        let ver_p = Path::new(&base).join("prismos_prismcode_isa_execution_verification.json");
        assert!(
            plan_p.exists() && ver_p.exists(),
            "real apo_cryptic ISA artifacts not present under {base}"
        );
        let plan = read_json_optional(&plan_p);
        let verification = read_json_optional(&ver_p);
        let summary = build_prismos_isa_registry_summary(&plan, &verification);
        let records = summary.get("records").and_then(Value::as_array).unwrap();
        assert_eq!(records.len(), 200, "8 streams x 25 opcodes = 200 records");
        assert_eq!(
            summary.get("registry_size").and_then(Value::as_u64),
            Some(25)
        );
        assert_invariants(&summary);
        if let Ok(out) = std::env::var("PRISM_ISA_SUMMARY_OUT") {
            fs::write(&out, summary.to_pretty_json()).expect("write summary");
            eprintln!("wrote real ISA registry summary -> {out}");
        }
    }
}

#[cfg(test)]
mod spike_summary_tests {
    use super::*;

    // Build a synthetic PRSPK001 envelope with the given 96-byte records, sealed with the real
    // fnv1a-64 checksum + PRSPKEND trailer — exactly the layout decode_prspk001_spike_summary parses.
    fn build_prspk001(stream_id: u32, records: &[[u8; 96]]) -> Vec<u8> {
        let run_id = b"synthetic_run";
        let stem = b"4LPK_apo";
        let mut b: Vec<u8> = Vec::new();
        b.extend_from_slice(b"PRSPK001");
        b.extend_from_slice(&1u32.to_le_bytes()); // schema_version
        b.extend_from_slice(&0x0102_0304u32.to_le_bytes()); // endian_marker
        b.extend_from_slice(&stream_id.to_le_bytes());
        b.extend_from_slice(&(run_id.len() as u64).to_le_bytes());
        b.extend_from_slice(run_id);
        b.extend_from_slice(&(stem.len() as u64).to_le_bytes());
        b.extend_from_slice(stem);
        b.extend_from_slice(&(records.len() as u64).to_le_bytes()); // record_count
        b.extend_from_slice(&96u64.to_le_bytes()); // byte_stride
        b.extend_from_slice(&((records.len() * 96) as u64).to_le_bytes()); // payload_size
        let payload_off = b.len();
        for r in records {
            b.extend_from_slice(r);
        }
        // fnv1a-64 over the payload only
        let mut h: u64 = 0xcbf2_9ce4_8422_2325;
        for &x in &b[payload_off..] {
            h ^= x as u64;
            h = h.wrapping_mul(0x0000_0100_0000_01b3);
        }
        b.extend_from_slice(&h.to_le_bytes());
        b.extend_from_slice(b"PRSPKEND");
        b
    }

    fn rec(timestep: i32, intensity: f32, primary: i32, aromatic_type: i32) -> [u8; 96] {
        let mut r = [0u8; 96];
        r[0..4].copy_from_slice(&timestep.to_le_bytes());
        r[20..24].copy_from_slice(&intensity.to_le_bytes());
        r[24..28].copy_from_slice(&primary.to_le_bytes()); // nearby_residues[0]
        r[56..60].copy_from_slice(&1i32.to_le_bytes()); // n_residues
        r[68..72].copy_from_slice(&aromatic_type.to_le_bytes());
        r
    }

    #[test]
    fn decode_aggregates_by_residue_and_conserves_count() {
        // res 5: two spikes (frames 6,12; amp 40,60; arom -1 dominant, one code 2);
        // res 9: one spike (frame 8; amp 50; arom 4).
        let records = vec![
            rec(6, 40.0, 5, -1),
            rec(12, 60.0, 5, -1),
            rec(10, 30.0, 5, 2),
            rec(8, 50.0, 9, 4),
        ];
        let bytes = build_prspk001(3, &records);
        let summary = decode_prspk001_spike_summary("4LPK_apo_stream3_spikes.bin", &bytes)
            .expect("decode succeeds on a well-formed envelope");
        assert_eq!(
            summary.get("schema_kind").and_then(Value::as_str),
            Some("prismos_spike_event_native_summary")
        );
        assert_eq!(summary.get("stream_id").and_then(Value::as_u64), Some(3));
        let recs = summary.get("records").and_then(Value::as_array).unwrap();
        assert_eq!(recs.len(), 2, "two distinct primary residues");
        // COUNT CONSERVATION: Σ spike_count == record_count == 4.
        let total: u64 = recs
            .iter()
            .map(|r| r.get("spike_count").and_then(Value::as_u64).unwrap())
            .sum();
        assert_eq!(total, 4);
        assert_eq!(
            summary.get("total_spike_count").and_then(Value::as_u64),
            Some(4)
        );
        // res 5 record: count 3, dominant aromatic_type -1, max_amplitude 60, first 6, last 12.
        let r5 = recs
            .iter()
            .find(|r| r.get("residue_id").and_then(Value::as_f64) == Some(5.0))
            .unwrap();
        assert_eq!(r5.get("spike_count").and_then(Value::as_u64), Some(3));
        assert_eq!(r5.get("aromatic_type").and_then(Value::as_f64), Some(-1.0));
        assert_eq!(r5.get("first_frame").and_then(Value::as_u64), Some(6));
        assert_eq!(r5.get("last_frame").and_then(Value::as_u64), Some(12));
        let max_amp = r5.get("max_amplitude").and_then(Value::as_f64).unwrap();
        assert!((max_amp - 60.0).abs() < 1e-4);
    }

    #[test]
    fn corrupt_checksum_returns_none() {
        let records = vec![rec(6, 40.0, 5, -1)];
        let mut bytes = build_prspk001(0, &records);
        // Flip a payload byte AFTER sealing => checksum mismatch => honest-absent None.
        let payload_off = bytes.len() - 96 - 16; // 96 payload + 8 checksum + 8 trailer
        bytes[payload_off] ^= 0xFF;
        assert!(decode_prspk001_spike_summary("x_spikes.bin", &bytes).is_none());
    }

    #[test]
    fn wrong_magic_returns_none() {
        let mut bytes = build_prspk001(0, &[rec(6, 40.0, 5, -1)]);
        bytes[0] = b'X';
        assert!(decode_prspk001_spike_summary("x_spikes.bin", &bytes).is_none());
    }

    // REAL-BYTES gate (skipped if the laptop artifact is absent): decode the actual 133.9 MB
    // stream0 carrier and assert count conservation against the PRSPK001 header record_count.
    #[test]
    #[ignore = "HOST_DATA_REQUIRED: set PRISM_APO_CRYPTIC_MATRIX_DIR to the laptop_matrix/apo_cryptic artifact dir"]
    fn decode_real_apo_cryptic_stream0_if_present() {
        let base = std::env::var("PRISM_APO_CRYPTIC_MATRIX_DIR")
            .expect("PRISM_APO_CRYPTIC_MATRIX_DIR must name the apo_cryptic artifact dir");
        let p_buf = Path::new(&base).join("4LPK_apo_stream0_spikes.bin");
        let p = p_buf.as_path();
        assert!(p.exists(), "real apo_cryptic spikes.bin not present: {}", p.display());
        let bytes = fs::read(p).expect("read real spikes.bin");
        let summary =
            decode_prspk001_spike_summary("4LPK_apo_stream0_spikes.bin", &bytes).expect("decode");
        let recs = summary.get("records").and_then(Value::as_array).unwrap();
        let total: u64 = recs
            .iter()
            .map(|r| r.get("spike_count").and_then(Value::as_u64).unwrap())
            .sum();
        assert_eq!(
            total, 1_394_939,
            "Σ per-residue spike_count == header record_count"
        );
        assert_eq!(
            summary.get("total_spike_count").and_then(Value::as_u64),
            Some(1_394_939)
        );
        // Residue-range invariant: every residue_id in [0, 155] (0-indexed 156-residue topology).
        for r in recs {
            let rid = r.get("residue_id").and_then(Value::as_f64).unwrap() as i64;
            assert!((0..=155).contains(&rid), "residue_id {rid} out of [0,155]");
        }
    }
}


#[cfg(test)]
mod durable_bootstrap_tests {
    use super::*;
    #[test]
    fn bootstrap_accepts_only_bound_publication_population() {
        let tmp = tempfile::tempdir().unwrap();
        require_durable_bootstrap_population(tmp.path()).unwrap();
        for name in ["PRISMOS_HYPER_RUNTIME_REQUEST.json.publication.lock", "PRISMOS_HYPER_RUNTIME_REQUEST.json.tmp.123.456.0"] {
            fs::write(tmp.path().join(name), b"").unwrap();
        }
        require_durable_bootstrap_population(tmp.path()).unwrap();
        fs::write(tmp.path().join("stale_previous_run.json"), b"retained").unwrap();
        assert!(require_durable_bootstrap_population(tmp.path()).is_err());
        fs::remove_file(tmp.path().join("stale_previous_run.json")).unwrap();
        #[cfg(unix)] {
            std::os::unix::fs::symlink("/etc/passwd", tmp.path().join("PRISMOS_HYPER_RUNTIME_REQUEST.json")).unwrap();
            assert!(require_durable_bootstrap_population(tmp.path()).is_err());
        }
    }
}

#[cfg(test)]
mod continuation_recovery_consumer_tests {
    use super::*;
    #[test]
    fn actual_sweep_and_source_classifier_retain_only_active_publication_population() {
        let root = tempfile::tempdir().unwrap();
        let active = root.path().join("active_spikes.bin");
        fs::write(&active, b"active native event bytes").unwrap();
        let names = [".continuation_tails/retained_spikes.bin", ".continuation_absent_owners/generation/payload/future_spikes.bin",
            "active_spikes.bin.uncommitted.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.19.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", "active_spikes.bin.uncommitted.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.19.next"];
        for name in names {
            let path = root.path().join(name);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, b"retained later native event bytes").unwrap();
            assert!(qnanl_family_for_prismos_output(&path).is_none());
            assert!(skip_source_artifact_file(&path));
        }
        assert!(skip_artifact_dir(&root.path().join(".continuation_absent_owners")));
        assert_eq!(collect_runtime_output_files(root.path(), 8).unwrap(), vec![active.clone()]);
        assert_eq!(qnanl_family_for_prismos_output(&active), Some(QnanlArtifactFamily::EventStream));
        assert!(!skip_source_artifact_file(&active));
        // An explicit source alias cannot bypass recovery exclusion through a
        // default family after canonical source resolution.
        let alias = root.path().join("alias_spikes.bin");
        std::os::unix::fs::symlink(root.path().join(names[0]), &alias).unwrap();
        let mut sources = BTreeMap::new();
        insert_source_artifact(root.path(), &root.path().join("fresh_output"), &alias,
            "test-explicit-source", Some(QnanlArtifactFamily::EventStream), &mut sources).unwrap();
        assert!(sources.is_empty());
        // Exclusion preserves the later observations in place for recovery/QC.
        for name in names { assert_eq!(fs::read(root.path().join(name)).unwrap(), b"retained later native event bytes"); }
    }
}
